  function chooseStickerCoverCandidate(group, candidates = []) {
    return new Promise(resolve => {
      const overlay = document.createElement("div");
      overlay.className = "modal-backdrop";
      overlay.innerHTML = `<div class="modal sticker-trade-picker"><div class="section-head"><div><div class="eyebrow">Doação administrativa</div><h2>Escolha a imagem da figurinha</h2><div class="section-subtitle">Selecione uma capa disponível ou use um link HTTPS.</div></div><button type="button" class="small-btn" data-close>Fechar</button></div><div class="sticker-trade-picker-grid">${candidates.map((candidate, index) => `<button type="button" class="sticker-trade-choice" data-cover-candidate="${index}"><span class="sticker-trade-choice-art"><img src="${escapeHTML(proxiedImageUrl(candidate.url))}" alt="Capa de ${escapeHTML(group.characterName)}" draggable="false"></span><strong>${escapeHTML(state.db.library.find(item => String(item.id) === String(candidate.itemId))?.title || group.characterName)}</strong><small>${index === 0 ? "Capa disponível" : "Capa variante"}</small></button>`).join("")}</div><div class="field sticker-cover-link-field"><label for="admin-sticker-cover-url">Ou usar imagem por link</label><div class="inline-form"><input id="admin-sticker-cover-url" type="url" placeholder="https://exemplo.com/imagem.jpg" autocomplete="off"><button type="button" class="small-btn" data-use-cover-link>Usar link</button></div><small>O link precisa começar com https://.</small></div><div class="modal-actions"><button type="button" class="small-btn" data-close>Cancelar</button><button type="button" class="btn btn-danger" data-send-cover disabled>Usar esta imagem</button></div></div>`;
      $("#modal-root").appendChild(overlay);
      let selectedIndex = null;
      const close = value => { overlay.remove(); resolve(value); };
      const coverGrid = $(".sticker-trade-picker-grid", overlay);
      const linkControls = $(".inline-form", overlay);
      if (linkControls) {
        linkControls.classList.add("sticker-cover-link-controls");
        linkControls.style.justifyContent = "flex-end";
      }
      $$('[data-close]', overlay).forEach(button => button.addEventListener("click", () => close(null)));
      overlay.addEventListener("click", event => { if (event.target === overlay) close(null); });
      $$('[data-cover-candidate]', overlay).forEach(button => button.addEventListener("click", () => {
        selectedIndex = Number(button.dataset.coverCandidate);
        coverGrid.hidden = false;
        $('[data-use-cover-link]', overlay).classList.remove("is-selected");
        $('[data-send-cover]', overlay).dataset.customCoverUrl = "";
        $$('[data-cover-candidate]', overlay).forEach(item => item.classList.toggle("is-selected", item === button));
        $('[data-send-cover]', overlay).disabled = false;
      }));
      $('[data-use-cover-link]', overlay).addEventListener("click", () => {
        const url = $('[name="admin-sticker-cover-url"]', overlay)?.value.trim() || $("#admin-sticker-cover-url", overlay)?.value.trim() || "";
        if (!/^https:\/\//i.test(url)) return toast("Informe um link HTTPS válido para a imagem.");
        $$('[data-cover-candidate]', overlay).forEach(item => item.classList.remove("is-selected"));
        selectedIndex = null;
        coverGrid.hidden = true;
        $('[data-use-cover-link]', overlay).classList.add("is-selected");
        $('[data-send-cover]', overlay).disabled = false;
        $('[data-send-cover]', overlay).dataset.customCoverUrl = url;
      });
      $('[data-send-cover]', overlay).addEventListener("click", () => {
        const customUrl = $('[data-send-cover]', overlay).dataset.customCoverUrl || "";
        close(customUrl ? { itemId: group.items[0]?.id, url: customUrl } : (candidates[selectedIndex] || null));
      });
    });
  }

  function askStickerDiscardConfirmation() {
    return new Promise(resolve => {
      const overlay = document.createElement("div");
      overlay.className = "modal-backdrop";
      overlay.innerHTML = `<div class="modal sticker-discard-confirm-modal"><div class="section-head"><div><div class="eyebrow">Álbum de figurinhas</div><h2>Descartar figurinha?</h2><div class="section-subtitle">Essa figurinha repetida será removida permanentemente e não poderá ser recuperada.</div></div></div><div class="modal-actions"><button type="button" class="small-btn" data-close>Manter figurinha</button><button type="button" class="btn btn-danger" data-confirm-discard>Descartar</button></div></div>`;
      $("#modal-root").appendChild(overlay);
      const finish = value => { overlay.remove(); resolve(value); };
      $$('[data-close]', overlay).forEach(button => button.addEventListener("click", () => finish(false)));
      overlay.addEventListener("click", event => { if (event.target === overlay) finish(false); });
      $('[data-confirm-discard]', overlay).addEventListener("click", () => finish(true));
    });
  }

  async function requestSticker(characterId, ownerId, type) {
    if (!state.session) return openAuthPage();
    const group = stickerGroups().find(entry => entry.id === characterId);
    const ownerAwards = state.publicProfile?.stickerAwards || [];
    const target = ownerAwards.find(award => award.character_id === characterId) || (state.publicProfile?.profile?.id === ownerId ? currentStickerAwards(state.stickerAwards).get(characterId) : null);
    if (!group || !target) return toast("Esta figurinha não está disponível no álbum.");
    let offeredAwardIds = [];
    if (type === "trade") {
      const offerable = (state.stickerAwards || []).filter(award => award.id !== target.id);
      if (!offerable.length) return toast("Você precisa ter outra figurinha para oferecer.");
      offeredAwardIds = await chooseStickerForTrade(offerable);
      if (!offeredAwardIds.length) return;
    }
    const result = await sb.rpc("create_sticker_request", { p_owner_id: ownerId, p_character_id: characterId, p_character_name: group.characterName, p_edition_fingerprint: stickerFingerprint(group), p_request_type: type, p_offered_award_id: offeredAwardIds[0] || null, p_offered_award_id_2: offeredAwardIds[1] || null });
    if (result.error) return toast(result.error.message || "Não foi possível enviar o pedido.");
    toast(type === "trade" ? "Proposta de troca enviada." : "Pedido de doação enviado.");
  }

  function toggleReadingCompleted(item, totalPages = progressFor(item)?.total_pages || 1) {
    if (!state.session || !sb || item?.local) return;
    const current = progressFor(item);
    const completed = !current?.completed;
    const row = { user_id: state.session.user.id, item_id: item.id, page: current?.page || 1, total_pages: totalPages, completed, completion_source: completed ? "manual" : null, updated_at: new Date().toISOString() };
    state.readingProgress.set(item.id, row);
    if (row.completed) rememberShelfItem("read", item.id);
    updateCompletionCards(item, row.completed);
    if (row.completed && isSeriesCompleted(item)) { awardAchievement("first_completed"); awardAchievement("five_completed"); }
    const result = sb.from("reading_progress").upsert(row, { onConflict: "user_id,item_id" });
    result.then(response => { if (response.error) console.warn("NÃ£o foi possÃ­vel atualizar o status de leitura:", response.error.message); });
    const nextCompleted = row.completed;
    result.then(response => { if (response.error) console.warn("Não foi possível atualizar o status de leitura:", response.error.message); });
    return nextCompleted;
  }

  const coverMemoryCache = new Map();
  const coverLoading = new Map();
  const coverAbortControllers = new Map();
  let deferredCoverObserver = null;
  let homeHeroReady = true;
  let coverLoadGeneration = 0;

  function cancelCoverLoads() {
    coverLoadGeneration += 1;
    homeHeroReady = true;
    deferredCoverObserver?.disconnect();
    deferredCoverObserver = null;
    for (const controller of coverAbortControllers.values()) controller.abort();
    coverAbortControllers.clear();
    coverLoading.clear();
    $$('[data-cover-id]').forEach(element => {
      const isHero = element.classList.contains("hero-bg") || element.classList.contains("hero-cover");
      const maxWidth = isHero ? coverMaxWidthForViewport() : 480;
      if (!coverMemoryCache.has(`${element.dataset.coverId}:${maxWidth}`)) element.dataset.coverReady = "";
    });
  }

  function setReadingMode(mode) {
    state.readingMode = mode;
    localStorage.setItem("readingMode", mode);
  };

  function setReadingDirection(direction) {
    state.readingDirection = direction;
    localStorage.setItem("readingDirection", direction);
  }

  const $ = (sel, root = document) => root?.querySelector?.(sel) || null;
  const $$ = (sel, root = document) => root?.querySelectorAll ? [...root.querySelectorAll(sel)] : [];

  function escapeHTML(value = "") {
    return String(value).replace(/[&<>"']/g, c => ({
      "&":"&amp;", "<":"&lt;", ">":"&gt;", '"':"&quot;", "'":"&#039;"
    }[c]));
  }

  function decodeNewsText(value = "") {
    let text = String(value);
    if (/[ÃÂâ]/.test(text)) {
      try {
        text = new TextDecoder("utf-8").decode(Uint8Array.from(text, char => char.charCodeAt(0)));
      } catch {}
    }
    return text
      .replace(/&#0?39;/gi, "'")
      .replace(/&#0?34;/gi, '"')
      .replace(/&amp;/gi, "&")
      .replace(/&lt;/gi, "<")
      .replace(/&gt;/gi, ">")
      .replace(/Â·/g, "·")
      .replace(/â€™/g, "’")
      .replace(/â€œ|â€/g, '"')
      .replace(/â€“|â€”/g, "–")
      .replace(/â€¢|âœ•/g, "•")
      .replace(/Ã—/g, "×")
      .replace(/â€¦/g, "…");
  }

  function getSpreadIndexes(totalPages, spread) {
    const a = spread * 2;
    const b = a + 1;

    if (state.readingDirection === "eastern") {
      return [b, a].filter(i => i < totalPages);
    }
    return [a, b].filter(i => i < totalPages);
  }

  function getSpreadPages(totalPages, spread) {
    const first = spread * 2 + 1;
    const second = first + 1;

    if (state.readingDirection === "eastern") {
      return [second, first].filter(p => p <= totalPages);
    }
    return [first, second].filter(p => p <= totalPages);
  }

  function getReaderPages(totalPages, skipCover) {
    const firstPage = skipCover && totalPages > 1 ? 2 : 1;
    return Array.from({ length: totalPages - firstPage + 1 }, (_, index) => firstPage + index);
  }

  function getReaderSpreadPages(totalPages, spread, skipCover) {
    const pages = getReaderPages(totalPages, skipCover).slice(spread * 2, spread * 2 + 2);
    return state.readingDirection === "eastern" ? pages.reverse() : pages;
  }

  function getReaderSpreadIndexes(totalPages, spread, skipCover) {
    return getReaderSpreadPages(totalPages, spread, skipCover).map(page => page - 1);
  }

  const READER_END_PAGE_URL = "assets/somosumabiblioteca.jpg";

  function isReaderEndPage(page, totalPages) {
    return page === totalPages + 1;
  }

  function formatType(type) {
    return type === "manga" ? "Mangá" : "Quadrinho";
  }

  function save() {
    DataStore.save(state.db);
  }

  function toast(message) {
    if (state.suppressDownloadReadyToast && String(message).includes("Quadrinho")) {
      state.suppressDownloadReadyToast = false;
      return;
    }
    const el = document.createElement("div");
    el.className = "toast";
    el.textContent = message;
    $("#toast-root").appendChild(el);
    setTimeout(() => el.remove(), 2800);
  }

  function openPasswordRecoveryModal() {
    const overlay = document.createElement("div");
    overlay.className = "modal-backdrop";
    overlay.innerHTML = `
      <div class="modal auth-modal">
        <div class="section-head">
          <div>
            <h2>Recuperar acesso</h2>
            <div class="section-subtitle">Informe o email associado à sua conta para receber o link de recuperação.</div>
          </div>
          <button class="small-btn" type="button" data-close>Fechar</button>
        </div>
        <form id="password-recovery-form">
          <div class="field">
            <label for="recovery-email">Email da conta</label>
            <input id="recovery-email" name="email" type="email" required placeholder="voce@email.com" autocomplete="email">
          </div>
          <div class="modal-actions">
            <button type="button" class="small-btn" data-close>Cancelar</button>
            <button class="btn btn-danger" type="submit">Enviar link</button>
          </div>
          <div class="auth-message" id="recovery-message"></div>
        </form>
      </div>`;
    $("#modal-root").appendChild(overlay);
    $$("[data-close]", overlay).forEach(button => button.onclick = () => overlay.remove());
    $("#recovery-email", overlay)?.focus();
    $("#password-recovery-form", overlay).addEventListener("submit", async event => {
      event.preventDefault();
      const email = String(new FormData(event.currentTarget).get("email") || "").trim();
      const message = $("#recovery-message", overlay);
      const submit = $('button[type="submit"]', event.currentTarget);
      submit.disabled = true;
      if (!sb) {
        message.textContent = "A autenticação ainda não foi configurada.";
        submit.disabled = false;
        return;
      }
      const redirectTo = `${window.location.origin}${window.location.pathname}`;
      const result = await sb.auth.resetPasswordForEmail(email, { redirectTo });
      if (result.error) {
        message.textContent = result.error.message;
        submit.disabled = false;
        return;
      }
      overlay.remove();
      toast("Enviamos o link de recuperação para o email informado.");
    });
  }

  function weightedRandom(items) {
    return items[Math.floor(Math.random() * items.length)];
  }

  function openRandomCatalogItem() {
    const candidates = visibleCatalogItems().filter(item => !item.local);
    if (!candidates.length) {
      toast("Ainda não há quadrinhos disponíveis para sortear.");
      return;
    }
    openReader(weightedRandom(candidates));
  }

  function normalizedSeriesKey(value = "") {
    return String(value).trim().toLowerCase()
      .normalize("NFD").replace(/[\u0300-\u036f]/g, "")
      .replace(/[^a-z0-9]+/g, "-").replace(/^-|-$/g, "");
  }

  function canonicalSeriesIdFor(seriesTitle = "", currentSeriesId = "") {
    const titleKey = normalizedSeriesKey(seriesTitle);
    const currentKey = normalizedSeriesKey(currentSeriesId).replace(/^series-/, "");
    const definition = (window.DEFAULT_SERIES || []).find(series => {
      const idKey = normalizedSeriesKey(series.id).replace(/^series-/, "");
      const nameKey = normalizedSeriesKey(series.name || series.seriesTitle);
      return (titleKey && (nameKey === titleKey || idKey === titleKey)) || (currentKey && idKey === currentKey);
    });
    return definition?.id || (titleKey === "shazam" ? "series-shazam-2023" : currentSeriesId || "");
  }

  function seriesKey(value = "") {
    return canonicalSeriesIdFor(value, "") || normalizedSeriesKey(value);
  }

  function issueSortValue(item) {
    const explicitOrder = Number(item?.sortOrder);
    if (Number.isFinite(explicitOrder)) return explicitOrder;
    const issueNumber = Number(String(item?.issue || "").match(/\d+(?:\.\d+)?/)?.[0]);
    return Number.isFinite(issueNumber) ? issueNumber : Number.MAX_SAFE_INTEGER;
  }

  function uniqueCatalogItems(items) {
    const seen = new Set();
    return items.filter(item => {
      const key = item.seriesId || item.id;
      if (seen.has(key)) return false;
      seen.add(key);
      return true;
    });
  }

  function personalizedRecommendations(lib) {
    if (!state.session) return [];
    const saved = state.favoriteIds || new Set();
    const liked = state.comicLikeIds || new Set();
    const seeds = lib.filter(item => saved.has(item.id) || liked.has(item.id) || (item.seriesId && saved.has(item.seriesId)));
    if (!seeds.length) return [];

    const values = value => String(value || "").toLowerCase().split(/\s*(?:\/|&|,|\be\b)\s*/i).map(part => seriesKey(part)).filter(Boolean);
    const tags = value => (Array.isArray(value) ? value : String(value || "").split(",")).map(part => seriesKey(part)).filter(Boolean);
    const fields = ["publisher", "imprint", "author", "character"];
    const preferences = new Map(fields.map(field => [field, new Set()]));
    const preferredTags = new Set();
    seeds.forEach(seed => {
      fields.forEach(field => values(seed[field]).forEach(value => preferences.get(field).add(value)));
      tags(seed.tags).forEach(tag => preferredTags.add(tag));
    });

    const seedIds = new Set(seeds.map(item => item.id));
    const seedSeries = new Set(seeds.map(item => item.seriesId).filter(Boolean));
    const candidates = lib.filter(item => !seedIds.has(item.id) && !(item.seriesId && seedSeries.has(item.seriesId)) && !item.local);
    const ranked = candidates.map(item => {
      let score = Math.log1p(Number(item.clicks) || 0) * .25 + (item.featured ? 1 : 0);
      fields.forEach(field => { if (values(item[field]).some(value => preferences.get(field).has(value))) score += field === "publisher" ? 4 : 3; });
      if (tags(item.tags).some(tag => preferredTags.has(tag))) score += 2;
      score += (state.comicLikeCounts.get(item.id) || 0) * .35;
      return { item, score };
    }).sort((a, b) => b.score - a.score || itemDisplayTitle(a.item).localeCompare(itemDisplayTitle(b.item), "pt-BR"));

    return uniqueCatalogItems(ranked.map(entry => entry.item)).slice(0, 6);
  }

  function readArtistSeriesRecommendation(lib) {
    const completedReads = [...(state.readingProgress || new Map()).entries()]
      .filter(([, progress]) => progress?.completed)
      .sort(([, a], [, b]) => new Date(b.updated_at || 0) - new Date(a.updated_at || 0))
      .map(([itemId]) => lib.find(item => String(item.id) === String(itemId)))
      .filter(Boolean);
    const artistValues = value => String(value || "").toLowerCase()
      .split(/\s*(?:\/|&|\be\b)\s*/i)
      .map(part => seriesKey(part))
      .filter(Boolean);
    for (const readItem of completedReads) {
      const artists = new Set(artistValues(readItem.author));
      if (!artists.size) continue;
      const matches = lib.filter(item => item.seriesId && item.seriesId !== readItem.seriesId && artistValues(item.author).some(artist => artists.has(artist)));
      const seriesItems = uniqueCatalogItems(matches).slice(0, 20);
      if (seriesItems.length) return { readItem, seriesItems };
    }
    return null;
  }

  function openItem(item) {
    if (!item) return;
    if (!item.seriesId) return openReader(item);
    const editions = seriesEditions(item);
    if (editions.length < 2) return openReader(item);
    openSeriesSelection(item, editions);
  }

  function seriesEditions(item) {
    if (!item?.seriesId) return [];
    const current = visibleCatalogItems().filter(x => x.seriesId === item.seriesId);
    const uniqueCurrent = [...new Map(current.map(entry => [entry.id, entry])).values()];
    if (uniqueCurrent.length !== current.length) {
      state.db.library = [
        ...state.db.library.filter(entry => entry.seriesId !== item.seriesId),
        ...uniqueCurrent
      ];
      DataStore.save(state.db);
    }
    if (item.seriesId === "series-shazam-2023") {
      const defaults = (window.DEFAULT_LIBRARY || []).filter(entry => entry.seriesId === item.seriesId);
      const currentById = new Map(uniqueCurrent.map(entry => [entry.id, entry]));
      const reconciled = defaults.map(entry => ({ ...structuredClone(entry), ...(currentById.get(entry.id) || {}) }));
      const extras = uniqueCurrent.filter(entry => !defaults.some(defaultEntry => defaultEntry.id === entry.id));
      if (reconciled.length !== uniqueCurrent.length || reconciled.some((entry, index) => entry.id !== uniqueCurrent[index]?.id)) {
        state.db.library = [
          ...state.db.library.filter(entry => entry.seriesId !== item.seriesId),
          ...reconciled,
          ...extras
        ];
        DataStore.save(state.db);
      }
      return visibleCatalogItems([...reconciled, ...extras]).sort((a, b) => issueSortValue(a) - issueSortValue(b));
    }
    return visibleCatalogItems(uniqueCurrent)
      .sort((a, b) => issueSortValue(a) - issueSortValue(b));
  }

  function appendSeriesNavigation(item, controls, overlay) {
    const editions = seriesEditions(item);
    const previousHost = $("#reader-series-prev", overlay);
    const nextHost = $("#reader-series-next", overlay);
    if (editions.length < 2 || (!previousHost && !nextHost)) return;
    const offlineReader = navigator.onLine === false || state.session?.offline;
    const navigationEditions = offlineReader
      ? editions.filter(edition => edition.id === item.id || downloaded(edition.id)?.status === "completed")
      : editions;
    if (offlineReader && navigationEditions.length < 2) {
      if (previousHost) previousHost.innerHTML = '<button type="button" disabled title="Nenhuma outra edição desta série está disponível offline">‹ Anterior</button>';
      if (nextHost) nextHost.innerHTML = '<button type="button" disabled title="Nenhuma outra edição desta série está disponível offline">Próxima ›</button>';
      return;
    }
    const current = navigationEditions.findIndex(x => x.id === item.id);
    const firstEdition = navigationEditions[0];
    const previousEdition = navigationEditions[current - 1];
    const nextEdition = navigationEditions[current + 1];
    const lastEdition = navigationEditions[navigationEditions.length - 1];
    const editionButtonLabel = edition => edition?.issue ? `#${escapeHTML(String(edition.issue))}` : "Edição";
    const createNavigation = (host, html) => {
      if (!host || host.querySelector("[data-series-nav]")) return;
      const nav = document.createElement("span");
      nav.dataset.seriesNav = "true";
      nav.className = "series-reader-nav";
      nav.innerHTML = html;
      host.appendChild(nav);
      $$('[data-series-target]', nav).forEach(button => {
        const target = navigationEditions[Number(button.dataset.seriesTarget)];
        if (offlineReader && (!target || (target.id !== item.id && downloaded(target.id)?.status !== "completed"))) {
          button.disabled = true;
          button.title = "Esta edição não está disponível offline";
          return;
        }
        button.addEventListener("click", () => {
          if (!target || target.id === item.id) return;
          overlay._seriesObserver?.disconnect();
          overlay.remove();
          openReader(target);
        });
      });
    };
    if (current > 0) createNavigation(previousHost, `${current > 1 ? `<button title="Primeira edição${firstEdition?.issue ? ` — ${String(firstEdition.issue)}` : ""}" data-series-target="0">« ${editionButtonLabel(firstEdition)}</button>` : ""}<button title="Edição anterior${previousEdition?.issue ? ` — ${String(previousEdition.issue)}` : ""}" data-series-target="${current - 1}">‹ ${editionButtonLabel(previousEdition)}</button>`);
    if (current < editions.length - 1) createNavigation(nextHost, `<button title="Próxima edição${nextEdition?.issue ? ` — ${String(nextEdition.issue)}` : ""}" data-series-target="${current + 1}">${editionButtonLabel(nextEdition)} ›</button>${current < editions.length - 2 ? `<button title="Última edição${lastEdition?.issue ? ` — ${String(lastEdition.issue)}` : ""}" data-series-target="${editions.length - 1}">${editionButtonLabel(lastEdition)} »</button>` : ""}`);
  }

  function openEntityPage(kind, value) {
    if (kind === "character") value = canonicalCharacterName(value);
    state.entityFilter = { kind, value };
    state.collectionFilter = { field: "all", query: "" };
    navigate({ pagina: "entidade", tipo: kind, valor: value });
  }

  function wikiEntityPublishers(kind, value) {
    const normalized = String(value || "").trim().toLocaleLowerCase("pt-BR");
    return [...new Set(state.db.library
      .filter(item => {
        if (kind === "character") return characterNames(item).some(name => name.toLocaleLowerCase("pt-BR") === normalized);
        if (kind === "author") return String(item.author || "").split(/\s*(?:\/|&|\be\b)\s*/i).some(name => name.trim().toLocaleLowerCase("pt-BR") === normalized);
        if (kind === "imprint") return String(item.imprint || "").trim().toLocaleLowerCase("pt-BR") === normalized;
        return false;
      })
      .map(item => String(item.publisher || "").trim())
      .filter(Boolean))];
  }

  function defaultWikiReferenceForEntity(kind, value) {
    if (kind !== "character") return "";
    const normalized = String(value || "").trim().toLocaleLowerCase("pt-BR");
    const references = {
      "o questão": "https://en.wikipedia.org/wiki/Question_(character)",
    };
    if (normalized === "scott free") return "https://en.wikipedia.org/wiki/Mister_Miracle";
    return references[normalized] || "";
  }

  function wikiApiUrl(params, sourceUrl = "") {
    const query = new URLSearchParams({ ...params, format: "json", origin: "*" });
    let origin = "https://pt.wikipedia.org";
    try {
      const source = new URL(String(sourceUrl || ""));
      if (/(^|\.)wikipedia\.org$/i.test(source.hostname)) origin = source.origin;
    } catch {}
    return `${origin}/w/api.php?${query.toString()}`;
  }

  function wikiArticleTitleFromUrl(value) {
    try {
      const url = new URL(String(value || "").trim());
      if (!/^https?:$/.test(url.protocol) || !/(^|\.)wikipedia\.org$/i.test(url.hostname)) return "";
      const match = url.pathname.match(/^\/wiki\/(.+)$/i);
      const title = match?.[1] || (url.pathname.endsWith("/w/index.php") ? url.searchParams.get("title") : "");
      return title ? decodeURIComponent(title).replace(/_/g, " ").trim() : "";
    } catch { return ""; }
  }

  function wikiLanguageFromUrl(value) {
    try {
      const url = new URL(String(value || ""));
      const hostname = url.hostname.toLowerCase();
      const match = hostname.match(/^([a-z]{2,3})\.wikipedia\.org$/);
      if (match?.[1]) return match[1];
      const pathLocale = url.pathname.match(/^\/([a-z]{2,3})(?:-[a-z]{2,4})?(?=\/|$)/i)?.[1]?.toLowerCase();
      if (/^ligadajustia\.fandom\.com$/i.test(hostname)) return "pt";
      return pathLocale || "auto";
    } catch { return "auto"; }
  }

  function isWikiReferenceUrl(value) {
    try {
      const url = new URL(String(value || "").trim());
      if (!/^https?:$/.test(url.protocol) || !url.pathname || url.pathname === "/") return false;
      return /(^|\.)wikipedia\.org$/i.test(url.hostname)
        || /(^|\.)fandom\.com$/i.test(url.hostname)
        || /(^|\.)wikia\.com$/i.test(url.hostname);
    } catch { return false; }
  }

  function fandomArticleFromUrl(value) {
    try {
      const url = new URL(String(value || "").trim());
      if (!/^https?:$/.test(url.protocol) || !/(^|\.)fandom\.com$|(^|\.)wikia\.com$/i.test(url.hostname)) return null;
      const match = url.pathname.match(/(?:\/[a-z]{2,3}(?:-[a-z]{2,4})?)?\/wiki\/(.+)$/i);
      const queryTitle = url.pathname.endsWith("/w/index.php") ? url.searchParams.get("title") : "";
      if (!match && !queryTitle) return null;
      const pathLocale = url.pathname.match(/^\/([a-z]{2,3}(?:-[a-z]{2,4})?)(?=\/|$)/i)?.[1] || "";
      const defaultLocale = /^ligadajustia\.fandom\.com$/i.test(url.hostname) ? "pt-br" : "";
      const locale = pathLocale || defaultLocale;
      return {
        url: url.href,
        title: decodeURIComponent(match?.[1] || queryTitle).replace(/_/g, " ").trim(),
        apiPath: `${locale ? `/${locale}` : ""}/api.php`,
      };
    } catch { return null; }
  }

  function fandomApiUrl(reference) {
    const url = new URL(reference.url);
    const pathLocale = url.pathname.match(/^\/([a-z]{2,3}(?:-[a-z]{2,4})?)(?=\/|$)/i)?.[1] || "";
    const defaultLocale = /^ligadajustia\.fandom\.com$/i.test(url.hostname) ? "pt-br" : "";
    const locale = pathLocale || reference.locale || defaultLocale;
    url.pathname = reference.apiPath || `${locale ? `/${locale}` : ""}/api.php`;
    url.search = new URLSearchParams({ action: "parse", page: reference.title, prop: "text|displaytitle", format: "json", origin: "*" }).toString();
    return url.href;
  }

  function fetchFandomApi(reference) {
    return fetchWithTimeout(fandomApiUrl(reference), { mode: "cors", credentials: "omit", cache: "no-store" });
  }

  // APIs externas podem ficar penduradas indefinidamente em redes com bloqueio
  // de CORS, DNS ou extensões de privacidade. A Wiki rápida precisa sempre
  // terminar em sucesso ou em uma mensagem de erro acionável.
  function fetchWithTimeout(input, options = {}, timeoutMs = 10000) {
    const controller = new AbortController();
    const timeout = setTimeout(() => controller.abort(), timeoutMs);
    const signal = controller.signal;
    return fetch(input, { ...options, signal }).finally(() => clearTimeout(timeout));
  }

  function wikiTextFromHtml(html, sourceBase = "https://pt.wikipedia.org") {
    const documentCopy = new DOMParser().parseFromString(String(html || ""), "text/html");
    let baseOrigin = "https://pt.wikipedia.org";
    try { baseOrigin = new URL(sourceBase).origin; } catch {}
    documentCopy.querySelectorAll("script,style,link,meta,form,iframe,object,embed,.mw-editsection,.navbox,.ambox,.vertical-navbox,.metadata").forEach(node => node.remove());
    documentCopy.querySelectorAll("*[style],*[onload],*[onclick],*[onerror],*[onmouseover]").forEach(node => {
      node.removeAttribute("style");
      [...node.attributes].filter(attribute => /^on/i.test(attribute.name)).forEach(attribute => node.removeAttribute(attribute.name));
    });
    documentCopy.querySelectorAll("a[href]").forEach(link => {
      const href = link.getAttribute("href") || "";
      if (href.startsWith("//")) link.href = `https:${href}`;
      else if (href.startsWith("/")) link.href = `${baseOrigin}${href}`;
      if (!/^https?:/i.test(link.href)) link.removeAttribute("href");
      else { link.target = "_blank"; link.rel = "noopener noreferrer"; }
    });
    documentCopy.querySelectorAll("img[src]").forEach(image => {
      const src = image.getAttribute("src") || "";
      if (src.startsWith("//")) image.src = `https:${src}`;
      else if (src.startsWith("/")) image.src = `${baseOrigin}${src}`;
      if (!/^https?:/i.test(image.src)) image.remove();
      image.removeAttribute("srcset");
    });
    return documentCopy.body.innerHTML;
  }

  function fandomTextFromHtml(html, sourceUrl) {
    const documentCopy = new DOMParser().parseFromString(String(html || ""), "text/html");
    documentCopy.querySelectorAll(".portable-infobox").forEach(node => node.classList.add("infobox"));
    documentCopy.querySelectorAll(".pi-title, .pi-header").forEach(node => node.classList.add("infobox-title"));
    let sourceOrigin = "https://www.fandom.com";
    try { sourceOrigin = new URL(sourceUrl).origin; } catch {}
    return wikiTextFromHtml(documentCopy.body.innerHTML, sourceOrigin);
  }

  function fandomQuickExtractFromHtml(html) {
    const documentCopy = new DOMParser().parseFromString(String(html || ""), "text/html");
    documentCopy.querySelectorAll(".portable-infobox, .toc, .navbox, .mw-editsection, table, script, style, figure").forEach(node => node.remove());
    const paragraphs = [...documentCopy.querySelectorAll("p")]
      .map(node => String(node.textContent || "").replace(/\s+/g, " ").trim())
      .filter(text => text.length >= 35 && !/^\[?citation needed\]?$/i.test(text));
    return paragraphs.slice(0, 2).join(" ").slice(0, 900).trim();
  }

  function fandomImageFromHtml(html, sourceUrl) {
    const documentCopy = new DOMParser().parseFromString(String(html || ""), "text/html");
    const image = documentCopy.querySelector(".portable-infobox figure img, .portable-infobox img, .pi-image img, figure img, img");
    if (!image) return "";
    const source = image.getAttribute("src") || image.getAttribute("data-src") || image.getAttribute("data-image-key") || "";
    try {
      const base = new URL(sourceUrl || "https://www.fandom.com");
      const resolved = new URL(source, base);
      return /^https?:$/i.test(resolved.protocol) ? resolved.href : "";
    } catch { return ""; }
  }

  function wikiLanguageFromHtml(html) {
    const documentCopy = new DOMParser().parseFromString(String(html || ""), "text/html");
    const lang = documentCopy.documentElement.lang || documentCopy.querySelector("[lang]")?.getAttribute("lang") || "";
    return String(lang).split("-")[0].toLowerCase() || "auto";
  }

  function fandomSourceLanguage(reference, html = "") {
    const urlLanguage = wikiLanguageFromUrl(reference?.url);
    if (urlLanguage !== "auto") return urlLanguage;
    const htmlLanguage = wikiLanguageFromHtml(html);
    return htmlLanguage !== "auto" ? htmlLanguage : "en";
  }

  const translationCache = new Map();
  const translationInFlight = new Map();
  const wikiTranslatedNodes = new WeakSet();
  let translationQueue = Promise.resolve();
  let translationBlockedUntil = 0;
  try {
    const savedTranslations = JSON.parse(localStorage.getItem("bancaTranslationCache") || "{}");
    Object.entries(savedTranslations).forEach(([key, value]) => translationCache.set(key, value));
    translationBlockedUntil = Number(localStorage.getItem("bancaTranslationBlockedUntilV2") || 0);
  } catch {}

  function persistTranslationCache() {
    try {
      const entries = [...translationCache.entries()].slice(-1000);
      localStorage.setItem("bancaTranslationCache", JSON.stringify(Object.fromEntries(entries)));
    } catch {}
  }

  function waitForTranslationSlot() {
    translationQueue = translationQueue.then(() => new Promise(resolve => setTimeout(resolve, 100)));
    return translationQueue;
  }

  async function translateToPortuguese(text, sourceLanguage = "auto") {
    const value = String(text || "").trim();
    if (!value || value.length < 3) return text;
    if (["pt", "auto"].includes(String(sourceLanguage).toLowerCase())) return text;
    if (value.length > 420) {
      const chunks = [];
      let remaining = value;
      while (remaining.length > 420) {
        let cut = remaining.lastIndexOf(" ", 420);
        if (cut < 180) cut = 420;
        chunks.push(remaining.slice(0, cut).trim());
        remaining = remaining.slice(cut).trim();
      }
      if (remaining) chunks.push(remaining);
      const translatedChunks = await Promise.all(chunks.map(chunk => translateToPortuguese(chunk, sourceLanguage)));
      return decodeNewsText(translatedChunks.join(" "));
    }
    const translationKey = "v3:" + sourceLanguage + ":" + value;
    if (translationCache.has(translationKey)) return translationCache.get(translationKey);
    if (translationInFlight.has(translationKey)) return translationInFlight.get(translationKey);
    const request = (async () => {
      await waitForTranslationSlot();
      if (sb?.functions?.invoke) {
        try {
          const backend = await sb.functions.invoke("translate", { body: { text: value, sourceLanguage } });
          const backendText = String(backend.data?.translatedText || "").trim();
          if (!backend.error && backendText) {
            translationCache.set(translationKey, backendText);
            persistTranslationCache();
            return decodeNewsText(backendText);
          }
        } catch {}
        // Com Supabase configurado, nunca voltar ao MyMemory no navegador:
        // isso causa CORS/429 e impede a leitura interna de funcionar.
        return text;
      }
      if (translationBlockedUntil > Date.now()) return text;
      const query = new URLSearchParams({ q: value.slice(0, 480), langpair: `${sourceLanguage}|pt` });
      const controller = new AbortController();
      const timeout = setTimeout(() => controller.abort(), 8000);
      let response;
      try {
        response = await fetch(`https://api.mymemory.translated.net/get?${query.toString()}`, { cache: "no-store", signal: controller.signal });
      } finally { clearTimeout(timeout); }
      if (response.status === 429) {
        translationBlockedUntil = Date.now() + 10 * 60 * 1000;
        try { localStorage.setItem("bancaTranslationBlockedUntilV2", String(translationBlockedUntil)); } catch {}
        return text;
      }
      if (!response.ok) return text;
      const payload = await response.json();
      if (Number(payload.responseStatus) !== 200) return text;
      const translated = String(payload.responseData?.translatedText || "").trim();
      if (!translated || /invalid source language|error/i.test(translated)) return text;
      translationCache.set(translationKey, translated);
      persistTranslationCache();
      return decodeNewsText(translated);
    })().catch(() => text).finally(() => translationInFlight.delete(translationKey));
    translationInFlight.set(translationKey, request);
    return request;
  }

  async function translateHtmlToPortuguese(html, sourceLanguage = "auto") {
    if (["pt", "auto"].includes(String(sourceLanguage).toLowerCase())) return String(html || "");
    const documentCopy = new DOMParser().parseFromString(String(html || ""), "text/html");
    const walker = documentCopy.createTreeWalker(documentCopy.body, NodeFilter.SHOW_TEXT);
    const textNodes = [];
    let node;
    while ((node = walker.nextNode())) {
      if (!node.parentElement?.closest("script,style,code,pre") && node.nodeValue.trim().length >= 3) textNodes.push(node);
    }
    for (let start = 0; start < textNodes.length; start += 6) {
      await Promise.all(textNodes.slice(start, start + 6).map(async textNode => {
        const leading = textNode.nodeValue.match(/^\s*/)?.[0] || "";
        const trailing = textNode.nodeValue.match(/\s*$/)?.[0] || "";
        const translated = await translateToPortuguese(textNode.nodeValue.trim(), sourceLanguage);
        textNode.nodeValue = `${leading}${translated}${trailing}`;
      }));
    }
    return documentCopy.body.innerHTML;
  }

  async function translateVisibleWikiContent(root, sourceLanguage) {
    if (!root || ["pt", "auto"].includes(String(sourceLanguage).toLowerCase())) return;
    const textNodes = [];
    const walker = document.createTreeWalker(root, NodeFilter.SHOW_TEXT);
    let node;
    while ((node = walker.nextNode())) {
      if (node.parentElement?.closest("script,style,code,pre") || node.nodeValue.trim().length < 3) continue;
      const rect = node.parentElement.getBoundingClientRect();
      if (rect.bottom > 0 && rect.top < window.innerHeight && rect.right > 0 && rect.left < window.innerWidth) textNodes.push(node);
    }
    for (let start = 0; start < textNodes.length; start += 6) {
      await Promise.all(textNodes.slice(start, start + 6).map(async textNode => {
        if (wikiTranslatedNodes.has(textNode)) return;
        wikiTranslatedNodes.add(textNode);
        const original = textNode.nodeValue.trim();
        const translated = await translateToPortuguese(original, sourceLanguage);
        if (translated !== original) textNode.nodeValue = textNode.nodeValue.replace(original, translated);
        if (textNode.parentElement) textNode.parentElement.dataset.translated = "true";
      }));
    }
  }

  function wikiQuickMarkup(value, kind = "character") {
    const character = value;
    let expanded = true;
    try { expanded = localStorage.getItem("bancaWikiQuickExpanded") !== "false"; } catch {}
    const settings = kind === "character" ? state.characterSettings : kind === "imprint" ? state.imprintSettings : new Map();
    const customImage = kind === "character" ? characterSettingForName(value)?.cover_url || "" : settings.get(publisherKey(value))?.cover_url || "";
    const imageMarkup = customImage ? `<img src="${escapeHTML(proxiedImageUrl(customImage))}" alt="Imagem de ${escapeHTML(value)}" loading="lazy">` : "";
    return `<section class="entity-wiki ${expanded ? "is-expanded" : "is-collapsed"}" data-wiki-quick="${escapeHTML(character)}"><div class="entity-wiki-heading"><div class="eyebrow">Wiki rápida</div><button type="button" class="small-btn" data-wiki-toggle aria-expanded="${expanded ? "true" : "false"}">${expanded ? "Recolher" : "Expandir"}</button></div><div class="entity-wiki-layout"><div class="entity-wiki-image ${customImage ? "" : "is-loading"}" data-wiki-image aria-hidden="true">${imageMarkup}</div><div class="entity-wiki-copy" data-wiki-copy><p class="section-subtitle">Buscando informações na Wikipédia...</p></div></div></section>`;
  }

  function toggleWikiQuick(button) {
    const wiki = button.closest("[data-wiki-quick]");
    if (!wiki) return;
    const expanded = !wiki.classList.contains("is-expanded");
    wiki.classList.toggle("is-expanded", expanded);
    wiki.classList.toggle("is-collapsed", !expanded);
    const layout = $(".entity-wiki-layout", wiki);
    if (layout) layout.hidden = !expanded;
    button.setAttribute("aria-expanded", String(expanded));
    button.textContent = expanded ? "Recolher" : "Expandir";
    try { localStorage.setItem("bancaWikiQuickExpanded", String(expanded)); } catch {}
  }

  async function loadWikiQuickInfo(value, kind) {
    if (kind === "character" && !characterSettingsReady) return;
    const host = [...document.querySelectorAll("[data-wiki-quick]")].find(node => node.dataset.wikiQuick === String(value));
    if (!host || host.dataset.wikiLoading === "true" || host.dataset.wikiLoaded === "true") return;
    host.dataset.wikiLoading = "true";
    const setting = kind === "character"
      ? characterSettingForName(value) || {}
      : kind === "imprint" ? state.imprintSettings.get(publisherKey(value)) || {} : {};
    const customImage = setting.cover_url || "";
    const authoredText = String(setting.authored_text || "").trim();
    const configuredWikiUrl = String(setting.wikipedia_url || defaultWikiReferenceForEntity(kind, value)).trim();
    const customWikipediaTitle = configuredWikiUrl ? wikiArticleTitleFromUrl(configuredWikiUrl) : "";
    const customFandomReference = configuredWikiUrl ? fandomArticleFromUrl(configuredWikiUrl) : null;
    const wikiSourceLanguage = wikiLanguageFromUrl(configuredWikiUrl);
    const imageHost = $("[data-wiki-image]", host);
    if (customImage && imageHost && !$("img", imageHost)) {
      imageHost.classList.remove("is-loading");
      imageHost.innerHTML = `<img src="${escapeHTML(proxiedImageUrl(customImage))}" alt="Imagem de ${escapeHTML(value)}" loading="lazy">`;
    }
    if (authoredText) {
      const copy = $("[data-wiki-copy]", host);
      if (copy) copy.innerHTML = `<p class="wiki-authored-text">${escapeHTML(authoredText)}</p>`;
      host.dataset.wikiLoaded = "true";
      return;
    }
    const publishers = wikiEntityPublishers(kind, value);
    // Uma editora já desambigua a busca sem exigir que a mesma página contenha
    // simultaneamente todas as editoras presentes no catálogo.
    const search = [value, publishers[0]].filter(Boolean).join(" ").trim();
    try {
      if (configuredWikiUrl && !customWikipediaTitle && !customFandomReference) throw new Error("Link da Wikipédia ou Fandom inválido");
      if (customFandomReference) {
        const fandomResult = await fetchFandomApi(customFandomReference);
        if (!fandomResult.ok) throw new Error("Fandom indisponível");
        const fandomData = await fandomResult.json();
        const parsed = fandomData.parse;
        if (!parsed?.text?.["*"]) throw new Error("Artigo do Fandom não encontrado");
        const fandomImage = fandomImageFromHtml(parsed.text["*"], customFandomReference.url);
        const safeHtml = fandomTextFromHtml(parsed.text["*"], customFandomReference.url);
        // O resumo deve acompanhar o início do artigo, não concatenar o infobox inteiro.
        const extract = fandomQuickExtractFromHtml(parsed.text["*"]);
        const sourceLanguage = wikiSourceLanguage === "auto" ? fandomSourceLanguage(customFandomReference, parsed.text["*"]) : wikiSourceLanguage;
        const translatedExtract = await translateToPortuguese(extract, sourceLanguage);
        const imageHost = $("[data-wiki-image]", host);
        if (imageHost) {
          imageHost.classList.remove("is-loading");
          if (!customImage || !$("img", imageHost)) imageHost.innerHTML = `<img src="${escapeHTML(customImage || fandomImage || "assets/batmanicon.jpg")}" alt="Imagem de ${escapeHTML(value)}" loading="lazy">`;
        }
        const copy = $("[data-wiki-copy]", host);
        if (copy) copy.innerHTML = `<p>${escapeHTML(translatedExtract || `Leia mais sobre ${value} no Fandom.`)}</p><button type="button" class="small-btn" data-fandom-read>Ler mais</button>`;
        host.dataset.wikiLoaded = "true";
        $("[data-fandom-read]", host)?.addEventListener("click", () => openFandomReader(customFandomReference));
        return;
      }
      let preferredPage = null;
      if (customWikipediaTitle) {
        const preferredResult = await fetchWithTimeout(wikiApiUrl({ action: "query", titles: customWikipediaTitle, prop: `extracts|pageimages${wikiSourceLanguage !== "pt" ? "|langlinks" : ""}`, exintro: "1", explaintext: "1", piprop: "thumbnail", pithumbsize: "240", ...(wikiSourceLanguage !== "pt" ? { lllang: "pt" } : {}) }, configuredWikiUrl), { cache: "no-store" });
        if (!preferredResult.ok) throw new Error("Artigo da Wikipédia configurado indisponível");
        preferredPage = Object.values((await preferredResult.json()).query?.pages || {}).find(candidate => candidate.missing === undefined) || null;
        if (!preferredPage) throw new Error("Artigo da Wikipédia configurado não encontrado");
      }
      let pages = [];
      if (!preferredPage && !customWikipediaTitle && !configuredWikiUrl) {
        const result = await fetchWithTimeout(wikiApiUrl({ action: "query", generator: "search", gsrsearch: search || value, gsrnamespace: "0", gsrlimit: "20", prop: "extracts|pageimages", exintro: "1", explaintext: "1", piprop: "thumbnail", pithumbsize: "240" }));
        if (!result.ok) throw new Error("Wikipedia indisponível");
        const data = await result.json();
        pages = Object.values(data.query?.pages || {});
      }
      const normalizedValue = String(value).trim().toLocaleLowerCase("pt-BR");
      const matchingPage = pages.find(candidate => String(candidate.title || "").trim().toLocaleLowerCase("pt-BR") === normalizedValue)
        || pages.find(candidate => String(candidate.title || "").trim().toLocaleLowerCase("pt-BR").startsWith(`${normalizedValue} (`))
      const page = preferredPage || matchingPage || (kind === "author" ? null : pages[0]);
      if (!page) throw new Error("Página não encontrada");
      // Preserve o artigo original configurado. A versão pt via langlinks pode
      // apontar para uma lista/desambiguação, como ocorre com Question_(character).
      const displayPage = page;
      const displaySourceUrl = setting.wikipedia_url || configuredWikiUrl || "";
      const image = customImage || displayPage.thumbnail?.source || "";
      const extract = await translateToPortuguese(String(displayPage.extract || "").trim(), wikiSourceLanguage);
      const copy = $("[data-wiki-copy]", host);
      const imageHost = $("[data-wiki-image]", host);
      if (imageHost) {
        const fallbackImage = "assets/batmanicon.jpg";
        imageHost.classList.remove("is-loading");
        if (!customImage || !$("img", imageHost)) imageHost.innerHTML = `<img src="${escapeHTML(image || fallbackImage)}" alt="Imagem de ${escapeHTML(value)}" loading="lazy">`;
        const imageElement = $("img", imageHost);
        imageElement?.addEventListener("error", () => { imageElement.src = fallbackImage; }, { once: true });
      }
      if (copy) copy.innerHTML = `<p>${escapeHTML(extract || `Leia mais sobre ${value} na Wikipédia.`)}</p><button type="button" class="small-btn" data-wiki-read="${escapeHTML(displayPage.pageid)}" data-wiki-title="${escapeHTML(displayPage.title || value)}">Ler mais</button>`;
      host.dataset.wikiLoaded = "true";
      $("[data-wiki-read]", host)?.addEventListener("click", () => openWikiReader(displayPage.pageid, displayPage.title || value, null, displaySourceUrl));
    } catch (error) {
      if (imageHost && customImage) {
        imageHost.classList.remove("is-loading");
        imageHost.innerHTML = `<img src="${escapeHTML(proxiedImageUrl(customImage))}" alt="Imagem de ${escapeHTML(value)}" loading="lazy">`;
      }
      const copy = $("[data-wiki-copy]", host);
      if (copy) copy.innerHTML = `<p>Não foi possível carregar a Wikipédia agora.</p><button type="button" class="small-btn" data-wiki-retry> tentar novamente </button>`;
      $("[data-wiki-retry]", host)?.addEventListener("click", () => { host.dataset.wikiLoading = ""; loadWikiQuickInfo(value, kind); });
      console.warn("Wiki rápida indisponível", error);
    }
  }

  async function openWikiReaderByTitle(title, overlay, sourceUrl = "") {
    const source = sourceUrl || overlay?.dataset.wikiSource || "";
    const result = await fetch(wikiApiUrl({ action: "query", titles: title, prop: "info" }, source));
    if (!result.ok) throw new Error("Wikipedia indisponível");
    const page = Object.values((await result.json()).query?.pages || {})[0];
    if (!page || page.missing !== undefined) throw new Error("Artigo não encontrado");
    return openWikiReader(page.pageid, page.title || title, overlay, source);
  }

  async function openCharacterWiki(characterName) {
    const name = String(characterName || "").trim();
    if (!name) return;
    const setting = state.characterSettings.get(publisherKey(name));
    const configuredUrl = String(setting?.wikipedia_url || defaultWikiReferenceForEntity("character", name)).trim();
    const fandomReference = fandomArticleFromUrl(configuredUrl);
    try {
      if (fandomReference) return await openFandomReader(fandomReference);
      const configuredTitle = wikiArticleTitleFromUrl(configuredUrl);
      if (configuredTitle) return await openWikiReaderByTitle(configuredTitle, null, configuredUrl);
      const result = await fetchWithTimeout(wikiApiUrl({ action: "query", generator: "search", gsrsearch: name, gsrnamespace: "0", gsrlimit: "5", prop: "info" }));
      if (!result.ok) throw new Error("Wikipedia indisponível");
      const pages = Object.values((await result.json()).query?.pages || {});
      const page = pages.find(candidate => candidate.missing === undefined);
      if (!page) throw new Error("Artigo não encontrado");
      return await openWikiReader(page.pageid, page.title || name);
    } catch (error) {
      console.warn("Wiki do personagem indisponível", error);
      toast("Não foi possível abrir a wiki deste personagem agora.");
    }
  }

  async function openSavedEntityWiki(kind, entityName) {
    const name = String(entityName || "").trim();
    if (!name) return;
    const settings = kind === "imprint" ? state.imprintSettings : state.publisherSettings;
    const setting = settings.get(publisherKey(name));
    const configuredUrl = String(setting?.wikipedia_url || "").trim();
    const fandomReference = fandomArticleFromUrl(configuredUrl);
    try {
      if (fandomReference) return await openFandomReader(fandomReference);
      const configuredTitle = wikiArticleTitleFromUrl(configuredUrl);
      if (configuredTitle) return await openWikiReaderByTitle(configuredTitle, null, configuredUrl);
      const result = await fetchWithTimeout(wikiApiUrl({ action: "query", generator: "search", gsrsearch: name, gsrnamespace: "0", gsrlimit: "5", prop: "info" }));
      if (!result.ok) throw new Error("Wikipedia indisponível");
      const pages = Object.values((await result.json()).query?.pages || {});
      const page = pages.find(candidate => candidate.missing === undefined);
      if (!page) throw new Error("Artigo não encontrado");
      return await openWikiReader(page.pageid, page.title || name);
    } catch (error) {
      console.warn(`Wiki de ${kind} indisponível`, error);
      toast("Não foi possível abrir esta wiki agora.");
    }
  }

  function assignedCharactersMarkup(characterName) {
    const setting = characterSettingForName(characterName);
    const keys = Array.isArray(setting?.assigned_character_keys) ? setting.assigned_character_keys : [];
    const entries = [...new Set(keys)].map(key => state.characterSettings.get(key)).filter(Boolean);
    if (!entries.length) return "";
    const cards = entries.map(entry => {
      const image = entry.cover_url || wikiCharacterImageCache.get(entry.character_name) || "assets/batmanicon.jpg";
      return `<button type="button" class="wiki-character-card" data-wiki-character="${escapeHTML(entry.character_name)}" aria-label="Ver ${escapeHTML(entry.character_name)}"><span class="wiki-character-image"><img src="${escapeHTML(imageProxyFetchUrl(image))}" alt="Imagem de ${escapeHTML(entry.character_name)}" loading="lazy"></span><strong>${escapeHTML(entry.character_name)}</strong></button>`;
    }).join("");
    return `<section class="section assigned-characters-section"><div class="section-head"><div><h2 class="section-title">Personagens relacionados</h2><div class="section-subtitle">Personagens atribuídos a ${escapeHTML(characterName)}.</div></div></div><div class="wiki-character-carousel"><div class="wiki-character-track wiki-team-track">${cards}</div></div></section>`;
  }

  const CHARACTER_NEWS_SITES = [
    { id: "ovicio", name: "O Vício", domain: "ovicio.com.br" },
    { id: "legiao", name: "Legião dos Heróis", domain: "legiaodosherois.com.br" },
    { id: "cbr", name: "CBR", domain: "cbr.com" },
  ];

  function newsSearchUrl(domain, character) {
    const query = encodeURIComponent(`site:${domain} "${String(character || "").trim()}"`);
    return `https://news.google.com/rss/search?q=${query}&hl=pt-BR&gl=BR&ceid=BR:pt-419`;
  }

  function newsSearchProxyUrl(domain, character) {
    const query = encodeURIComponent(`site:${domain} "${String(character || "").trim()}"`);
    return `https://r.jina.ai/http://www.google.com/search?q=${query}`;
  }

  function newsRssItems(xml, site) {
    const documentCopy = new DOMParser().parseFromString(String(xml || ""), "text/xml");
    return [...documentCopy.querySelectorAll("item")].map(item => {
      const title = String(item.querySelector("title")?.textContent || "").replace(/\s+-\s+[^-]+$/, "").trim();
      let link = String(item.querySelector("link")?.textContent || "").trim();
      try { const parsedLink = new URL(link); link = parsedLink.searchParams.get("url") || parsedLink.searchParams.get("q") || link; } catch {}
      try { if (!(new URL(link)).hostname.toLowerCase().endsWith(site.domain)) return null; } catch { return null; }
      const description = String(item.querySelector("description")?.textContent || "").replace(/<[^>]+>/g, " ").replace(/\s+/g, " ").trim();
      if (!title || !link) return null;
      return { title, url: link, description, site: site.name, siteId: site.id };
    }).filter(Boolean);
  }

  function randomNewsItems(items, count = 3) {
    return [...items].sort(() => Math.random() - 0.5).slice(0, count);
  }

  function newsSearchMarkdownItems(markdown, site) {
    const items = [];
    const pattern = /\[([^\]]+)\]\((https?:\/\/[^)]+)\)/g;
    let match;
    while ((match = pattern.exec(String(markdown || "")))) {
      let link = match[2];
      try {
        const parsed = new URL(link);
        link = parsed.searchParams.get("url") || parsed.searchParams.get("q") || link;
        const hostname = new URL(link).hostname.toLowerCase();
        if (hostname !== site.domain && !hostname.endsWith(`.${site.domain}`)) continue;
      } catch { continue; }
      const title = match[1].replace(/\s+/g, " ").trim();
      if (title && !items.some(item => item.url === link)) items.push({ title, url: link, description: "Leia a matéria completa no site de origem.", site: site.name, siteId: site.id });
    }
    return items;
  }

  async function searchCharacterNewsFallback(site, character) {
    try {
      const response = await fetchWithTimeout(newsSearchProxyUrl(site.domain, character), { cache: "no-store" }, 15000);
      if (!response.ok) return [];
      return newsSearchMarkdownItems(await response.text(), site);
    } catch (error) {
      console.warn("Busca alternativa indisponÃ­vel", error);
      return [];
    }
  }

  async function searchCharacterNews(character) {
    if (sb && navigator.onLine !== false && !state.session?.offline) {
      try {
        const historyKey = "bancaCharacterNewsHistory:" + String(character || "").trim().toLowerCase();
        let excludeUrls = [];
        try { excludeUrls = JSON.parse(localStorage.getItem(historyKey) || "[]"); } catch {}
        const result = await sb.functions.invoke("character-news", { body: { character, excludeUrls } });
        if (!result.error && Array.isArray(result.data?.items)) {
          try {
            const updatedHistory = [...new Set([...excludeUrls, ...result.data.items.map(item => item.url).filter(Boolean)])].slice(-120);
            localStorage.setItem(historyKey, JSON.stringify(updatedHistory));
          } catch {}
          return result.data.items;
        }
        console.warn("Edge Function character-news indisponível", result.error?.message || "resposta inválida");
      } catch (error) {
        console.warn("Não foi possível consultar a Edge Function character-news", error);
      }
    }
    if (sb) return [];
    const results = await Promise.all(CHARACTER_NEWS_SITES.map(async site => {
      try {
        const response = await fetchWithTimeout(newsSearchUrl(site.domain, character), { cache: "no-store" }, 9000);
        if (response.ok) {
          const rssItems = newsRssItems(await response.text(), site);
          if (rssItems.length) return rssItems;
        }
      } catch (error) {
        console.warn(`Busca de notícias indisponível em ${site.name}`, error);
        return await searchCharacterNewsFallback(site, character);
      }
      return await searchCharacterNewsFallback(site, character);
    }));
    const unique = new Map();
    results.flat().forEach(item => { if (!unique.has(item.url)) unique.set(item.url, item); });
    return randomNewsItems([...unique.values()]);
  }

  function characterNewsMarkup() {
    return "";
    return `<section class="section character-news-section" data-character-news><div class="section-head"><div><div class="eyebrow">Notícias e curiosidades</div><h2 class="section-title">Mais sobre este personagem</h2><div class="section-subtitle">Encontramos páginas recentes em sites especializados.</div></div></div><div class="character-news-grid"><div class="empty">Pesquisando notícias e curiosidades...</div></div></section>`;
  }

  function cleanNewsMarkdown(markdown, title = "") {
    let value = String(markdown || "").replace(/\r/g, "");
    const contentIndex = value.indexOf("Markdown Content:");
    if (contentIndex >= 0) value = value.slice(contentIndex + "Markdown Content:".length);
    value = value.replace(/\]\(\[(https?:\/\/[^)\]]+)\]\((https?:\/\/[^)]+)\)\)/g, "]($2)");
    const titleIndex = title ? value.indexOf(title) : -1;
    if (titleIndex >= 0) value = value.slice(titleIndex);
    const cbrArticleStart = value.search(/Show me the facts\s+Explain it like.*?Give me a lighthearted recap\s*/i);
    if (cbrArticleStart >= 0) value = value.slice(cbrArticleStart).replace(/^[^\n]*\n?/i, "");
    value = value.replace(/\n(?:#{1,6}\s*)?(?:Leia mais sobre[^\n]*|Leia também sobre[^\n]*|Veja também:|Comentários|Fonte:)[\s\S]*$/i, "");
    // No CBR, o extrator costuma inserir este aviso antes do texto real. Tudo
    // que vem antes dele é a moldura da página (menu, autor, anúncio e player).
    value = value.replace(/^[\s\S]*?Here is a fact-based summary of the story contents:\s*/i, "");
    value = value.replace(/\nImage \d+:[^\n]*(?:\n[^\n]*)?/gi, "");
    // Algumas páginas do CBR injetam um quiz promocional completo no corpo
    // retornado pelo extrator. Ele não pertence à matéria.
    const cbrQuizIndex = value.search(/\nCBR Exclusive\s*[·•-]?\s*Quiz\b/i);
    if (cbrQuizIndex >= 0) value = value.slice(0, cbrQuizIndex);
    const cbrPromoIndex = value.search(/\n(?:\[\s*\]\([^)]*repackz\.cbr\.com|##\s*\[Adriano Di Benedetto)/i);
    if (cbrPromoIndex >= 0) value = value.slice(0, cbrPromoIndex);
    // O CBR representa cards e players de vídeo como links Markdown.
    value = value.replace(/\n[^\n]*(?:Visit|WATCH|NEXT)[^\n]*\n(?:\[(?:Video|VÃ­deo) \d+\][^\n]*\n)?[\s\S]*?(?=\n(?:Following|The series|A nova coleÃ§Ã£o|Scott Snyder's All Star))/gi, "\n");
    value = value.replace(/\n\[(?:Video|VÃ­deo) \d+\][^\n]*\n?/gi, "\n");
    const infoBoxIndex = value.search(/\n\\?#{1,6}\s*(?:Batman|\[Batman\]\([^)]*tag\/batman[^)]*\))\s*\n/i);
    if (infoBoxIndex >= 0) value = value.slice(0, infoBoxIndex);
    value = value.replace(/\n\*\*Google is updating how content is shown\.[\s\S]*$/i, "");
    // O Jina também devolve a interface do CBR (menu, anúncios, player e rodapé).
    // Esses elementos não fazem parte da matéria e deixam o leitor interno ilegível.
    value = value.replace(/\n(?:#{1,6}\s*)?Batman\nFirst Film Batman:[\s\S]*$/i, "");
    value = value.replace(/\n(?:#{1,6}\s*)?(?:Recommended|Trending|Most Popular|Comments)[\s\S]*$/i, "");
    return value.split("\n").map(line => {
      const normalized = line.trim();
      if (!normalized) return "";
      if (/^\[(?:Video|VÃ­deo) \d+\]\(https?:\/\/[^)]+\)$/i.test(normalized)
        || /^\[[^\]]*(?:Visit|WATCH|NEXT|Remover anÃºncios)[^\]]*\]\(https?:\/\/[^)]+\)$/i.test(normalized)
        || /^Scott Snyder's Complete All Star Batman Returns In Paperback$/i.test(normalized)) return "";
      const cbrInterfaceNoise = /^(?:Menu|Sign in(?: now)?|Log in|Create account|Add Us|Follow|Like|Listen|Thread|More Action|Preferred Source|Upgrade to Premium|Remove Ads|Remover anúncios|Advertisement|Advertise|Now Playing|Video Player is loading\.|Play|Pause|Mute|Unmute|Current Time|Hora actual|Duration|Duração|Loaded:|Carregado:|Stream Type|Tipo de Fluxo|Seek to live|Procurar viver|Playback Rate|Chapters|Capítulos|Descriptions|descrições desligadas, selecionadas|Audio Track|Faixa de áudio|Picture-in-Picture|Fullscreen|Tela cheia|This is a modal window\.|The media could not be loaded|Não foi possível carregar a multimédia|Here is a fact-based summary of the story contents:|Try something different:|Share this article|Compartilhar|Subscribe|Newsletter|Image via .*)$/i.test(normalized)
        || /^(?:•\s*)?(?:Chapters|Capítulos|descriptions off, selected|descrições desligadas, selecionadas|captions off, selected|legendas desligadas, seleccionadas|English|Português)$/i.test(normalized)
        || /^(?:Video \d+|Skip Ad|Audio \d+|[\d:./×x-]+)$/i.test(normalized)
        || /^(?:Vídeo \d+|Pular anúncio|Áudio \d+|VIGIA|PRÓXIMO|WATCH|NEXT|Reproduzir vídeo|Visite|Expandir\/Recolher)$/i.test(normalized)
        || /^\d{1,2}:\d{2}(?:\s*\/\s*\d{1,2}:\d{2})?(?:\s+\d+[×x])?$/i.test(normalized);
      return !cbrInterfaceNoise && !/^Image \d+(?::|$)/i.test(normalized) && !/^Pular para o conte[uú]do$/i.test(normalized)
        && !/^Pesquisar\.\.\.$/i.test(normalized) && !/^Compartilhe:/i.test(normalized)
        && !/^Estimated reading time:/i.test(normalized) && !/^By\s*[^\n]+$/i.test(normalized)
        && !/^Published\s*(?:on|:)?.*$/i.test(normalized) && normalized !== title ? line : "";
    }).join("\n");
  }

  function newsMarkdownToHtml(markdown, title = "") {
    const lines = cleanNewsMarkdown(markdown, title).split("\n");
    const html = [];
    let paragraph = [];
    const flush = () => { if (paragraph.length) { html.push(`<p>${paragraph.join(" ")}</p>`); paragraph = []; } };
    lines.forEach(line => {
      const value = line.trim();
      if (!value) return flush();
      if (/^#{1,3}\s+/.test(value)) { flush(); html.push(`<h2>${escapeHTML(value.replace(/^#{1,3}\s+/, ""))}</h2>`); return; }
      if (/^[-*]\s+/.test(value)) { flush(); html.push(`<p>• ${escapeHTML(value.replace(/^[-*]\s+/, ""))}</p>`); return; }
      paragraph.push(escapeHTML(value)
        .replace(/!\[((?!tracking|pixel)[^\]]*)\]\((https?:\/\/(?!pixel\.wp\.com|gravatar\.com\/avatar|authors\/|ids(?:\d+)?\.ad\.gt|adnxs|openx|pubmatic|rubiconproject|adsrvr|doubleclick|360yield|sonobi|tapad)[^)\s]+)(?:\s+"[^"]*")?\)/gi, '<img src="$2" alt="$1" loading="lazy">')
        .replace(/\*\*(.+?)\*\*/g, "<strong>$1</strong>")
        .replace(/\\?_(.+?)\\?_/g, "<em>$1</em>")
        .replace(/\[([^\]]+)\]\((https?:[^)]+)\)/g, '<a href="$2" target="_blank" rel="noopener noreferrer">$1</a>'));
    });
    flush();
    return html.join("");
  }

  async function openCharacterNewsArticle(article) {
    article = { ...article, title: decodeNewsText(article?.title), description: decodeNewsText(article?.description) };
    const overlay = document.createElement("div");
    overlay.className = "modal-backdrop wiki-reader-backdrop";
    overlay.innerHTML = `<article class="modal wiki-reader-modal character-news-reader"><div class="section-head"><div><div class="eyebrow">${escapeHTML(article.site)} · leitura interna</div><h2>${escapeHTML(article.title)}</h2></div><div class="wiki-reader-actions"><button type="button" class="small-btn" data-close>Fechar</button></div></div><div class="wiki-reader-content">${article.image ? `<img class="character-news-hero-image" src="${escapeHTML(article.image)}" alt="Imagem de ${escapeHTML(article.title)}" loading="lazy">` : ""}<p class="section-subtitle">Carregando matéria...</p></div></article>`;
    $("#modal-root").appendChild(overlay);
    $("[data-close]", overlay).onclick = () => overlay.remove();
    overlay.addEventListener("click", event => { if (event.target === overlay) overlay.remove(); });
    const content = $(".wiki-reader-content", overlay);
    const heroImage = article.image ? `<img class="character-news-hero-image" src="${escapeHTML(article.image)}" alt="Imagem de ${escapeHTML(article.title)}" loading="lazy">` : "";
    try {
      const target = new URL(article.url);
      if (target.hostname === "news.google.com") {
        const summary = article.description || article.title;
        content.innerHTML = `${heroImage}<p>${escapeHTML(summary)}</p><p class="news-source-note">O Google News encontrou esta matéria, mas o site de origem não permitiu a extração automática do texto completo.<br><a href="${escapeHTML(article.url)}" target="_blank" rel="noopener noreferrer">Abrir referência original em ${escapeHTML(article.site)}</a></p>`;
        return;
      }
      const proxyUrl = `https://r.jina.ai/http://${target.host}${target.pathname}${target.search}`;
      const response = await fetchWithTimeout(proxyUrl, { cache: "no-store" }, 15000);
      if (!response.ok) throw new Error("Matéria indisponível");
      const rawArticle = await Promise.race([
        response.text(),
        new Promise((_, reject) => setTimeout(() => reject(new Error("Tempo limite ao ler matéria")), 10000)),
      ]);
      let html = newsMarkdownToHtml(rawArticle, article.title);
      content.innerHTML = `${heroImage}${html || `<p>Não foi possível extrair o texto desta matéria.</p>`}<p class="news-source-note">Fonte: <a href="${escapeHTML(article.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(article.site)}</a></p>`;
      const isCbrArticle = article.siteId === "cbr"
        || String(article.site || "").trim().toLowerCase() === "cbr"
        || /(^|\.)cbr\.com$/i.test(target.hostname);
      if (isCbrArticle) {
        content.innerHTML = heroImage + '<p class="section-subtitle">Traduzindo matéria...</p>';
        html = await Promise.race([
          translateHtmlToPortuguese(html, "en"),
          new Promise(resolve => setTimeout(() => resolve(html), 90000)),
        ]);
      }
      content.innerHTML = `${heroImage}${html || `<p>Não foi possível extrair o texto desta matéria.</p>`}<p class="news-source-note">Fonte: <a href="${escapeHTML(article.url)}" target="_blank" rel="noopener noreferrer">${escapeHTML(article.site)}</a></p>`;
    } catch (error) {
      content.innerHTML = `<p>Não foi possível carregar esta matéria dentro do site.</p><p><a href="${escapeHTML(article.url)}" target="_blank" rel="noopener noreferrer">Abrir matéria original em ${escapeHTML(article.site)}</a></p>`;
      console.warn("Leitura interna de notícia indisponível", error);
    }
  }

  const characterNewsCache = new Map();

  async function loadCharacterNews(character) {
    const host = $("[data-character-news]");
    if (!host || host.dataset.newsLoading === "true" || host.dataset.newsLoaded === "true") return;
    host.dataset.newsLoading = "true";
    const cacheKey = String(character || "").trim().toLowerCase();
    let items = characterNewsCache.get(cacheKey) || [];
    if (!characterNewsCache.has(cacheKey)) {
      try {
      items = await Promise.race([
        searchCharacterNews(character),
        new Promise(resolve => setTimeout(() => resolve([]), 20000)),
      ]);
    } catch (error) {
      console.warn("Notícias e curiosidades indisponíveis", error);
    }
    items = await Promise.all(items.map(async item => {
      const isCbr = item.siteId === "cbr"
        || String(item.site || "").trim().toLowerCase() === "cbr"
        || /(^|\.)cbr\.com$/i.test(item.url || "");
      if (!isCbr) return item;
      const title = await translateToPortuguese(item.title, "en");
      const description = item.description && item.description !== item.title
        ? await translateToPortuguese(item.description, "en")
        : title;
      return { ...item, title, description };
    }));
      characterNewsCache.set(cacheKey, items);
    }
    const grid = $(".character-news-grid", host);
    if (grid) grid.innerHTML = items.length
      ? items.map((item, index) => `<button type="button" class="character-news-card" data-character-news-index="${index}">${item.image ? `<img class="character-news-card-image" src="${escapeHTML(item.image)}" alt="" loading="lazy">` : ""}<span class="eyebrow">${escapeHTML(item.site)}</span><strong>${escapeHTML(item.title)}</strong><p>${escapeHTML(item.description || `Leia notícias e curiosidades sobre ${character}.`)}</p><span class="small-btn">Ler no pop-up</span></button>`).join("")
      : '<div class="empty">Não encontramos páginas sobre este personagem agora.</div>';
    host._newsItems = items;
    host.dataset.newsLoaded = "true";
    $$('[data-character-news-index]', host).forEach(button => button.addEventListener("click", () => openCharacterNewsArticle(items[Number(button.dataset.characterNewsIndex)])));
  }

  async function openFandomReader(reference, existingOverlay = null) {
    if (!reference?.url) return;
    const overlay = existingOverlay || document.createElement("div");
    const loadToken = String(Number(overlay.dataset.fandomLoadToken || 0) + 1);
    overlay.dataset.fandomLoadToken = loadToken;
    if (!existingOverlay) {
      overlay.className = "modal-backdrop wiki-reader-backdrop";
      overlay.innerHTML = `<article class="modal wiki-reader-modal"><div class="section-head"><div><div class="eyebrow">Fandom · leitura interna</div><h2>${escapeHTML(reference.title)}</h2></div><div class="wiki-reader-actions"><button type="button" class="small-btn" data-close>Fechar</button></div></div><div class="wiki-reader-content"><p class="section-subtitle">Carregando artigo atualizado...</p></div></article>`;
      $("#modal-root").appendChild(overlay);
      $("[data-close]", overlay).onclick = () => overlay.remove();
      overlay.addEventListener("click", event => { if (event.target === overlay) overlay.remove(); });
    } else {
      $(".wiki-reader-modal h2", overlay).textContent = reference.title;
      $(".wiki-reader-content", overlay).innerHTML = '<p class="section-subtitle">Carregando artigo atualizado...</p>';
    }
    const readerContent = $(".wiki-reader-content", overlay);
    if (readerContent && !readerContent.dataset.fandomLinksBound) {
      readerContent.dataset.fandomLinksBound = "true";
      readerContent.addEventListener("click", event => {
        const link = event.target.closest("a[href]");
        if (!link) return;
        const linkedReference = fandomArticleFromUrl(link.href);
        if (linkedReference) {
          event.preventDefault();
          openFandomReader(linkedReference, overlay);
          return;
        }
        let url;
        try { url = new URL(link.href); } catch { return; }
        if (!/(^|\.)wikipedia\.org$/i.test(url.hostname)) return;
        const linkedTitle = wikiArticleTitleFromUrl(url.href);
        if (!linkedTitle || linkedTitle.startsWith("Especial:")) return;
        event.preventDefault();
        openWikiReaderByTitle(linkedTitle, overlay, url.href).catch(error => {
          console.warn("Link da WikipÃ©dia indisponÃ­vel", error);
          toast("NÃ£o foi possÃ­vel carregar este artigo da WikipÃ©dia.");
        });
      });
    }
    try {
      const result = await fetchFandomApi(reference);
      if (!result.ok) throw new Error("Fandom indisponível");
      const data = await result.json();
      const content = $(".wiki-reader-content", overlay);
      if (overlay.dataset.fandomLoadToken !== loadToken) return;
      if (!data.parse?.text?.["*"]) throw new Error("Artigo do Fandom não encontrado");
      if (content) {
        const sourceLanguage = fandomSourceLanguage(reference, data.parse.text["*"]);
        const articleHtml = fandomTextFromHtml(data.parse.text["*"], reference.url);
        content.innerHTML = articleHtml;
        content.dataset.visibleTranslationLanguage = sourceLanguage;
        addWikiSectionToggles(content);
        if (!content.dataset.visibleTranslationBound) {
          content.dataset.visibleTranslationBound = "true";
          let translationTimer = null;
          content.addEventListener("scroll", () => {
            clearTimeout(translationTimer);
            translationTimer = setTimeout(() => translateVisibleWikiContent(content, content.dataset.visibleTranslationLanguage).catch(() => {}), 180);
          }, { passive: true });
        }
        if (!["pt", "auto"].includes(sourceLanguage)) {
          translateToPortuguese(reference.title, sourceLanguage).then(translatedTitle => {
            if (overlay.dataset.fandomLoadToken !== loadToken || !overlay.isConnected) return;
            const heading = $(".wiki-reader-modal h2", overlay);
            if (heading && translatedTitle) heading.textContent = translatedTitle;
          }).catch(() => {});
          translateVisibleWikiContent(content, sourceLanguage).then(() => {
            if (!content.isConnected || !overlay.isConnected || overlay.dataset.fandomLoadToken !== loadToken) return;
            addWikiSectionToggles(content);
          }).catch(error => console.warn("Tradução do Fandom indisponível", error));
        }
      }
    } catch (error) {
      const content = $(".wiki-reader-content", overlay);
      if (content) content.innerHTML = "<p>Não foi possível carregar o artigo atualizado.</p>";
      console.warn("Leitor do Fandom indisponível", error);
    }
  }

  function addWikiSectionToggles(root) {
    [...root.querySelectorAll("h2, h3")].forEach(heading => {
      if (heading.querySelector("[data-wiki-section-toggle]")) return;
      const level = Number(heading.tagName.slice(1));
      const button = document.createElement("button");
      button.type = "button";
      button.className = "wiki-section-toggle";
      button.dataset.wikiSectionToggle = "true";
      button.setAttribute("aria-expanded", "true");
      button.textContent = "−";
      button.title = "Recolher seção";
      heading.prepend(button);
      const sectionNodes = [];
      let sibling = heading.nextElementSibling;
      while (sibling) {
        const siblingLevel = /H[23]/.test(sibling.tagName) ? Number(sibling.tagName.slice(1)) : null;
        if (siblingLevel && siblingLevel <= level) break;
        sectionNodes.push(sibling);
        sibling = sibling.nextElementSibling;
      }
      if (!sectionNodes.length) {
        let container = heading.parentElement;
        while (container && container !== root && !container.matches(".infobox, .portable-infobox, .navbox")) {
          const index = [...container.children].indexOf(heading);
          if (index >= 0 && index < container.children.length - 1) {
            sectionNodes.push(...[...container.children].slice(index + 1));
            break;
          }
          heading = container;
          container = container.parentElement;
        }
      }
      button.addEventListener("click", () => {
        const expanded = button.getAttribute("aria-expanded") !== "false";
        button.setAttribute("aria-expanded", String(!expanded));
        button.textContent = expanded ? "+" : "−";
        button.title = expanded ? "Expandir seção" : "Recolher seção";
        sectionNodes.forEach(node => { node.hidden = expanded; });
      });
    });
  }

  async function openWikiReader(pageId, title, existingOverlay = null, sourceUrl = "") {
    const overlay = existingOverlay || document.createElement("div");
    if (sourceUrl) overlay.dataset.wikiSource = sourceUrl;
    if (!existingOverlay) {
      overlay.className = "modal-backdrop wiki-reader-backdrop";
      overlay.innerHTML = `<article class="modal wiki-reader-modal"><div class="section-head"><div><div class="eyebrow">Wikipédia · leitura interna</div><h2>${escapeHTML(title)}</h2></div><div class="wiki-reader-actions"><button type="button" class="small-btn" data-close>Fechar</button></div></div><div class="wiki-reader-content"><p class="section-subtitle">Carregando artigo atualizado...</p></div></article>`;
      $("#modal-root").appendChild(overlay);
      $("[data-close]", overlay).onclick = () => overlay.remove();
      overlay.addEventListener("click", event => { if (event.target === overlay) overlay.remove(); });
    } else {
      $(".wiki-reader-modal h2", overlay).textContent = title;
      $(".wiki-reader-content", overlay).innerHTML = '<p class="section-subtitle">Carregando artigo atualizado...</p>';
    }
    const readerContent = $(".wiki-reader-content", overlay);
    if (readerContent && !readerContent.dataset.wikiLinksBound) {
      readerContent.dataset.wikiLinksBound = "true";
      readerContent.addEventListener("click", event => {
        const link = event.target.closest("a[href]");
        if (!link) return;
        let url;
        try { url = new URL(link.href); } catch { return; }
        const linkedFandom = fandomArticleFromUrl(url.href);
        if (linkedFandom) {
          event.preventDefault();
          openFandomReader(linkedFandom, overlay);
          return;
        }
        if (!/(^|\.)wikipedia\.org$/i.test(url.hostname)) return;
        const linkedTitle = wikiArticleTitleFromUrl(url.href);
        if (!linkedTitle || linkedTitle.startsWith("Especial:")) return;
        event.preventDefault();
        openWikiReaderByTitle(linkedTitle, overlay, url.href).catch(error => {
          console.warn("Link da Wikipédia indisponível", error);
          toast("Não foi possível carregar este artigo da Wikipédia.");
        });
      });
    }
    try {
      const sourceUrl = overlay.dataset.wikiSource || "";
      const fetchWiki = async url => {
        const controller = new AbortController();
        const timeout = setTimeout(() => controller.abort(), 12000);
        try { return await fetch(url, { cache: "no-store", signal: controller.signal }); }
        finally { clearTimeout(timeout); }
      };
      let result = await fetchWiki(wikiApiUrl({ action: "parse", pageid: String(pageId), prop: "text|displaytitle", disabletoc: "0" }, sourceUrl));
      if (!result.ok) throw new Error("Wikipedia indisponível");
      let data = await result.json();
      if (!data.parse?.text?.["*"]) {
        result = await fetchWiki(wikiApiUrl({ action: "parse", page: title, prop: "text|displaytitle", disabletoc: "0" }, sourceUrl));
        if (!result.ok) throw new Error("Artigo da Wikipédia indisponível");
        data = await result.json();
      }
      if (!data.parse?.text?.["*"]) throw new Error("Artigo da Wikipédia não encontrado");
      const content = $(".wiki-reader-content", overlay);
      if (content) {
        const articleHtml = wikiTextFromHtml(data.parse.text["*"], sourceUrl || "https://pt.wikipedia.org");
        const sourceLanguage = wikiLanguageFromUrl(sourceUrl);
        content.innerHTML = articleHtml;
        addWikiSectionToggles(content);
        if (!content.dataset.visibleTranslationBound) {
          content.dataset.visibleTranslationBound = "true";
          let translationTimer = null;
          content.addEventListener("scroll", () => {
            clearTimeout(translationTimer);
            translationTimer = setTimeout(() => translateVisibleWikiContent(content, sourceLanguage).catch(() => {}), 180);
          }, { passive: true });
        }
        if (!["pt", "auto"].includes(sourceLanguage)) translateVisibleWikiContent(content, sourceLanguage).catch(() => {});
      }
    } catch (error) {
      const content = $(".wiki-reader-content", overlay);
      if (content) content.innerHTML = "<p>Não foi possível carregar o artigo atualizado.</p>";
      console.warn("Leitor da Wikipédia indisponível", error);
    }
  }

  async function attachComments(item, overlay) {
    if (!sb || state.session?.offline || navigator.onLine === false) return;
    const panel = document.createElement("details");
    panel.className = "reader-comments";
    panel.innerHTML = `<div class="section-head"><h3>Comentários</h3></div><div class="comments-list"><span class="section-subtitle">Carregando...</span></div>${state.session ? '<form class="comment-form"><textarea name="body" maxlength="1000" required placeholder="Escreva um comentário..."></textarea><button class="small-btn">Comentar</button></form>' : '<p class="section-subtitle">Entre para comentar.</p>'}`;
    const summary = document.createElement("summary");
    summary.textContent = "Comentários";
    const content = document.createElement("div");
    content.className = "comments-content";
    while (panel.firstChild) content.appendChild(panel.firstChild);
    panel.append(summary, content);
    $(".comment-form button", panel)?.setAttribute("type", "submit");
    overlay.appendChild(panel);
    const list = $(".comments-list", panel);
    const refresh = async () => {
      const result = await sb.from("comments").select("id, body, created_at, profiles(username, avatar_url, title, plan, faction_id)").eq("item_id", item.id).order("created_at", { ascending: false });
      if (result.error) {
        list.innerHTML = '<span class="section-subtitle">Não foi possível carregar os comentários.</span>';
        return;
      }
      list.innerHTML = (result.data || []).map(comment => {
        const username = cleanUsername(comment.profiles?.username || "usuário");
        const profile = { ...(comment.profiles || {}), username };
        return `<article class="comment"><div class="comment-author-row">${avatarMarkup(profile, "comment-avatar")}<div class="comment-author-info"><a class="comment-author" href="${publicProfileHref(username)}" target="_blank" rel="noopener">@${escapeHTML(username)}</a>${staffTitleMarkup(profile)}${profile.title ? `<span class="comment-title">${escapeHTML(profile.title)}</span>` : ""}</div></div><p>${escapeHTML(comment.body)}</p></article>`;
      }).join("") || '<span class="section-subtitle">Nenhum comentário ainda.</span>';
    };
    await refresh();
    hydrateCommentFactionRoleTitles(panel);
    $(".comment-form", panel)?.addEventListener("submit", async event => {
      event.preventDefault();
      event.stopImmediatePropagation();
      const form = event.currentTarget;
      const body = String(new FormData(form).get("body") || "").trim();
      const button = $("button", form);
      if (!state.session?.user?.id) { toast("Entre na sua conta para comentar."); return; }
      if (!body) return;
      button.disabled = true;
      const result = await sb.from("comments").insert({ user_id: state.session.user.id, item_id: item.id, body });
      if (result.error) toast(result.error.message);
      else { awardAchievement("first_comment"); awardProfileXp("comment", `comment:${item.id}:${Date.now()}`); form.reset(); await refresh(); }
      button.disabled = false;
    });
  }

