  function followSummary(profileId, followerCount, followingCount) {
    return `<div class="profile-follow-summary"><button class="profile-follow-link" data-follow-list="followers" data-follow-profile-id="${escapeHTML(profileId)}">${followerCount || 0} seguidores</button><span> · </span><button class="profile-follow-link" data-follow-list="following" data-follow-profile-id="${escapeHTML(profileId)}">${followingCount || 0} seguindo</button></div>`;
  }

  async function openFollowList(kind, profileId) {
    if (!sb || !profileId) return toast("A lista de seguidores ainda não está disponível.");
    const isFollowers = kind === "followers";
    const relation = isFollowers
      ? await sb.from("profile_follows").select("follower_id").eq("following_id", profileId)
      : await sb.from("profile_follows").select("following_id").eq("follower_id", profileId);
    if (relation.error) return toast("Não foi possível carregar essa lista.");
    const ids = (relation.data || []).map(row => isFollowers ? row.follower_id : row.following_id).filter(Boolean);
    const profiles = ids.length ? await sb.from("profiles").select("id, username, avatar_url, title, plan, faction_id, is_bot, is_official, bot_type").in("id", ids) : { data: [] };
    if (profiles.error) return toast("Não foi possível carregar os perfis.");
    const byId = new Map((profiles.data || []).map(profile => [profile.id, profile]));
    const title = isFollowers ? "Seguidores" : "Seguindo";
    const overlay = document.createElement("div");
    overlay.className = "modal-backdrop";
    overlay.innerHTML = `<div class="modal follow-list-modal"><div class="section-head"><div><h2>${title}</h2><div class="section-subtitle">${ids.length} perfil(is)</div></div><button class="small-btn" data-close>Fechar</button></div><div class="follow-list">${ids.map(id => { const profile = byId.get(id); return profile ? `<a class="follow-list-item" href="${escapeHTML(publicProfileHref(profile.username))}">${avatarMarkup(profile, "follow-list-avatar")}<span><b>${factionDot(profile)}@${escapeHTML(profile.username)} ${officialAiBadge(profile)}</b>${profile.title ? `<small>${escapeHTML(profile.title)}</small>` : ""}</span></a>` : ""; }).join("") || '<div class="empty">Nenhum perfil nesta lista.</div>'}</div></div>`;
    $("#modal-root").appendChild(overlay);
    $("[data-close]", overlay).onclick = () => overlay.remove();
    overlay.addEventListener("click", event => { if (event.target === overlay) overlay.remove(); });
  }

  async function toggleFactionImprintPin(button) {
    const factionId = currentFactionId();
    const imprintName = String(button.dataset.factionImprintPin || "").trim();
    if (!factionId || !imprintName || !state.session?.user?.id) return;
    const key = publisherKey(imprintName);
    const pinned = button.dataset.factionImprintPinned === "true";
    const result = await sb.rpc("toggle_faction_imprint_pin", { p_faction_id: factionId, p_imprint_key: key, p_imprint_name: imprintName, p_pinned: !pinned });
    if (result.error) return toast(result.error.message || "Não foi possível atualizar o destaque do selo.");
    const mapKey = `${factionId}:${key}`;
    if (pinned) state.factionPinnedImprints.delete(mapKey);
    else state.factionPinnedImprints.set(mapKey, { faction_id: factionId, imprint_key: key, imprint_name: imprintName });
    render();
  }

