  const CHAT_ROOMS = [
    { id: "geral", name: "Chat Geral", access: "public" },
    { id: "decenautas", name: "Decenautas", access: "public" },
    { id: "marvetes", name: "Marvetes", access: "public" },
    { id: "leitores-colecionadores", name: "Leitores e Colecionadores", access: "premium" },
    { id: "staff", name: "Chat da Staff", access: "staff" },
    { id: "faccao-aurora-rubra", name: "Maravilhas", access: "faction", factionId: "aurora-rubra" },
    { id: "faccao-vigilia-cobalto", name: "Legado", access: "faction", factionId: "vigilia-cobalto" },
    { id: "faccao-forja-dourada", name: "Ruptura", access: "faction", factionId: "forja-dourada" },
    { id: "faccao-nevoa-violeta", name: "Horizonte", access: "faction", factionId: "nevoa-violeta" }
  ];
  const SHERIFF_ROOM_IDS = new Set(["geral", "decenautas", "marvetes", "leitores-colecionadores"]);
  const isSheriffRoom = room => Boolean(room && SHERIFF_ROOM_IDS.has(room.id) && !room.factionId);
  const isFactionChatSheriff = (room, userId) => Boolean(room?.factionId && userId && state.factionRoles.some(role => role.faction_id === room.factionId && role.user_id === userId && ["leader", "curator"].includes(role.role)));
  const factionChatSheriffIds = room => new Set((state.factionRoles || []).filter(role => role.faction_id === room?.factionId && ["leader", "curator"].includes(role.role)).map(role => String(role.user_id)));

  function canOpenChatRoom(room) {
    if (room.factionId) return ["moderator", "banca", "admin"].includes(state.profile?.plan) || state.profile?.faction_id === room.factionId;
    return room.access === "public"
      || (room.access === "premium" && hasLegendaryAccess())
      || (room.access === "staff" && ["moderator", "banca", "admin"].includes(state.profile?.plan));
  }

  function chatRoomLabel(room) {
    if (room.factionId) return "Exclusivo";
    return room.access === "premium" ? "Lenda" : room.access === "staff" ? "Staff" : "Público";
  }

  async function loadChatSenderVisuals(senderIds) {
    const ids = [...new Set(senderIds.filter(Boolean))];
    const visuals = new Map(ids.map(id => [id, { coverChoices: new Map(), coverStyles: new Map() }]));
    if (!ids.length || !sb) return visuals;
    const [choicesResult, stylesResult] = await Promise.all([
      sb.from("user_cover_choices").select("user_id, item_id, variant_key, cover_url").in("user_id", ids),
      sb.from("user_cover_styles").select("user_id, item_id, style").in("user_id", ids)
    ]);
    (choicesResult.data || []).forEach(choice => visuals.get(choice.user_id)?.coverChoices.set(choice.item_id, choice));
    (stylesResult.data || []).forEach(style => visuals.get(style.user_id)?.coverStyles.set(style.item_id, style.style));
    return visuals;
  }

  function chatTop10PreviewMarkup(preview, url) {
    const story = preview.list.list_type === "story";
    const items = (preview.items || []).slice(0, 3);
    const rows = items.map((item, index) => {
      const storyEntry = story ? state.db.library.find(entry => String(entry.id) === String(item.character_key)) : null;
      const image = item.image_url || (storyEntry ? coverFor(storyEntry) : characterSettingForName(item.character_name)?.cover_url) || "assets/batmanicon.jpg";
      return `<li class="chat-top10-preview-item" data-chat-top10-preview-item="${escapeHTML(item.id)}" data-chat-top10-preview-type="${story ? "story" : "character"}" data-chat-top10-preview-key="${escapeHTML(item.character_key || item.character_name)}"><span>${index + 1}</span><img src="${escapeHTML(image)}" alt="${escapeHTML(item.character_name)}" loading="lazy"><strong>${escapeHTML(item.character_name)}</strong><span class="top10-vote-actions"><button type="button" class="small-btn" data-chat-top10-vote="1">👍 ${item.likes || 0}</button><button type="button" class="small-btn" data-chat-top10-vote="-1">👎 ${item.dislikes || 0}</button></span></li>`;
    }).join("");
    return `<div class="chat-top10-preview" data-chat-top10-preview="${escapeHTML(url)}" data-chat-top10-hydrated="true"><div class="chat-top10-preview-head"><strong>${escapeHTML(preview.list.name)}</strong><span>3 primeiros</span></div><ol>${rows || '<li class="empty">Lista sem itens.</li>'}</ol><button type="button" class="small-btn" data-chat-top10-open="${escapeHTML(preview.list.id)}" data-chat-top10-owner="${escapeHTML(preview.owner.username)}">Abrir lista completa</button></div>`;
  }

  async function loadChatTop10Preview(url) {
    if (!sb) return null;
    const parsed = new URL(url, window.location.href);
    const listId = parsed.searchParams.get("lista_top10");
    const username = parsed.searchParams.get("perfil");
    if (!listId || !username) return null;
    const cacheKey = `${username}:${listId}`;
    if (state.chatTop10PreviewCache.has(cacheKey)) return state.chatTop10PreviewCache.get(cacheKey);
    const owner = await sb.from("profiles").select("id, username").ilike("username", username).maybeSingle();
    if (owner.error || !owner.data) return null;
    const listResult = await sb.from("profile_top10_lists").select("id, owner_id, name, list_type, is_public").eq("id", listId).eq("owner_id", owner.data.id).eq("is_public", true).maybeSingle();
    if (listResult.error || !listResult.data) return null;
    const itemsResult = await sb.from("profile_top10_items").select("id, character_key, character_name, image_url, rank").eq("list_id", listId).order("rank", { ascending: true }).limit(3);
    if (itemsResult.error) return null;
    const items = itemsResult.data || [];
    const votesResult = items.length ? await sb.from("profile_top10_item_votes").select("item_id, user_id, vote").in("item_id", items.map(item => item.id)) : { data: [] };
    items.forEach(item => {
      const votes = (votesResult.data || []).filter(vote => String(vote.item_id) === String(item.id));
      item.likes = votes.filter(vote => vote.vote === 1).length;
      item.dislikes = votes.filter(vote => vote.vote === -1).length;
      item.userVote = votes.find(vote => String(vote.user_id) === String(state.session?.user?.id))?.vote || 0;
    });
    const preview = { list: listResult.data, owner: owner.data, items };
    state.chatTop10PreviewCache.set(cacheKey, preview);
    return preview;
  }

  async function hydrateChatTop10Previews(root) {
    if (!root) return;
    hydrateChatInternalPreviews(root);
    const previews = [...root.querySelectorAll("[data-chat-top10-preview]:not([data-chat-top10-hydrated])")];
    await Promise.all(previews.map(async previewElement => {
      if (!previewElement.isConnected) return;
      const preview = await loadChatTop10Preview(previewElement.dataset.chatTop10Preview);
      if (preview && previewElement.isConnected) previewElement.outerHTML = chatTop10PreviewMarkup(preview, previewElement.dataset.chatTop10Preview);
    }));
    $$('[data-chat-top10-open]', root).forEach(button => {
      if (button.dataset.bound) return;
      button.dataset.bound = "true";
      button.onclick = () => {
        button.closest(".chat-modal, .comments-modal, .top10-comments-modal")?.querySelector("[data-close]")?.click();
        loadPublicProfile(button.dataset.chatTop10Owner, null, false, { top10ListId: button.dataset.chatTop10Open });
      };
    });
    $$('[data-chat-top10-preview-item]', root).forEach(row => {
      if (row.dataset.bound) return;
      row.dataset.bound = "true";
      row.onclick = event => {
        if (event.target.closest("button")) return;
        row.closest(".chat-modal, .comments-modal, .top10-comments-modal")?.querySelector("[data-close]")?.click();
        if (row.dataset.chatTop10PreviewType === "story") openReader(state.db.library.find(item => String(item.id) === String(row.dataset.chatTop10PreviewKey)));
        else openEntityPage("character", row.dataset.chatTop10PreviewKey);
      };
      row.onkeydown = event => { if (event.key === "Enter" || event.key === " ") { event.preventDefault(); row.click(); } };
      row.tabIndex = 0;
    });
    $$('[data-chat-top10-vote]', root).forEach(button => {
      if (button.dataset.bound) return;
      button.dataset.bound = "true";
      button.onclick = event => {
        event.stopPropagation();
        const row = button.closest("[data-chat-top10-preview-item]");
        const previewElement = button.closest("[data-chat-top10-preview]");
        const preview = previewElement && loadChatTop10Preview(previewElement.dataset.chatTop10Preview);
        Promise.resolve(preview).then(data => {
          const item = data?.items?.find(entry => String(entry.id) === String(row?.dataset.chatTop10PreviewItem));
          if (item) voteTop10Item(item, Number(button.dataset.chatTop10Vote), button.closest(".top10-vote-actions"), data.list);
        });
      };
    });
  }

  async function hydrateChatInternalPreviews(root) {
    const characterPreviews = [...(root?.querySelectorAll?.('[data-chat-character-preview]:not([data-chat-internal-hydrated])') || [])];
    if (sb) await Promise.all(characterPreviews.map(async preview => {
      const name = preview.dataset.chatCharacterPreview;
      if (!name) return;
      let setting = characterSettingForName(name);
      if (!setting) {
        const result = await sb.from("character_settings").select("character_key, character_name, cover_url").ilike("character_name", name).maybeSingle();
        if (!result.error && result.data) {
          state.characterSettings.set(result.data.character_key, result.data);
          setting = result.data;
        }
      }
      if (!preview.isConnected) return;
      const image = setting?.cover_url || wikiCharacterImageCache.get(name) || "assets/batmanicon.jpg";
      preview.outerHTML = `<a class="chat-internal-preview" data-chat-internal-hydrated="true" href="${escapeHTML(preview.dataset.chatCharacterUrl)}" target="_blank" rel="noopener noreferrer"><img class="chat-internal-preview-character" data-chat-character-image="${escapeHTML(name)}" src="${escapeHTML(image)}" alt="Imagem de ${escapeHTML(name)}"><span><b>${escapeHTML(name)}</b><small>Personagem</small></span><span class="chat-internal-preview-arrow">›</span></a>`;
    }));
    if (characterPreviews.length) {
      await loadCharacterWikiCarousel();
      await Promise.all([...root.querySelectorAll('[data-chat-character-image]')].map(async image => {
        const name = image.dataset.chatCharacterImage;
        if (!name || state.characterSettings.get(publisherKey(name))?.cover_url || (wikiCharacterImageCache.get(name) && wikiCharacterImageCache.get(name) !== "assets/batmanicon.jpg")) return;
        try {
          const response = await fetch(wikiApiUrl({ action: "query", generator: "search", gsrsearch: name, gsrnamespace: "0", gsrlimit: "5", prop: "pageimages", piprop: "thumbnail", pithumbsize: "180" }));
          if (!response.ok) return;
          const pages = Object.values((await response.json()).query?.pages || {});
          const source = pages.find(page => page.thumbnail?.source)?.thumbnail?.source;
          if (!source || !image.isConnected) return;
          wikiCharacterImageCache.set(name, source);
          image.src = imageProxyFetchUrl(source);
        } catch {}
      }));
    }
    const entityPreviews = [...(root?.querySelectorAll?.('[data-chat-entity-preview]:not([data-chat-internal-hydrated])') || [])];
    await Promise.all(entityPreviews.map(async preview => {
      const kind = preview.dataset.chatEntityPreviewKind;
      const name = String(preview.dataset.chatEntityPreview || '').trim();
      if (!name || !['publisher', 'imprint'].includes(kind) || !preview.isConnected) return;
      const normalized = publisherKey(name);
      const setting = kind === 'publisher' ? state.publisherSettings.get(normalized) : state.imprintSettings.get(normalized);
      const matchingItems = state.db.library.filter(item => publisherKey(kind === 'publisher' ? item.publisher : item.imprint) === normalized);
      const representative = matchingItems.find(item => item.featuredCoverUrl || item.coverUrl || item.cover) || matchingItems[0];
      const image = setting?.cover_url || (representative ? coverFor(representative) : instantCover({ title: name }));
      const label = kind === 'publisher' ? 'Editora' : 'Selo';
      const count = matchingItems.length ? `<small>${label} · ${matchingItems.length} edição(ões)</small>` : `<small>${label}</small>`;
      preview.outerHTML = `<a class="chat-internal-preview" data-chat-internal-hydrated="true" href="${escapeHTML(preview.dataset.chatEntityPreviewUrl)}" target="_blank" rel="noopener noreferrer"><img class="chat-internal-preview-cover" src="${escapeHTML(proxiedImageUrl(image))}" alt="Imagem de ${escapeHTML(name)}" loading="lazy"><span><b>${escapeHTML(name)}</b>${count}</span><span class="chat-internal-preview-arrow">›</span></a>`;
    }));
    const factionPreviews = [...(root?.querySelectorAll?.('[data-chat-faction-preview]:not([data-chat-internal-hydrated])') || [])];
    await Promise.all(factionPreviews.map(async preview => {
      const factionKey = String(preview.dataset.chatFactionPreview || '').trim();
      const faction = state.factions.find(item => item.id === factionKey || String(item.page_key) === factionKey);
      if (!faction || !preview.isConnected) return;
      const color = /^#(?:[0-9a-f]{3}|[0-9a-f]{6})$/i.test(String(faction.color || '')) ? faction.color : '#777780';
      preview.outerHTML = `<a class="chat-internal-preview chat-faction-preview" data-chat-internal-hydrated="true" style="--chat-faction-color:${escapeHTML(color)}" href="${escapeHTML(preview.dataset.chatFactionPreviewUrl)}" target="_blank" rel="noopener noreferrer"><span class="chat-faction-preview-emblem" aria-hidden="true">${escapeHTML(faction.emblem || '✦')}</span><span><b>${escapeHTML(faction.name || factionKey)}</b><small>Facção</small></span><span class="chat-internal-preview-arrow">›</span></a>`;
    }));
    if (!sb) return;
    const previews = [...(root?.querySelectorAll?.('[data-chat-profile-preview]:not([data-chat-internal-hydrated])') || [])];
    await Promise.all(previews.map(async preview => {
      const username = preview.dataset.chatProfilePreview;
      if (!username) return;
      let profile = state.chatInternalPreviewCache.get(username);
      if (!profile) {
        const result = await sb.from("profiles").select("id, username, avatar_url, title, title_color, faction_id, plan").ilike("username", username).maybeSingle();
        if (result.error || !result.data) return;
        profile = result.data;
        state.chatInternalPreviewCache.set(username, profile);
      }
      if (!preview.isConnected) return;
      const label = preview.dataset.chatProfileLabel || "Perfil público";
      if (preview.dataset.chatProfileCollection) {
        const collectionResult = await sb.from("shelf_collections").select("id, name, cover_url, is_public").eq("id", preview.dataset.chatProfileCollection).eq("owner_id", profile.id).eq("is_public", true).maybeSingle();
        if (collectionResult.error || !collectionResult.data || !preview.isConnected) return;
        const collection = collectionResult.data;
        const cover = collection.cover_url || "assets/estantepb.jpg";
        preview.outerHTML = `<a class="chat-internal-preview" data-chat-internal-hydrated="true" href="${escapeHTML(preview.dataset.chatProfileUrl)}" target="_blank" rel="noopener noreferrer"><img class="chat-internal-preview-cover" src="${escapeHTML(cover)}" alt="Capa da coleção"><span><b>${escapeHTML(collection.name)}</b><small>Coleção pública</small></span><span class="chat-internal-preview-arrow">›</span></a>`;
        return;
      }
      const profileVisual = preview.dataset.chatProfileAlbum === "true"
        ? '<img class="chat-internal-preview-art" src="assets/album/album.jpg" alt="Álbum de figurinhas">'
        : avatarMarkup(profile, "chat-internal-preview-avatar");
      preview.outerHTML = `<a class="chat-internal-preview" data-chat-internal-hydrated="true" href="${escapeHTML(preview.dataset.chatProfileUrl)}" target="_blank" rel="noopener noreferrer">${profileVisual}<span><b>${factionDot(profile)}@${escapeHTML(profile.username)}</b><small>${escapeHTML(profile.title || label)}</small></span><span class="chat-internal-preview-arrow">›</span></a>`;
    }));
  }

  function hydrateCommentLinkPreviews(root = document) {
    if (!root?.querySelectorAll) return;
    $$('.comment > p, .profile-wall-comment > p', root).forEach(body => {
      if (body.querySelector(".chat-top10-preview")) return;
      const text = body.textContent || "";
      if (!/https?:\/\//i.test(text)) return;
      body.innerHTML = chatBodyMarkup(text);
    });
    hydrateChatTop10Previews(root);
  }

  function observeCommentLinkPreviews() {
    const modalRoot = $("#modal-root");
    if (!modalRoot || modalRoot.dataset.commentPreviewObserver) return;
    modalRoot.dataset.commentPreviewObserver = "true";
    new MutationObserver(() => hydrateCommentLinkPreviews(modalRoot)).observe(modalRoot, { childList: true, subtree: true });
  }

  function chatBodyMarkup(body, metadata = {}, senderVisual = null) {
    const mentionMarkup = text => escapeHTML(String(text || ""))
      .replace(/@([A-Za-z0-9_]{3,24})/g, (match, mentionedUsername) => `<a class="comment-mention" href="${escapeHTML(publicProfileHref(mentionedUsername))}" target="_blank" rel="noopener">${match}</a>`)
      .replace(/\*\*([^*\r\n]+)\*\*/g, "<strong>$1</strong>")
      .replace(/(?<!\*)\*([^*\r\n]+)\*(?!\*)/g, '<strong class="chat-emphasis-soft">$1</strong>')
      .replace(/([.!?:])\s+-\s+(?=<strong>)/g, "$1<br>")
      .replace(/\r?\n/g, "<br>");
    const cleanChatUrl = rawUrl => String(rawUrl || "").replace(/[),.!?;:]+$/g, "");
    const isChatImageUrl = rawUrl => {
      let parsed;
      try { parsed = new URL(cleanChatUrl(rawUrl)); } catch { return false; }
      if (!/^https?:$/.test(parsed.protocol)) return false;
      const host = parsed.hostname.toLowerCase();
      const pathname = parsed.pathname.toLowerCase();
      const hasImageExtension = /\.(?:avif|bmp|gif|jpe?g|png|svg|webp)(?:$|\/)/i.test(pathname)
        || /(?:format|fm|type)=(?:avif|bmp|gif|jpe?g|png|svg|webp)(?:&|$)/i.test(parsed.search);
      // Pinterest e Instagram normalmente enviam uma página, não um arquivo.
      // Os CDNs de mídia, quando o usuário cola a URL real, podem ser exibidos.
      const knownImageHost = host === "i.pinimg.com"
        || host.endsWith(".pinimg.com")
        || host.endsWith(".fbcdn.net")
        || host.endsWith(".cdninstagram.com")
        || host === "images.unsplash.com"
        || host === "images.pexels.com";
      return hasImageExtension || knownImageHost;
    };
    const chatUrlMarkup = (rawUrl, label = null) => {
      const cleanUrl = cleanChatUrl(rawUrl);
      if (isChatImageUrl(cleanUrl)) {
        return `<a class="chat-image-link" href="${escapeHTML(cleanUrl)}" target="_blank" rel="noopener noreferrer" data-chat-image-link><img src="${escapeHTML(cleanUrl)}" alt="Imagem enviada no chat" loading="lazy" decoding="async"><span class="chat-image-fallback">Imagem indisponível · abrir link</span></a>`;
      }
      return `<a class="chat-link" href="${escapeHTML(cleanUrl)}" target="_blank" rel="noopener noreferrer">${escapeHTML(label || cleanUrl)}</a>`;
    };
    const internalPreview = rawUrl => {
      const cleanUrl = cleanChatUrl(rawUrl);
      let parsed;
      try { parsed = new URL(cleanUrl, window.location.href); } catch { return null; }
      if (parsed.origin !== window.location.origin || parsed.searchParams.has("ler") || parsed.searchParams.has("lista_top10")) return null;
      const profile = parsed.searchParams.get("perfil");
      const collection = parsed.searchParams.get("lista");
      const album = parsed.searchParams.get("album") === "1";
      const page = parsed.searchParams.get("pagina");
      const faction = parsed.searchParams.get("faccao");
      const kind = parsed.searchParams.get("tipo");
      const value = parsed.searchParams.get("valor");
      const blog = parsed.searchParams.get("blog");
      let title = "Banca Digital";
      let subtitle = "Abrir página";
      if (profile) {
        title = `@${cleanUsername(profile)}`;
        subtitle = album ? "Álbum de figurinhas" : collection ? "Coleção pública" : "Perfil público";
        return `<div class="chat-internal-preview" data-chat-profile-preview="${escapeHTML(cleanUsername(profile))}" data-chat-profile-url="${escapeHTML(cleanUrl)}" data-chat-profile-label="${escapeHTML(subtitle)}" data-chat-profile-album="${album ? "true" : "false"}" data-chat-profile-collection="${escapeHTML(collection || "")}">${album ? '<img class="chat-internal-preview-art" src="assets/album/album.jpg" alt="Álbum de figurinhas">' : ""}<span>${album ? "" : "Carregando perfil..."}</span></div>`;
      } else if (page === "entidade" && value) {
        title = value;
        subtitle = kind === "character" ? "Personagem" : kind ? kind.charAt(0).toUpperCase() + kind.slice(1) : "Página da entidade";
        if (kind === "character") return `<div class="chat-internal-preview" data-chat-character-preview="${escapeHTML(value)}" data-chat-character-url="${escapeHTML(cleanUrl)}"><span>Carregando personagem...</span></div>`;
        if (["publisher", "imprint"].includes(kind)) return `<div class="chat-internal-preview" data-chat-entity-preview="${escapeHTML(value)}" data-chat-entity-preview-kind="${escapeHTML(kind)}" data-chat-entity-preview-url="${escapeHTML(cleanUrl)}"><span>Carregando ${kind === "publisher" ? "editora" : "selo"}...</span></div>`;
      } else if (page === "blogs" && blog) {
        title = "Publicação do blog";
        subtitle = `Blog · ${blog}`;
      } else if (page === "faccoes" && faction) {
        return `<div class="chat-internal-preview" data-chat-faction-preview="${escapeHTML(faction)}" data-chat-faction-preview-url="${escapeHTML(cleanUrl)}"><span>Carregando facção...</span></div>`;
      } else if (page) {
        title = page.charAt(0).toUpperCase() + page.slice(1);
        subtitle = "Página da Banca Digital";
      } else {
        return null;
      }
      return `<a class="chat-internal-preview" href="${escapeHTML(cleanUrl)}" target="_blank" rel="noopener noreferrer"><span class="chat-internal-preview-icon">▣</span><span><b>${escapeHTML(title)}</b><small>${escapeHTML(subtitle)}</small></span><span class="chat-internal-preview-arrow">›</span></a>`;
    };
    const sharedPreviews = Array.isArray(metadata?.comic_previews) ? metadata.comic_previews : [];
    const comicPreview = rawUrl => {
      const cleanUrl = cleanChatUrl(rawUrl);
      let parsed;
      try { parsed = new URL(cleanUrl, window.location.href); } catch { return null; }
      if (parsed.origin !== window.location.origin) return null;
      const itemId = parsed.searchParams.get("ler");
      const item = itemId ? state.db.library.find(entry => String(entry.id) === String(itemId) && entry.type === "comic") : null;
      if (!item) return null;
      const sharedPreview = sharedPreviews.find(preview => preview?.url === cleanUrl || String(preview?.item_id) === String(item.id));
      const senderChoice = senderVisual?.coverChoices?.get(item.id);
      const sharedCoverUrl = senderChoice?.cover_url || sharedPreview?.cover_url || parsed.searchParams.get("capa_url");
      const sharedVariantKey = senderChoice?.variant_key || sharedPreview?.variant_key || parsed.searchParams.get("capa");
      const sharedVariant = usableCoverVariants(item).find(variant => variant.variant_key === sharedVariantKey);
      const sharedCover = /^https?:\/\//i.test(sharedCoverUrl || "") ? sharedCoverUrl : sharedVariant?.cover_url;
      const hasSharedAppearance = parsed.searchParams.has("capa") || parsed.searchParams.has("capa_url") || parsed.searchParams.has("efeito");
      const defaultCover = item.coverUrl || item.cover || instantCover(item);
      const previewCover = sharedCover ? proxiedImageUrl(sharedCover) : hasSharedAppearance ? proxiedImageUrl(defaultCover) : coverFor(item);
      const senderStyle = senderVisual?.coverStyles?.get(item.id) || (item.seriesId && senderVisual?.coverStyles?.get(item.seriesId));
      const requestedStyle = sharedPreview?.cover_style || senderStyle || parsed.searchParams.get("efeito");
      // No chat, nunca consultar o estado visual de quem recebe.
      const coverStyle = ["normal", "grayscale", "gold"].includes(requestedStyle) ? requestedStyle : "normal";
      const title = itemDisplayTitle(item) || item.title || "Quadrinho";
      const year = item.year ? ` · ${item.year}` : "";
      return `<a class="chat-comic-preview" href="${escapeHTML(cleanUrl)}" target="_blank" rel="noopener"><div class="chat-comic-preview-cover" data-cover-style="${escapeHTML(coverStyle)}" style="background-image:url('${escapeHTML(previewCover)}')"></div><span class="chat-comic-preview-copy"><b>${escapeHTML(title)}</b><small>${escapeHTML(year.replace(/^ · /, ""))}</small></span></a>`;
    };
    const source = String(body || "");
    const urlPattern = /!?\[([^\]\r\n]+)\]\(((?:https?:\/\/|\/)[^\s)]+)\)|(https?:\/\/[^\s<\])]+)/gi;
    let output = "";
    let cursor = 0;
    for (const match of source.matchAll(urlPattern)) {
      output += mentionMarkup(source.slice(cursor, match.index));
      const rawUrl = match[2] || match[3] || match[0];
      const markdownLabel = match[2] ? match[1] : null;
      let top10Preview = null;
      try {
        const parsed = new URL(cleanChatUrl(rawUrl), window.location.href);
        if (parsed.searchParams.has("lista_top10") && parsed.searchParams.has("perfil")) top10Preview = `<div class="chat-top10-preview" data-chat-top10-preview="${escapeHTML(cleanChatUrl(rawUrl))}"><span>Carregando lista...</span></div>`;
      } catch {}
      output += top10Preview || comicPreview(rawUrl) || internalPreview(rawUrl) || chatUrlMarkup(rawUrl, markdownLabel);
      cursor = match.index + match[0].length;
    }
    return output + mentionMarkup(source.slice(cursor));
  }

  function chatMessageMarkup(message, profile = {}, senderVisual = null, options = {}) {
    const username = cleanUsername(profile.username || "usuário");
    const isGuria = username.toLowerCase() === "guria";
    const title = isGuria ? "" : String(profile.title || "").trim();
    const reply = message.metadata?.reply_to;
    const replyMarkup = reply?.body ? `<div class="chat-message-reply"><b>Respondendo a @${escapeHTML(cleanUsername(reply.username || "usuario"))}</b><span>${escapeHTML(String(reply.body).slice(0, 180))}</span></div>` : "";
    const canModerateChat = options.canModerate ?? ["moderator", "banca", "admin"].includes(state.profile?.plan);
    const isSheriff = (options.sheriffId && String(options.sheriffId) === String(message.sender_id)) || options.sheriffIds?.has(String(message.sender_id));
    const messageAvatar = isSheriff ? sheriffAvatarMarkup({ ...profile, username }, "chat-message-avatar") : avatarMarkup({ ...profile, username }, "chat-message-avatar");
    const moderationButton = canModerateChat ? `<button type="button" class="chat-delete-action" data-chat-delete="${escapeHTML(message.id || "")}" aria-label="Excluir mensagem" title="Excluir mensagem"><span class="chat-delete-glyph">×</span></button>` : "";
    const expandButton = `<button type="button" class="chat-expand-message-action" data-chat-message-expand aria-expanded="false" hidden>Expandir</button>`;
    const replyButton = `<button type="button" class="chat-reply-action" data-chat-reply="${escapeHTML(message.id || "")}" aria-label="Responder esta mensagem" title="Responder">↩</button>`;
    const pinButton = canModerateChat && options.allowPin ? `<button type="button" class="chat-pin-action" data-chat-pin="${escapeHTML(message.id || "")}" aria-label="Fixar mensagem" title="Fixar mensagem">📌</button>` : "";
    return `<div class="chat-message ${message.sender_id === state.session.user.id ? "is-mine" : ""}${canModerateChat ? " has-chat-moderation" : ""}" data-chat-message-id="${escapeHTML(message.id || "")}">${moderationButton}<a class="chat-message-author" href="${escapeHTML(publicProfileHref(username))}" target="_blank" rel="noopener">${messageAvatar}<span><b>${factionDot(profile)}@${escapeHTML(username)} ${officialAiBadge(profile)}</b>${title ? `<em style="--title-bg:${safeTitleColor(profile.title_color)}">${escapeHTML(title)}</em>` : ""}</span></a>${staffTitleMarkup(profile)}${replyMarkup}<div class="chat-message-body">${chatBodyMarkup(message.body, message.metadata, senderVisual)}</div><div class="chat-message-footer"><small>${escapeHTML(formatCommentDate(message.created_at))}</small><div class="chat-message-actions">${expandButton}${pinButton}${replyButton}</div></div></div>`;
  }

  function updateChatMessageExpansionUI(messagesRoot) {
    if (!messagesRoot) return;
    $$('[data-chat-message-id]', messagesRoot).forEach(message => {
      const body = $(".chat-message-body", message);
      const button = $("[data-chat-message-expand]", message);
      if (!body || !button) return;
      body.classList.remove("is-expanded");
      body.classList.add("is-line-limited");
      button.hidden = true;
      button.textContent = "Expandir";
      button.setAttribute("aria-expanded", "false");
      requestAnimationFrame(() => {
        body.classList.remove("is-line-limited");
        const lineTops = new Set();
        const walker = document.createTreeWalker(body, NodeFilter.SHOW_TEXT, {
          acceptNode: node => node.textContent.trim() ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT
        });
        let node;
        while ((node = walker.nextNode())) {
          const range = document.createRange();
          range.selectNodeContents(node);
          [...range.getClientRects()].forEach(rect => lineTops.add(Math.round(rect.top)));
        }
        const canExpand = lineTops.size > 9;
        body.classList.add("is-line-limited");
        button.hidden = !canExpand;
        button.textContent = "Expandir";
        button.setAttribute("aria-expanded", "false");
      });
    });
  }

  function setupChatMessageExpansionUI(messagesRoot) {
    if (!messagesRoot || messagesRoot.dataset.messageExpansionBound) return;
    messagesRoot.dataset.messageExpansionBound = "true";
    messagesRoot.addEventListener("click", event => {
      const button = event.target.closest?.("[data-chat-message-expand]");
      if (!button) return;
      const body = $(".chat-message-body", button.closest(".chat-message"));
      if (!body) return;
      const expanded = body.classList.toggle("is-expanded");
      body.classList.toggle("is-line-limited", !expanded);
      button.textContent = expanded ? "Recolher" : "Expandir";
      button.setAttribute("aria-expanded", expanded ? "true" : "false");
    });
    updateChatMessageExpansionUI(messagesRoot);
  }

  function setupChatReplyUI({ messagesRoot, compose, input, getMessage }) {
    if (!messagesRoot || !compose || !input) {
      const noReply = () => null;
      noReply.clear = () => {};
      return noReply;
    }
    let selectedMessage = null;
    let preview = $(".chat-reply-preview", compose);
    if (!preview) {
      preview = document.createElement("div");
      preview.className = "chat-reply-preview";
      preview.hidden = true;
      preview.innerHTML = `<span></span><button type="button" aria-label="Cancelar resposta">×</button>`;
      compose.insertBefore(preview, compose.firstChild);
    }
    const update = () => {
      preview.hidden = !selectedMessage;
      if (selectedMessage) {
        $("span", preview).innerHTML = `<b>Respondendo a @${escapeHTML(cleanUsername(selectedMessage.profile?.username || "usuario"))}</b> ${escapeHTML(String(selectedMessage.body || "").slice(0, 160))}`;
        input.focus();
      }
    };
    const choose = id => { const message = getMessage(id); if (message) { selectedMessage = message; update(); } };
    $("button", preview).onclick = () => { selectedMessage = null; update(); input.focus(); };
    messagesRoot.addEventListener("click", event => { const button = event.target.closest("[data-chat-reply]"); if (button) choose(button.dataset.chatReply); });
    messagesRoot.addEventListener("error", event => {
      const image = event.target.closest?.("[data-chat-image-link] img");
      if (!image) return;
      image.hidden = true;
      image.parentElement.classList.add("is-broken");
    }, true);
    const getReply = () => selectedMessage ? { id: selectedMessage.id, body: selectedMessage.body, username: selectedMessage.profile?.username || "usuario" } : null;
    getReply.clear = () => { selectedMessage = null; update(); };
    return getReply;
  }

  function removeLegacyChatScrollControls(root = document) {
    $$(".chat-scroll-controls, .chat-scroll-control, .chat-scroll-edge, [data-chat-scroll-controls], [data-chat-scroll-first], [data-chat-scroll-latest]", root).forEach(element => element.remove());
  }

  function setupChatModerationUI({ messagesRoot, getMessage, renderMessages, roomId = null, pinsRoot = null, canModerate = null }) {
    const canModerateChat = canModerate ?? ["moderator", "banca", "admin"].includes(state.profile?.plan);
    if (!messagesRoot || !canModerateChat) return;
    messagesRoot.addEventListener("click", async event => {
      const reportButton = event.target.closest?.("[data-chat-report]");
      if (reportButton) {
        event.preventDefault(); event.stopPropagation();
        const message = getMessage(reportButton.dataset.chatReport);
        const reason = message && await askChatReportReason();
        if (!message || !reason) return;
        reportButton.disabled = true;
        const result = await sb.from("chat_message_reports").insert({ message_id: message.id, room_id: roomId, reporter_id: state.session.user.id, target_id: message.sender_id, message_body: String(message.body || "").slice(0, 2000), reason });
        reportButton.disabled = false;
        if (result.error) return toast(/duplicate|unique/i.test(result.error.message || "") ? "Você já denunciou esta mensagem." : (result.error.message || "Não foi possível denunciar a mensagem."));
        toast("Denúncia enviada aos moderadores.");
        return;
      }
      const userButton = event.target.closest?.("[data-chat-user-moderate]");
      if (userButton && roomId) {
        event.preventDefault(); event.stopPropagation();
        const action = await askChatModerationAction(userButton.dataset.chatUsername);
        if (!action || !["mute", "unmute", "clear_recent"].includes(action)) return toast("Ação inválida.");
        const duration = action === "mute" ? (await askChatMuteDuration() || "1h") : "1h";
        const audit = ["mute", "clear_recent"].includes(action) ? await askModerationReason(action === "mute" ? "silence" : "delete_message") : { reason: null, internalNote: null };
        if (!audit) return;
        userButton.disabled = true;
        const result = await sb.rpc("moderate_chat_user", { p_room_id: roomId, p_username: userButton.dataset.chatUsername, p_action: action, p_duration: duration, p_reason: audit.reason || "", p_internal_note: audit.internalNote || "" });
        userButton.disabled = false;
        if (result.error) return toast(result.error.message || "Não foi possível aplicar a moderação.");
        toast(action === "mute" ? "Usuário silenciado nesta sala." : action === "unmute" ? "Silenciamento removido." : "Mensagens recentes removidas.");
        await renderMessages();
        return;
      }
      const pinButton = event.target.closest?.("[data-chat-pin]");
      if (pinButton && roomId) {
        event.preventDefault();
        event.stopPropagation();
        pinButton.disabled = true;
        const duration = await askChatPinDuration();
        if (duration) {
          const result = await sb.rpc("pin_chat_message", { p_room_id: roomId, p_message_id: Number(pinButton.dataset.chatPin), p_duration: duration });
          if (result.error) toast(result.error.message || "Não foi possível fixar a mensagem.");
          else await renderChatPins(pinsRoot, roomId, canModerateChat);
        }
        pinButton.disabled = false;
        return;
      }
      const button = event.target.closest?.("[data-chat-delete]");
      if (!button) return;
      event.preventDefault();
      event.stopPropagation();
      const message = getMessage(button.dataset.chatDelete);
      if (!message) return;
      button.disabled = true;
      const confirmed = await askChatDeleteConfirmation();
      if (!confirmed) {
        button.disabled = false;
        return;
      }
      const moderatedDelete = chatCanModerate && message.sender_id !== state.session?.user?.id;
      const audit = moderatedDelete ? await askModerationReason("delete_message") : { reason: null, internalNote: null };
      if (!audit) {
        button.disabled = false;
        return;
      }
      const result = moderatedDelete
        ? await sb.rpc("delete_moderated_chat_message", { p_message_id: message.id, p_reason: audit.reason, p_internal_note: audit.internalNote })
        : await sb.from("chat_messages").delete().eq("id", message.id);
      if (result.error) {
        button.disabled = false;
        return toast(result.error.message || "Não foi possível excluir a mensagem.");
      }
      await renderMessages();
    });
    if (pinsRoot && roomId) pinsRoot.addEventListener("click", async event => {
      const expandButton = event.target.closest?.("[data-chat-pin-expand]");
      if (expandButton) {
        const slide = expandButton.closest("[data-chat-pin-slide]");
        const expanded = slide?.classList.toggle("is-expanded");
        if (expanded) pinsRoot._chatPinPause?.();
        expandButton.textContent = expanded ? "Recolher" : "Expandir";
        expandButton.setAttribute("aria-expanded", expanded ? "true" : "false");
        return;
      }
      const button = event.target.closest?.("[data-chat-unpin]");
      if (!button) return;
      event.preventDefault();
      event.stopPropagation();
      button.disabled = true;
      const result = await sb.rpc("unpin_chat_message", { p_room_id: roomId, p_message_id: Number(button.dataset.chatUnpin) });
      if (result.error) {
        button.disabled = false;
        return toast(result.error.message || "Não foi possível desfixar a mensagem.");
      }
      await renderChatPins(pinsRoot, roomId, canModerateChat);
    });
  }

  function askChatDeleteConfirmation() {
    return new Promise(resolve => {
      const overlay = document.createElement("div");
      overlay.className = "modal-backdrop";
      overlay.innerHTML = `<div class="modal chat-delete-confirm-modal"><div class="section-head"><div><div class="eyebrow">Moderação</div><h2>Excluir mensagem?</h2><div class="section-subtitle">Esta mensagem será removida do chat e essa ação não pode ser desfeita.</div></div></div><div class="modal-actions"><button type="button" class="small-btn" data-chat-delete-cancel>Cancelar</button><button type="button" class="btn btn-danger" data-chat-delete-confirm>Excluir mensagem</button></div></div>`;
      $("#modal-root").appendChild(overlay);
      const finish = value => { overlay.remove(); resolve(value); };
      $("[data-chat-delete-cancel]", overlay).onclick = () => finish(false);
      $("[data-chat-delete-confirm]", overlay).onclick = () => finish(true);
      overlay.addEventListener("click", event => { if (event.target === overlay) finish(false); });
    });
  }

