  function chatPinDurationLabel(pin) {
    if (!pin.expires_at) return "Até ser desfixada";
    const remaining = new Date(pin.expires_at).getTime() - Date.now();
    if (remaining <= 24 * 60 * 60 * 1000) return "Expira em até 24 horas";
    if (remaining <= 7 * 24 * 60 * 60 * 1000) return "Expira em até 7 dias";
    return "Expira em até 1 mês";
  }

  function chatPinsMarkup(pins, canModerate = null) {
    const canModerateChat = canModerate ?? ["moderator", "banca", "admin"].includes(state.profile?.plan);
    return `<div class="chat-pins-inner">${pins.map((pin, index) => `<article class="chat-pin-slide${index === 0 ? " is-active" : ""}" data-chat-pin-slide="${index}"><div class="chat-pin-heading"><span>📌 Mensagem fixada</span><small>${escapeHTML(chatPinDurationLabel(pin))}</small><div class="chat-pin-carousel-actions"><button type="button" class="chat-pin-carousel-button" data-chat-pin-prev aria-label="Mensagem fixada anterior" title="Anterior">‹</button><button type="button" class="chat-pin-carousel-button" data-chat-pin-toggle aria-label="Pausar carrossel" title="Pausar carrossel">⏸</button><button type="button" class="chat-pin-carousel-button" data-chat-pin-next aria-label="Próxima mensagem fixada" title="Próxima">›</button></div></div><div class="chat-pin-body"><div class="chat-pin-copy">${chatBodyMarkup(pin.body, pin.metadata)}</div></div><div class="chat-pin-footer"><span>— @${escapeHTML(cleanUsername(pin.sender_username || "usuario"))}</span><div class="chat-pin-actions"><button type="button" class="small-btn chat-expand-action" data-chat-pin-expand aria-expanded="false" hidden>Expandir</button>${canModerateChat ? `<button type="button" class="small-btn chat-unpin-action" data-chat-unpin="${escapeHTML(String(pin.message_id))}">Desfixar</button>` : ""}</div></div></article>`).join("")}<div class="chat-pin-dots" role="tablist" aria-label="Mensagens fixadas">${pins.map((pin, index) => `<button type="button" class="chat-pin-dot${index === 0 ? " is-active" : ""}" data-chat-pin-index="${index}" role="tab" aria-label="Mensagem fixada ${index + 1}" aria-selected="${index === 0 ? "true" : "false"}"></button>`).join("")}</div></div>`;
  }

  function updateChatPinExpansionUI(root) {
    $$('[data-chat-pin-slide]', root).forEach(slide => {
      const copy = $(".chat-pin-copy", slide);
      const button = $("[data-chat-pin-expand]", slide);
      if (!copy || !button) return;
      const previousSlideDisplay = slide.style.display;
      const previousCopyDisplay = copy.style.display;
      slide.style.display = "block";
      copy.style.display = "block";
      try {
        const lineTops = new Set();
        const walker = document.createTreeWalker(copy, NodeFilter.SHOW_TEXT, { acceptNode: node => node.textContent.trim() ? NodeFilter.FILTER_ACCEPT : NodeFilter.FILTER_REJECT });
        let node;
        while ((node = walker.nextNode())) {
          const range = document.createRange();
          range.selectNodeContents(node);
          [...range.getClientRects()].forEach(rect => lineTops.add(Math.round(rect.top)));
        }
        button.hidden = lineTops.size <= 2;
      } finally {
        slide.style.display = previousSlideDisplay;
        copy.style.display = previousCopyDisplay;
      }
    });
  }

  function setupChatPinsCarousel(root) {
    root._chatPinCleanup?.();
    const slides = [...root.querySelectorAll("[data-chat-pin-slide]")];
    const dots = [...root.querySelectorAll("[data-chat-pin-index]")];
    const previous = $$('[data-chat-pin-prev]', root);
    const next = $$('[data-chat-pin-next]', root);
    const toggles = $$('[data-chat-pin-toggle]', root);
    if (slides.length < 2) {
      $(".chat-pin-carousel-actions", root)?.setAttribute("hidden", "true");
      return;
    }
    let current = 0;
    let paused = false;
    const show = index => {
      current = (index + slides.length) % slides.length;
      slides.forEach((slide, itemIndex) => {
        slide.classList.toggle("is-active", itemIndex === current);
        slide.classList.remove("is-expanded");
        const expandButton = $("[data-chat-pin-expand]", slide);
        if (expandButton) {
          expandButton.textContent = "Expandir";
          expandButton.setAttribute("aria-expanded", "false");
        }
      });
      updateChatPinExpansionUI(root);
      dots.forEach((dot, itemIndex) => { dot.classList.toggle("is-active", itemIndex === current); dot.setAttribute("aria-selected", itemIndex === current ? "true" : "false"); });
    };
    dots.forEach(dot => dot.onclick = () => show(Number(dot.dataset.chatPinIndex)));
    previous.forEach(button => button.onclick = () => show(current - 1));
    next.forEach(button => button.onclick = () => show(current + 1));
    const updatePauseButton = () => {
      toggles.forEach(toggle => {
        toggle.textContent = paused ? "▶" : "⏸";
        toggle.setAttribute("aria-label", paused ? "Retomar carrossel" : "Pausar carrossel");
        toggle.title = paused ? "Retomar carrossel" : "Pausar carrossel";
      });
    };
    toggles.forEach(toggle => toggle.onclick = () => { paused = !paused; updatePauseButton(); });
    root._chatPinPause = () => { paused = true; updatePauseButton(); };
    const timer = window.setInterval(() => { if (!paused) show(current + 1); }, 10000);
    root._chatPinCleanup = () => { window.clearInterval(timer); root._chatPinPause = null; };
  }

  async function renderChatPins(root, roomId, canModerate = null) {
    if (!root || !roomId || !sb) return;
    const result = await sb.from("chat_pins").select("id, message_id, body, metadata, sender_username, expires_at, pinned_at").eq("room_id", roomId).or(`expires_at.is.null,expires_at.gt.${new Date().toISOString()}`).order("pinned_at", { ascending: true });
    if (result.error) return;
    const pins = result.data || [];
    root.hidden = !pins.length;
    root.innerHTML = pins.length ? chatPinsMarkup(pins, canModerate) : "";
    setupChatPinsCarousel(root);
    updateChatPinExpansionUI(root);
  }

  async function openChatSheriffManager(room) {
    if (!isSheriffRoom(room) || !["moderator", "banca", "admin"].includes(state.profile?.plan)) return;
    const currentResult = await sb.rpc("get_chat_room_sheriff", { p_room_id: room.id });
    const current = currentResult.data?.[0] || null;
    const overlay = document.createElement("div");
    overlay.className = "modal-backdrop";
    overlay.innerHTML = `<div class="modal chat-sheriff-modal"><div class="section-head"><div><div class="eyebrow">Moderação da sala</div><h2>Xerife · ${escapeHTML(room.name)}</h2><div class="section-subtitle">O xerife pode fixar e excluir mensagens desta sala pública.</div></div><button type="button" class="small-btn" data-close>Fechar</button></div><div class="notice">${current ? `Xerife atual: <b>@${escapeHTML(current.username)}</b>` : "Nenhum xerife definido."}</div><form data-sheriff-form><label class="field"><span>Usuário do novo xerife</span><input name="username" required placeholder="Nome de usuário" value="${escapeHTML(current?.username || "")}"></label><div class="modal-actions"><button type="button" class="small-btn" data-clear-sheriff>Remover xerife</button><button type="submit" class="btn btn-danger">Salvar xerife</button></div></form></div>`;
    $("#modal-root").appendChild(overlay);
    const close = () => overlay.remove();
    $("[data-close]", overlay).onclick = close;
    overlay.addEventListener("click", event => { if (event.target === overlay) close(); });
    $("[data-clear-sheriff]", overlay).onclick = async () => {
      const result = await sb.rpc("set_chat_room_sheriff", { p_room_id: room.id, p_username: "" });
      if (result.error) return toast(result.error.message || "Não foi possível remover o xerife.");
      close();
      toast("Xerife removido da sala.");
    };
    $("[data-sheriff-form]", overlay).onsubmit = async event => {
      event.preventDefault();
      const username = String(new FormData(event.currentTarget).get("username") || "").trim();
      if (!username) return;
      const result = await sb.rpc("set_chat_room_sheriff", { p_room_id: room.id, p_username: username });
      if (result.error) return toast(result.error.message || "Não foi possível definir o xerife.");
      close();
      toast(`@${result.data?.[0]?.username || username} agora é o xerife da sala.`);
    };
    $("[name=username]", overlay).focus();
  }

  async function openChatRoom(room) {
    const sheriffResult = isSheriffRoom(room) && sb ? await sb.rpc("get_chat_room_sheriff", { p_room_id: room.id }) : { data: [] };
    const sheriff = sheriffResult.data?.[0] || null;
    const chatCanModerate = ["moderator", "banca", "admin"].includes(state.profile?.plan) || (isSheriffRoom(room) && sheriff?.user_id === state.session?.user?.id) || isFactionChatSheriff(room, state.session?.user?.id);
    const factionSheriffIds = factionChatSheriffIds(room);
    removeLegacyChatScrollControls();
    await markChatMentionsRead(room?.id);
    await loadNotifications();
    if (!state.session || !sb || !room || !canOpenChatRoom(room)) return toast("Você não tem acesso a esta sala.");
    $$('.chat-modal').forEach(modal => modal.closest('.modal-backdrop')?.remove());
    const overlay = document.createElement("div");
    overlay.className = "modal-backdrop";
    overlay.innerHTML = `<div class="modal chat-modal chat-conversation-modal"><div class="section-head"><div><h2>${escapeHTML(room.name)}</h2><div class="section-subtitle">Sala ${chatRoomLabel(room).toLowerCase()} · mensagens expiram em 24 horas</div></div><div class="chat-modal-actions"><button class="small-btn" type="button" data-chat-back>Voltar</button><button class="small-btn" type="button" data-close>Fechar</button></div></div><div class="chat-pins" data-chat-pins hidden></div><div class="chat-messages" data-chat-messages><div class="empty">Carregando mensagens...</div></div><form class="chat-compose" id="chat-room-compose"><textarea name="body" maxlength="2000" rows="2" required placeholder="Escreva uma mensagem"></textarea><button type="submit" class="btn btn-danger">Enviar</button></form></div>`;
    $("#modal-root").appendChild(overlay);
    if (chatCanModerate) {
      const toolsButton = document.createElement("button");
      toolsButton.className = "small-btn"; toolsButton.type = "button"; toolsButton.textContent = "⚙ Moderação";
      toolsButton.onclick = async () => {
        const current = await sb.from("chat_room_settings").select("slow_mode_seconds").eq("room_id", room.id).maybeSingle();
        const value = await askChatSlowMode(current.data?.slow_mode_seconds || 0);
        if (value !== null) {
          const result = await sb.rpc("set_chat_room_slow_mode", { p_room_id: room.id, p_seconds: Math.max(0, Math.min(300, Number(value) || 0)) });
          if (result.error) toast(result.error.message || "Não foi possível atualizar o slow mode."); else toast("Slow mode atualizado.");
        }
        const history = await sb.rpc("get_chat_moderation_history", { p_room_id: room.id, p_limit: 20 });
        if (!history.error && history.data?.length) {
          const summary = history.data.map(item => `${new Date(item.created_at).toLocaleString("pt-BR")} · ${item.action}${item.duration_until ? ` até ${new Date(item.duration_until).toLocaleString("pt-BR")}` : ""}`).join("\n");
          window.alert(`Histórico de moderação\n\n${summary}`);
        }
      };
      $(".chat-modal-actions", overlay)?.prepend(toolsButton);
    }
    if (isSheriffRoom(room) && ["moderator", "banca", "admin"].includes(state.profile?.plan)) {
      const sheriffButton = document.createElement("button");
      sheriffButton.className = "small-btn";
      sheriffButton.type = "button";
      sheriffButton.textContent = "🤠 Xerife";
      sheriffButton.title = sheriff ? `Xerife atual: @${sheriff.username}` : "Definir xerife";
      sheriffButton.onclick = () => openChatSheriffManager(room);
      $(".chat-modal-actions", overlay)?.prepend(sheriffButton);
    }
    if (room.factionId && ["moderator", "banca", "admin"].includes(state.profile?.plan)) $("#chat-room-compose", overlay)?.remove();
    const pinsRoot = $("[data-chat-pins]", overlay);
    let closed = false;
    let channel = null;
    const close = event => {
      event?.preventDefault();
      event?.stopPropagation();
      if (closed) return;
      closed = true;
      channel?.unsubscribe();
      pinsRoot?._chatPinCleanup?.();
      overlay.remove();
    };
    $("[data-close]", overlay).onclick = close;
    $("[data-chat-back]", overlay).onclick = event => { close(event); openChat(); };
    overlay.addEventListener("click", event => {
      if (event.target === overlay) close(event);
    });
    const messagesRoot = $("[data-chat-messages]", overlay);
    const chatInput = $("#chat-room-compose textarea", overlay);
    let chatMessagesById = new Map();
    const resizeChatInput = () => {
      if (!chatInput) return;
      chatInput.style.height = "auto";
      chatInput.style.height = `${chatInput.scrollHeight}px`;
    };
    const renderMessages = async () => {
      const result = await sb.from("chat_messages").select("id, sender_id, body, metadata, created_at, profiles!chat_messages_sender_id_fkey(id, username, avatar_url, title, title_color, plan, faction_id)").eq("room_id", room.id).gt("expires_at", new Date().toISOString()).order("created_at", { ascending: true }).limit(200);
      if (result.error) return messagesRoot.innerHTML = '<div class="empty">Não foi possível carregar as mensagens.</div>';
      const senderVisuals = await loadChatSenderVisuals((result.data || []).map(message => message.sender_id));
      chatMessagesById = new Map((result.data || []).map(message => [String(message.id), { ...message, profile: message.profiles || {} }]));
      messagesRoot.innerHTML = (result.data || []).map(message => chatMessageMarkup(message, message.profiles || {}, senderVisuals.get(message.sender_id), { allowPin: true, canModerate: chatCanModerate, sheriffId: sheriff?.user_id, sheriffIds: factionSheriffIds })).join("") || '<div class="empty">Nenhuma mensagem ainda.</div>';
      hydrateChatTop10Previews(messagesRoot);
      $$('[data-chat-message-id]', messagesRoot).forEach(node => {
        const message = chatMessagesById.get(String(node.dataset.chatMessageId));
        if (!message) return;
        const actions = $(".chat-message-actions", node);
        if (message.sender_id !== state.session?.user?.id) {
          const report = document.createElement("button");
          report.type = "button"; report.className = "chat-report-action"; report.dataset.chatReport = String(message.id); report.textContent = "⚑"; report.title = "Denunciar mensagem";
          actions?.prepend(report);
        }
        if (chatCanModerate && actions) {
          const moderate = document.createElement("button");
          moderate.type = "button"; moderate.className = "chat-report-action"; moderate.dataset.chatUserModerate = String(message.id); moderate.dataset.chatUsername = cleanUsername(message.profiles?.username || "usuario"); moderate.textContent = "⚙"; moderate.title = "Moderar usuário";
          actions.prepend(moderate);
        }
      });
      hydrateChatFactionRoleTitles(messagesRoot);
      updateChatMessageExpansionUI(messagesRoot);
      messagesRoot.scrollTop = messagesRoot.scrollHeight;
      await renderChatPins(pinsRoot, room.id, chatCanModerate);
    };
    await renderMessages();
    channel = sb.channel(`chat-room-${room.id}-${state.session.user.id}`).on("postgres_changes", { event: "INSERT", schema: "public", table: "chat_messages", filter: `room_id=eq.${room.id}` }, payload => { if (payload.new?.room_id === room.id) renderMessages(); }).on("postgres_changes", { event: "*", schema: "public", table: "chat_pins", filter: `room_id=eq.${room.id}` }, payload => { if (payload.new?.room_id === room.id || payload.old?.room_id === room.id) renderChatPins(pinsRoot, room.id, chatCanModerate); }).subscribe();
    const chatCompose = $("#chat-room-compose", overlay);
    const getReply = setupChatReplyUI({ messagesRoot, compose: chatCompose, input: chatInput, getMessage: id => chatMessagesById.get(String(id)) });
    setupChatMessageExpansionUI(messagesRoot);
    setupChatModerationUI({ messagesRoot, getMessage: id => chatMessagesById.get(String(id)), renderMessages, roomId: room.id, pinsRoot, canModerate: chatCanModerate });
    if (chatCompose) chatCompose.onsubmit = async event => {
      event.preventDefault();
      const composeForm = event.currentTarget;
      const form = new FormData(composeForm);
      const prepared = prepareChatMessage(String(form.get("body") || "").trim());
      const body = prepared.body;
      const reply = getReply();
      const button = $("button[type=submit]", composeForm);
      if (!body || button.disabled) return;
      button.disabled = true;
      const result = await sb.from("chat_messages").insert({ sender_id: state.session.user.id, room_id: room.id, recipient_id: null, body, metadata: { ...prepared.metadata, ...(reply ? { reply_to: reply } : {}) }, expires_at: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString() });
      if (result.error) { console.error("[chat room] erro ao enviar mensagem", result.error); toast(result.error.message || "Não foi possível enviar a mensagem."); }
      else { awardProfileXp("chat", `chat:${Date.now()}`); composeForm.reset(); getReply.clear(); await renderMessages(); }
      button.disabled = false;
    };
    chatInput?.addEventListener("keydown", event => {
      if (event.key !== "Enter" || event.shiftKey || event.isComposing) return;
      event.preventDefault();
      chatCompose?.requestSubmit();
    });
  }

  async function openChat(contact = null) {
    removeLegacyChatScrollControls();
    $$('.notifications-popup-modal').forEach(modal => modal.closest('.modal-backdrop')?.remove());
    $$('.chat-modal').forEach(modal => modal.closest('.modal-backdrop')?.remove());
    if (!state.session || !sb) return openAuthPage();
    if (contact?.id === state.session.user.id) return toast("Você não pode enviar mensagens para si mesmo.");
    if (contact?.id && contact.allow_messages === false) return toast("Este usuário não está recebendo mensagens privadas.");
    if (contact?.id && (contact.allow_messages === undefined || contact.is_bot === undefined || contact.is_official === undefined)) {
      const recipient = await sb.from("profiles").select("allow_messages, is_bot, is_official, bot_type").eq("id", contact.id).maybeSingle();
      if (recipient.data) contact = { ...contact, ...recipient.data };
      if (recipient.data?.allow_messages === false) return toast("Este usuário não está recebendo mensagens privadas.");
    }
    state.chatContact = contact?.id ? contact : null;
    if (contact?.id) {
      state.notifications = state.notifications.filter(notification => !isNotificationFromOpenChat(notification));
      state.notificationUnreadCount = state.notifications.filter(notification => !notification.read_at).length;
    }
    if (contact?.id) await markChatNotificationsRead(contact.id);
    await loadNotifications();
    render();
    const overlay = document.createElement("div");
    overlay.className = "modal-backdrop";
    overlay.innerHTML = `<div class="modal chat-modal${contact ? " chat-conversation-modal" : ""}"><div class="section-head"><div><h2>Mensagens</h2><div class="section-subtitle">As mensagens desaparecem após 24 horas.</div></div><div class="chat-modal-actions">${contact ? `<button class="small-btn" type="button" data-chat-back>Voltar</button>` : ""}<button class="small-btn" data-close>Fechar</button></div></div><div class="chat-contact-picker">${contact ? `<div class="chat-contact-selected">Conversando com <b>@${escapeHTML(contact.username)} ${officialAiBadge(contact)}</b>${contact.is_bot ? '<small>Mensagens para a IA podem passar por moderação automatizada.</small>' : ''}</div>` : `<form id="chat-contact-form"><input name="username" required placeholder="Nome de usuário"><button type="submit" class="small-btn">Abrir conversa</button></form>`}</div>${contact ? `<div class="chat-messages" data-chat-messages><div class="empty">Carregando mensagens...</div></div><form class="chat-compose" id="chat-compose"><textarea name="body" maxlength="2000" rows="2" required placeholder="Escreva uma mensagem"></textarea><button type="submit" class="btn btn-danger">Enviar</button></form>` : `<div class="notice">Abra o perfil de um usuário e clique em “Enviar mensagem”, ou pesquise o nome de usuário acima.</div><div class="chat-private-list" data-private-chat-list hidden></div>`}</div>`;
    $("#modal-root").appendChild(overlay);
    let channel = null;
    let closed = false;
    const close = event => {
      event?.preventDefault();
      event?.stopPropagation();
      if (closed) return;
      closed = true;
      state.chatContact = null;
      channel?.unsubscribe();
      overlay.remove();
      loadNotifications().then(() => render());
    };
    $("[data-close]", overlay).onclick = close;
    $("[data-chat-back]", overlay)?.addEventListener("click", event => { close(event); openChat(); });
    overlay.addEventListener("click", event => {
      if (event.target === overlay) close(event);
    });
    if (contact) {
      const headerTitle = $(".section-head h2", overlay);
      const selectedContact = $(".chat-contact-selected", overlay);
      if (headerTitle) headerTitle.textContent = `@${contact.username}`;
      if (selectedContact) selectedContact.hidden = true;
    }
    if (!contact) {
      const availableRooms = CHAT_ROOMS.filter(canOpenChatRoom);
      $(".chat-contact-picker", overlay).insertAdjacentHTML("afterbegin", `<div class="chat-room-list"><div class="chat-room-list-title">Salas de conversa</div>${availableRooms.map(room => { const unread = state.chatRoomUnreadCounts?.[room.id] || 0; return `<button type="button" class="chat-room-option" data-chat-room="${escapeHTML(room.id)}"><span>${escapeHTML(room.name)}</span>${unread ? `<span class="message-badge" aria-label="${unread} marcação(ões) não lida(s)">${unread > 99 ? "99+" : unread}</span>` : ""}<small>${chatRoomLabel(room)}</small></button>`; }).join("")}</div>`);
      $$('[data-chat-room]', overlay).forEach(button => button.onclick = () => { overlay.remove(); openChatRoom(CHAT_ROOMS.find(room => room.id === button.dataset.chatRoom)); });
      const privateChatList = $("[data-private-chat-list]", overlay);
      const privateMessages = await sb.from("chat_messages")
        .select("id, sender_id, recipient_id, body, created_at")
        .or(`sender_id.eq.${state.session.user.id},recipient_id.eq.${state.session.user.id}`)
        .gt("expires_at", new Date().toISOString())
        .order("created_at", { ascending: false })
        .limit(500);
      const conversations = new Map();
      (privateMessages.data || []).forEach(message => {
        const incoming = String(message.recipient_id) === String(state.session.user.id);
        const contactId = incoming ? message.sender_id : message.recipient_id;
        if (!contactId) return;
        const conversation = conversations.get(contactId) || { latest: message, hasIncoming: false };
        conversation.hasIncoming ||= incoming;
        if (new Date(message.created_at) > new Date(conversation.latest.created_at)) conversation.latest = message;
        conversations.set(contactId, conversation);
      });
      const contactIds = [...conversations.keys()];
      if (contactIds.length) {
        const profilesResult = await sb.from("profiles").select("id, username, avatar_url, title, title_color, allow_messages, is_bot, is_official, bot_type").in("id", contactIds);
        const profiles = new Map((profilesResult.data || []).map(profile => [profile.id, profile]));
        const cards = contactIds.map(contactId => {
          const profile = profiles.get(contactId);
          const conversation = conversations.get(contactId);
          if (!profile || !conversation) return "";
          return `<button type="button" class="chat-private-card" data-private-chat-user="${escapeHTML(profile.id)}">${avatarMarkup(profile, "chat-private-card-avatar")}<span class="chat-private-card-copy"><b>${factionDot(profile)}@${escapeHTML(profile.username)}</b><small>${escapeHTML(conversation.latest.body.slice(0, 100))}</small></span><time>${escapeHTML(formatCommentDate(conversation.latest.created_at))}</time></button>`;
        }).join("");
        if (cards) {
          privateChatList.hidden = false;
          privateChatList.innerHTML = `<div class="chat-room-list-title">Conversas recentes</div><div class="chat-private-card-list">${cards}</div>`;
          $$('[data-private-chat-user]', privateChatList).forEach(button => button.onclick = () => {
            const contact = profiles.get(button.dataset.privateChatUser);
            if (!contact) return;
            overlay.remove();
            openChat(contact);
          });
        }
      }
      $("#chat-contact-form", overlay).onsubmit = async event => {
        event.preventDefault();
        const username = String(new FormData(event.currentTarget).get("username") || "").trim();
        if (!username) return;
        const result = await sb.from("profiles").select("id, username, avatar_url, title, allow_messages, is_bot, is_official, bot_type").ilike("username", username).maybeSingle();
        if (result.error || !result.data) return toast("Usuário não encontrado.");
        if (result.data.allow_messages === false) return toast("Este usuário não está recebendo mensagens privadas.");
        overlay.remove();
        openChat(result.data);
      };
      return;
    }
    const messagesRoot = $("[data-chat-messages]", overlay);
    let chatMessagesById = new Map();
    const renderMessages = async () => {
      const now = new Date().toISOString();
      const result = await sb.from("chat_messages").select("id, sender_id, body, metadata, created_at").or(`and(sender_id.eq.${state.session.user.id},recipient_id.eq.${contact.id}),and(sender_id.eq.${contact.id},recipient_id.eq.${state.session.user.id})`).gt("expires_at", now).order("created_at", { ascending: true }).limit(200);
      if (result.error) return messagesRoot.innerHTML = '<div class="empty">Não foi possível carregar as mensagens.</div>';
      const senderIds = [...new Set((result.data || []).map(message => message.sender_id).filter(Boolean))];
      const profilesResult = senderIds.length ? await sb.from("profiles").select("id, username, avatar_url, title, title_color, plan, faction_id, is_bot, is_official, bot_type").in("id", senderIds) : { data: [] };
      const profilesById = new Map((profilesResult.data || []).map(profile => [profile.id, profile]));
      const senderVisuals = await loadChatSenderVisuals(senderIds);
      chatMessagesById = new Map((result.data || []).map(message => [String(message.id), { ...message, profile: profilesById.get(message.sender_id) || {} }]));
      messagesRoot.innerHTML = (result.data || []).map(message => chatMessageMarkup(message, profilesById.get(message.sender_id) || (message.sender_id === state.session.user.id ? state.profile : {}), senderVisuals.get(message.sender_id))).join("") || '<div class="empty">Nenhuma mensagem ainda.</div>';
      hydrateChatTop10Previews(messagesRoot);
      hydrateChatFactionRoleTitles(messagesRoot);
      updateChatMessageExpansionUI(messagesRoot);
      messagesRoot.scrollTop = messagesRoot.scrollHeight;
    };
    await renderMessages();
    channel = sb.channel(`chat-${state.session.user.id}-${contact.id}`).on("postgres_changes", { event: "INSERT", schema: "public", table: "chat_messages", filter: `recipient_id=eq.${state.session.user.id}` }, payload => { if (payload.new?.sender_id === contact.id) renderMessages(); }).subscribe();
    const chatCompose = $("#chat-compose", overlay);
    const chatInput = $("#chat-compose textarea", overlay);
    const getReply = setupChatReplyUI({ messagesRoot, compose: chatCompose, input: chatInput, getMessage: id => chatMessagesById.get(String(id)) });
    setupChatMessageExpansionUI(messagesRoot);
    setupChatModerationUI({ messagesRoot, getMessage: id => chatMessagesById.get(String(id)), renderMessages });
    chatCompose.onsubmit = async event => {
      event.preventDefault();
      const composeForm = event.currentTarget;
      const form = new FormData(event.currentTarget);
      const prepared = prepareChatMessage(String(form.get("body") || "").trim());
      const body = prepared.body;
      const reply = getReply();
      if (!body) return;
      const submitButton = $("button[type=submit]", event.currentTarget);
      if (!submitButton || submitButton.disabled) return;
      submitButton.disabled = true;
      const optimisticId = `chat-pending-${Date.now()}`;
      messagesRoot.insertAdjacentHTML("beforeend", `<div class="chat-message is-mine chat-message-pending" data-chat-pending="${optimisticId}"><div>${escapeHTML(body)}</div><small>Enviando…</small></div>`);
      event.currentTarget.reset();
      messagesRoot.scrollTop = messagesRoot.scrollHeight;
      const result = await sb.from("chat_messages").insert({ sender_id: state.session.user.id, recipient_id: contact.id, body, metadata: { ...prepared.metadata, ...(reply ? { reply_to: reply } : {}) }, expires_at: new Date(Date.now() + 24 * 60 * 60 * 1000).toISOString() }).select("id").single();
      if (result.error) {
        $(`[data-chat-pending="${optimisticId}"]`, messagesRoot)?.remove();
        submitButton.disabled = false;
        console.error("[private chat] erro ao enviar mensagem", result.error);
        return toast(result.error.message || "Não foi possível enviar a mensagem.");
      }
      if (contact.is_bot && contact.is_official && result.data?.id) {
        sb.functions.invoke("guria-chat", { body: { message_id: result.data.id } }).catch(error => console.warn("[guria] resposta assíncrona indisponível", error?.message || error));
      }
      await renderMessages();
      getReply.clear();
      awardProfileXp("chat", `chat:${Date.now()}`);
      submitButton.disabled = false;
    };
    $("#chat-compose textarea", overlay)?.addEventListener("keydown", event => {
      if (event.key !== "Enter" || event.shiftKey || event.isComposing) return;
      event.preventDefault();
      $("#chat-compose", overlay)?.requestSubmit();
    });
  }

  async function saveShelfCategories(categories) {
    if (sb && state.session) {
      const rows = categories.map(category => ({ id: category.id, owner_id: state.session.user.id, name: category.name, cover_url: category.coverUrl || null, is_public: category.isPublic !== false, item_ids: category.itemIds || [], sort_order: category.sortOrder || state.collectionSortOrders?.[`category:${category.id}`] || "added_desc", collection_type: "comic", blog_ids: [], is_featured: category.is_featured === true }));
      let result = rows.length ? await sb.from("shelf_collections").upsert(rows, { onConflict: "id" }) : { error: null };
      if (result.error && /sort_order|schema cache|column/i.test(result.error.message || "")) {
        result = rows.length ? await sb.from("shelf_collections").upsert(rows.map(({ sort_order, ...row }) => row), { onConflict: "id" }) : { error: null };
      }
      if (result.error) return toast("Não foi possível salvar a organização da estante.");
      const ids = rows.map(row => row.id);
      const existing = await sb.from("shelf_collections").select("id").eq("owner_id", state.session.user.id).eq("collection_type", "comic");
      const removedIds = (existing.data || []).map(row => row.id).filter(id => !ids.includes(id));
      if (removedIds.length) await sb.from("shelf_collections").delete().eq("owner_id", state.session.user.id).in("id", removedIds);
    }
    render();
    toast("Estante atualizada.");
  }

  async function saveShelfSortOrder(key, order) {
    if (!state.session || !SHELF_SORT_OPTIONS.some(([value]) => value === order)) return;
    const storageKey = key.replace(/^public-/, "");
    state.collectionSortOrders = { ...(state.collectionSortOrders || {}), [storageKey]: order };
    const result = await sb?.from("profiles").update({ shelf_sort_orders: state.collectionSortOrders }).eq("id", state.session.user.id);
    if (storageKey.startsWith("category:")) {
      const collectionId = storageKey.slice("category:".length);
      const category = state.shelfCategories.find(item => item.id === collectionId);
      if (category) category.sortOrder = order;
      await sb?.from("shelf_collections").update({ sort_order: order }).eq("id", collectionId).eq("owner_id", state.session.user.id);
    }
    if (result?.error) {
      try { localStorage.setItem(`bancaDigitalShelfSort:${state.session.user.id}`, JSON.stringify(state.collectionSortOrders)); } catch {}
    }
    render();
  }

  async function saveShelfStyle(key, style) {
    if (!state.session || !shelfStyleOptionsFor(state.profile).some(([value]) => value === style)) return;
    const shelfStyles = { ...(state.profile?.shelf_styles || {}), [key]: style };
    const update = await sb?.from("profiles").update({ shelf_styles: shelfStyles }).eq("id", state.session.user.id);
    if (update?.error) {
      const message = String(update.error.message || "");
      if (/shelf_style|column|schema cache/i.test(message)) return toast("Execute a migraÃ§Ã£o add_shelf_style.sql no Supabase para ativar os estilos.");
      return toast(`NÃ£o foi possÃ­vel salvar: ${message}`);
    }
    state.profile = { ...state.profile, shelf_styles: shelfStyles };
    if (state.publicProfile?.profile?.id === state.session.user.id) state.publicProfile.profile = { ...state.publicProfile.profile, shelf_styles: shelfStyles };
    render();
    toast("Estilo das prateleiras atualizado.");
  }

  async function copyCollectionLink(categoryId, username = state.profile?.username) {
    if (!username || !categoryId) return;
    const link = new URL(publicProfileHref(username, categoryId), window.location.href).href;
    try {
      await navigator.clipboard.writeText(link);
      toast("Link da coleção copiado.");
    } catch {
      await openSitePrompt("Copie o link da coleção:", link, { title: "Compartilhar coleção", label: "Link" });
    }
  }

  function shelfComicPickerMarkup(items, selectedIds = []) {
    const normalize = value => String(value || "").trim().toLocaleLowerCase("pt-BR").normalize("NFD").replace(/[\u0300-\u036f]/g, "");
    const groups = new Map();
    items.forEach(item => {
      const publisher = String(item.publisher || "").trim() || "Sem editora";
      const imprint = String(item.imprint || "").trim() || "Sem selo";
      const series = String(item.seriesTitle || item.title || "").trim() || "Sem série";
      const first = normalize(series).charAt(0).toUpperCase();
      const letter = /^[A-Z]$/.test(first) ? first : "#";
      if (!groups.has(publisher)) groups.set(publisher, new Map());
      if (!groups.get(publisher).has(imprint)) groups.get(publisher).set(imprint, new Map());
      if (!groups.get(publisher).get(imprint).has(letter)) groups.get(publisher).get(imprint).set(letter, new Map());
      if (!groups.get(publisher).get(imprint).get(letter).has(series)) groups.get(publisher).get(imprint).get(letter).set(series, []);
      groups.get(publisher).get(imprint).get(letter).get(series).push(item);
    });
    const sortLabels = (a, b) => String(a).localeCompare(String(b), "pt-BR", { sensitivity: "base" });
    const details = (className, label, content, searchText) => `<details class="collection-picker-group ${className}" data-picker-group data-picker-text="${escapeHTML(normalize(searchText))}" open><summary>${escapeHTML(label)}</summary>${content}</details>`;
    const publishers = [...groups.entries()].sort(([a], [b]) => sortLabels(a, b)).map(([publisher, imprints]) => {
      const imprintMarkup = [...imprints.entries()].sort(([a], [b]) => sortLabels(a, b)).map(([imprint, letters]) => {
        const letterMarkup = [...letters.entries()].sort(([a], [b]) => sortLabels(a, b)).map(([letter, seriesMap]) => {
          const seriesMarkup = [...seriesMap.entries()].sort(([a], [b]) => sortLabels(a, b)).map(([series, seriesItems]) => {
            const issueMarkup = seriesItems.slice().sort((a, b) => issueSortValue(a) - issueSortValue(b) || sortLabels(itemDisplayTitle(a), itemDisplayTitle(b))).map(item => `<label class="collection-picker-item" data-picker-item data-picker-text="${escapeHTML(normalize(`${itemDisplayTitle(item)} ${item.issue || ""} ${item.seriesTitle || ""} ${item.publisher || ""} ${item.imprint || ""}`))}"><input type="checkbox" name="itemIds" value="${escapeHTML(item.id)}" ${selectedIds.map(String).includes(String(item.id)) ? "checked" : ""}> ${escapeHTML(itemDisplayTitle(item))}${item.issue ? ` — ${escapeHTML(item.issue)}` : ""}</label>`).join("");
            return details("collection-picker-series", `${series} (${seriesItems.length})`, `<div class="collection-picker-items">${issueMarkup}</div>`, `${series} ${publisher} ${imprint} ${letter}`);
          }).join("");
          return details("collection-picker-letter", letter, `<div class="collection-picker-nested">${seriesMarkup}</div>`, `${publisher} ${imprint} ${letter}`);
        }).join("");
        return details("collection-picker-imprint", imprint, `<div class="collection-picker-nested">${letterMarkup}</div>`, `${publisher} ${imprint}`);
      }).join("");
      return details("collection-picker-publisher", publisher, `<div class="collection-picker-nested">${imprintMarkup}</div>`, publisher);
    }).join("");
    return `<div class="collection-picker collection-picker-comics"><div class="collection-picker-search"><input type="search" data-collection-picker-search placeholder="Pesquisar quadrinho, série, selo ou editora"><span data-collection-picker-count>${items.length} quadrinho(s)</span></div><div data-collection-picker-tree>${publishers || '<div class="empty">Salve algum quadrinho primeiro.</div>'}</div></div>`;
  }

  function openShelfCategoryForm(categoryId = null) {
    const existing = state.shelfCategories.find(category => category.id === categoryId);
    const savedItems = shelfItemsByIds([...ensureShelfSnapshot().saved]);
    const overlay = document.createElement("div");
    overlay.className = "modal-backdrop";
    overlay.innerHTML = `<div class="modal"><div class="section-head"><div><h2>${existing ? "Editar coleção" : "Nova coleção"}</h2><div class="section-subtitle">Organize seus itens salvos e escolha se a coleção será compartilhável</div></div><button class="small-btn" data-close>Fechar</button></div><form id="shelf-category-form"><div class="form-grid"><div class="field full"><label>Nome da coleção</label><input name="name" required maxlength="60" value="${escapeHTML(existing?.name || "")}" placeholder="Ex.: Favoritos, Para reler"></div><div class="field full"><label>Imagem da coleção (opcional)</label><input name="coverUrl" type="url" value="${escapeHTML(existing?.coverUrl || "")}" placeholder="https://.../imagem.jpg"><small class="format-hint">Apenas para coleções públicas.</small></div><div class="field full"><label><input name="isPublic" type="checkbox" ${existing?.isPublic !== false ? "checked" : ""}> Coleção pública — aparecerá no perfil e poderá ser compartilhada</label></div><div class="field full"><label>Quadrinhos nesta coleção</label><div class="collection-picker">${savedItems.map(item => `<label><input type="checkbox" name="itemIds" value="${escapeHTML(item.id)}" ${existing?.itemIds?.includes(item.id) ? "checked" : ""}> ${escapeHTML(item.seriesTitle || item.title)}${item.issue ? ` — ${escapeHTML(item.issue)}` : ""}</label>`).join("") || "Salve algum quadrinho primeiro."}</div></div></div><div class="modal-actions"><button type="button" class="small-btn" data-close>Cancelar</button><button class="btn btn-danger">Salvar coleção</button></div></form></div>`;
    $("#modal-root").appendChild(overlay);
    const comicPicker = $(".collection-picker", overlay);
    if (comicPicker) {
      comicPicker.outerHTML = shelfComicPickerMarkup(savedItems, existing?.itemIds || []);
      const search = $("[data-collection-picker-search]", overlay);
      const tree = $("[data-collection-picker-tree]", overlay);
      const count = $("[data-collection-picker-count]", overlay);
      const normalizeSearch = value => String(value || "").trim().toLocaleLowerCase("pt-BR").normalize("NFD").replace(/[\u0300-\u036f]/g, "");
      const filterPicker = () => {
        const query = normalizeSearch(search?.value);
        let visibleCount = 0;
        $$('[data-picker-item]', tree).forEach(item => {
          const visible = !query || normalizeSearch(item.dataset.pickerText).includes(query);
          item.hidden = !visible;
          if (visible) visibleCount += 1;
        });
        $$('[data-picker-group]', tree).reverse().forEach(group => {
          const hasVisible = Boolean($('[data-picker-item]:not([hidden])', group));
          group.hidden = !hasVisible;
          if (query && hasVisible) group.open = true;
        });
        if (count) count.textContent = `${visibleCount} quadrinho(s)`;
      };
      search?.addEventListener("input", filterPicker);
      filterPicker();
    }
    $$('[data-close]', overlay).forEach(button => button.onclick = () => overlay.remove());
    overlay.addEventListener("click", event => { if (event.target === overlay) overlay.remove(); });
    $("#shelf-category-form", overlay).onsubmit = async event => {
      event.preventDefault();
      const form = new FormData(event.currentTarget);
      const category = { id: existing?.id || `shelf-${Date.now()}`, name: String(form.get("name") || "").trim(), coverUrl: String(form.get("coverUrl") || "").trim(), isPublic: form.get("isPublic") === "on", itemIds: form.getAll("itemIds"), sortOrder: existing?.sortOrder || state.collectionSortOrders?.[`category:${existing?.id}`] || "added_desc" };
      if (!category.name) return;
      const categories = existing ? state.shelfCategories.map(item => item.id === category.id ? category : item) : [...state.shelfCategories, category];
      state.shelfCategories = categories;
      overlay.remove();
      await saveShelfCategories(categories);
    };
  }

  function deleteShelfCategory(categoryId) {
    state.shelfCategories = state.shelfCategories.filter(category => category.id !== categoryId);
    saveShelfCategories(state.shelfCategories);
  }

  function blogShelfCollectionMarkup(collection, posts, editable = false) {
    const items = (collection.blogIds || []).map(id => posts.find(post => String(post.id) === String(id))).filter(Boolean);
    const staff = ["moderator", "banca", "admin"].includes(state.profile?.plan);
    const profileUsername = state.publicProfile?.profile?.username || state.profile?.username || "";
    return `<section class="section shelf-collection blog-shelf-collection"><div class="section-head"><div><h2 class="section-title">${escapeHTML(collection.name)}</h2><div class="section-subtitle">${items.length} blog(s)</div></div><div class="shelf-section-actions">${collection.isPublic !== false ? `<span class="shelf-visibility is-public">${collection.is_featured ? "Destaque · " : ""}Pública</span><button class="small-btn" data-copy-collection="${escapeHTML(collection.id)}" data-copy-username="${escapeHTML(profileUsername)}">Compartilhar</button>${!editable && profileUsername ? `<a class="small-btn" href="${escapeHTML(publicProfileHref(profileUsername, collection.id))}">Abrir</a>` : ""}` : '<span class="shelf-visibility is-private">Privada</span>'}${staff && collection.isPublic !== false ? `<button class="small-btn" data-collection-feature="${escapeHTML(collection.id)}" data-collection-featured="${collection.is_featured ? "true" : "false"}">${collection.is_featured ? "Remover destaque" : "Destacar"}</button>` : ""}${editable ? `<button class="small-btn" data-blog-shelf-edit="${escapeHTML(collection.id)}">Editar</button><button class="small-btn danger" data-blog-shelf-delete="${escapeHTML(collection.id)}">Excluir</button>` : ""}</div></div><div class="blog-shelf-grid">${items.map(post => blogCard(post)).join("") || '<div class="empty">Nenhum blog nesta coleção.</div>'}</div></section>`;
  }

  function blogShelfPanelMarkup(publicState = null) {
    const authored = publicState ? publicState.authoredBlogPosts || [] : state.authoredBlogPosts;
    const saved = publicState ? [...(publicState.savedBlogPosts || []), ...(publicState.collectionBlogPosts || [])] : state.savedBlogPosts;
    const collections = (publicState ? publicState.blogCollections || [] : state.blogShelfCategories).filter(collection => !publicState || collection.isPublic !== false);
    const posts = [...new Map([...authored, ...saved].map(post => [String(post.id), post])).values()];
    const canEdit = !publicState;
    return `<div class="blog-shelf-panel"><div class="section-head"><div><h2 class="section-title">Blogs</h2><div class="section-subtitle">Blogs escritos e salvos por esta pessoa.</div></div>${canEdit ? '<button class="small-btn" data-blog-shelf-new>+ Nova coleção</button>' : ""}</div><section class="section shelf-collection"><div class="section-head"><div><h2 class="section-title">Escritos</h2><div class="section-subtitle">${authored.length} blog(s)</div></div></div><div class="blog-shelf-grid">${authored.map(post => blogCard(post)).join("") || '<div class="empty">Nenhum blog escrito ainda.</div>'}</div></section><section class="section shelf-collection"><div class="section-head"><div><h2 class="section-title">Salvos</h2><div class="section-subtitle">${saved.length} blog(s)</div></div></div><div class="blog-shelf-grid">${saved.map(post => blogCard(post)).join("") || '<div class="empty">Nenhum blog salvo ainda.</div>'}</div></section>${collections.map(collection => blogShelfCollectionMarkup(collection, posts, canEdit)).join("")}</div>`;
  }

  function openBlogShelfCollectionForm(collectionId = null) {
    const existing = state.blogShelfCategories.find(collection => collection.id === collectionId);
    const posts = [...new Map([...state.authoredBlogPosts, ...state.savedBlogPosts].map(post => [String(post.id), post])).values()];
    const overlay = document.createElement("div");
    overlay.className = "modal-backdrop";
    overlay.innerHTML = `<div class="modal"><div class="section-head"><div><h2>${existing ? "Editar coleção de blogs" : "Nova coleção de blogs"}</h2><div class="section-subtitle">Organize blogs escritos ou salvos.</div></div><button class="small-btn" data-close>Fechar</button></div><form id="blog-shelf-collection-form"><div class="field"><label>Nome da coleção</label><input name="name" maxlength="60" required value="${escapeHTML(existing?.name || "")}" placeholder="Ex.: Notícias favoritas"></div><div class="field"><label>Imagem da coleção (opcional)</label><input name="coverUrl" type="url" value="${escapeHTML(existing?.coverUrl || "")}" placeholder="https://..."></div><div class="field"><label><input name="isPublic" type="checkbox" ${existing?.isPublic !== false ? "checked" : ""}> Coleção pública</label></div><div class="field"><label>Blogs</label><div class="collection-picker">${posts.map(post => `<label><input type="checkbox" name="blogIds" value="${escapeHTML(post.id)}" ${existing?.blogIds?.includes(String(post.id)) ? "checked" : ""}> ${escapeHTML(post.title)}</label>`).join("") || "Salve ou escreva algum blog primeiro."}</div></div><div class="modal-actions"><button type="button" class="small-btn" data-close>Cancelar</button><button class="btn btn-danger" type="submit">${existing ? "Salvar alterações" : "Criar coleção"}</button></div></form></div>`;
    $("#modal-root").appendChild(overlay);
    $$('[data-close]', overlay).forEach(button => button.onclick = () => overlay.remove());
    overlay.addEventListener("click", event => { if (event.target === overlay) overlay.remove(); });
    $("#blog-shelf-collection-form", overlay).onsubmit = async event => {
      event.preventDefault();
      const form = new FormData(event.currentTarget);
      const name = String(form.get("name") || "").trim();
      const blogIds = form.getAll("blogIds");
      if (!name) return;
      const payload = { owner_id: state.session.user.id, name, cover_url: String(form.get("coverUrl") || "").trim() || null, is_public: form.get("isPublic") === "on", collection_type: "blog", blog_ids: blogIds, item_ids: [] };
      const result = existing ? await sb.from("shelf_collections").update(payload).eq("id", existing.id).eq("owner_id", state.session.user.id) : await sb.from("shelf_collections").insert({ id: `blog-shelf-${Date.now()}`, ...payload });
      if (result.error) return toast("Não foi possível criar a coleção de blogs.");
      overlay.remove();
      await loadAccount();
    };
  }

  async function deleteBlogShelfCollection(id) {
    const result = await sb.from("shelf_collections").delete().eq("id", id).eq("owner_id", state.session.user.id);
    if (result.error) return toast("Não foi possível excluir a coleção.");
    await loadAccount();
  }

  function publicCollectionCard(collection, canManage = false) {
    const blog = collection.collection_type === "blog";
    const factionCatalog = collection.is_faction_catalog === true;
    const count = blog ? (Array.isArray(collection.blog_ids) ? collection.blog_ids.length : 0) : (Array.isArray(collection.item_ids) ? collection.item_ids.length : 0);
    const cover = collection.cover_url || collection.coverUrl || instantCover({ title: collection.name });
    const href = factionCatalog ? `?pagina=faccoes&faccao=${encodeURIComponent(collection.faction_page_key)}&catalogo=${encodeURIComponent(collection.catalog_id)}` : publicProfileHref(collection.username, collection.id);
    const ownerLabel = factionCatalog ? `${collection.faction_emblem || ""} ${collection.faction_name}` : `@${collection.username || "usuário"}`;
    return `<article class="public-shelf-collection-card" data-public-collection="${escapeHTML(collection.id)}" data-public-owner="${escapeHTML(collection.username || "")}" ${factionCatalog ? `data-public-faction-page="${escapeHTML(collection.faction_page_key)}" data-public-faction-catalog="${escapeHTML(collection.catalog_id)}"` : ""} role="link" tabindex="0"><div class="public-shelf-collection-cover has-image" style="background-image:url('${escapeHTML(cover)}')"></div><div class="public-shelf-collection-info"><div class="eyebrow">${collection.is_featured ? "Destaque · " : ""}${factionCatalog ? "Catálogo de facção" : blog ? "Blogs" : "Quadrinhos"}</div><h3>${escapeHTML(collection.name)}</h3><p>${count} item(ns) · ${escapeHTML(ownerLabel)}${collection.likes ? ` · ${collection.likes} curtida(s)` : ""}</p><div class="shelf-section-actions"><span class="shelf-visibility is-public">Pública</span><a class="small-btn" href="${escapeHTML(href)}">Abrir</a>${canManage ? `<button class="small-btn" data-copy-collection="${escapeHTML(collection.id)}" data-copy-username="${escapeHTML(collection.username)}">Compartilhar</button><button class="small-btn" data-collection-feature="${escapeHTML(collection.id)}" data-collection-featured="${collection.is_featured ? "true" : "false"}">${collection.is_featured ? "Remover destaque" : "Destacar"}</button>` : ""}</div></div></article>`;
  }

  async function toggleShelfCollectionFeatured(id, featured) {
    if (!["moderator", "banca", "admin"].includes(state.profile?.plan)) return;
    const result = await sb.from("shelf_collections").update({ is_featured: !featured }).eq("id", id);
    if (result.error) return toast("Não foi possível atualizar o destaque da coleção.");
    if (state.section === "public-profile" && state.publicProfile?.profile) await loadPublicProfile(state.publicProfile.profile.username, state.publicProfile.collectionId || null);
    else await loadAccount();
  }

  function profileXpProgressMarkup(profile, compact = false) {
    if (normalizedPlan(profile) === "banca") {
      return `<div class="profile-xp-progress profile-xp-unavailable ${compact ? "is-compact" : ""}"><div class="profile-xp-head"><strong>Precisa de ajuda?</strong></div><small>Envie uma mensagem se tiver algum problema ou precisar de ajuda.</small></div>`;
    }
    const xp = Math.max(0, Number(profile?.xp) || 0);
    const level = Math.max(1, Number(profile?.level) || 1);
    const currentFloor = Math.pow(level - 1, 2) * 100;
    const nextFloor = Math.pow(level, 2) * 100;
    const progress = Math.max(0, Math.min(100, ((xp - currentFloor) / Math.max(1, nextFloor - currentFloor)) * 100));
    return `<div class="profile-xp-progress ${compact ? "is-compact" : ""}"><div class="profile-xp-head"><strong>Nível ${level}</strong><span>${xp.toLocaleString("pt-BR")} / ${nextFloor.toLocaleString("pt-BR")} XP para o nível ${level + 1}</span></div><div class="profile-xp-track"><span style="width:${progress.toFixed(2)}%"></span></div>${compact ? "" : `<small>${Math.max(0, nextFloor - xp).toLocaleString("pt-BR")} XP restantes · 🔥 ${Number(profile?.daily_streak || 0)} dia(s) de sequência</small>`}</div>`;
  }

  function profileBannerUrl(profile) {
    const value = String(profile?.profile_banner_url || "").trim();
    return /^https?:\/\//i.test(value) ? value : "/assets/estantepb.jpg";
  }

  function ensureProfileBanner(profile) {
    const content = $(".content");
    const header = $(".content .profile-header");
    if (!content || !header) return null;
    let banner = $(".profile-banner", content);
    if (!banner) {
      banner = document.createElement("div");
      banner.className = "profile-banner";
      header.before(banner);
      banner.appendChild(header);
    }
    const url = profileBannerUrl(profile).replace(/["\\)]/g, "");
    banner.style.setProperty("--profile-banner-image", `url("${url}")`);
    return banner;
  }

  function renderShelfLikePage({ profile, own, savedItems, savedSeries, readItems, completedItems, likedItems, categories = [], profileState = null, profileActions = "" }) {
    const canEditPersonalCollections = own || isOwnShelfProfile();
    const actions = own
      ? '<button class="small-btn" data-action="profile">Editar perfil</button><button class="small-btn" data-action="logout">Sair</button>'
      : profileActions;
    const publicPrefix = own ? "" : "public-";
    const personalCollectionOrder = normalizePersonalCollectionOrder(shelfCollectionOrderForProfile(profile), categories);
    const orderedCategories = categories.slice().sort((a, b) => personalCollectionOrder.indexOf(String(a.id)) - personalCollectionOrder.indexOf(String(b.id)));
    let categoryMarkup = orderedCategories.map(category => {
      const items = own ? shelfItemsByIds(category.itemIds) : publicCollectionItems(category, profileState);
      const liked = !own && profileState?.collectionLikes?.has(category.id);
      const likes = !own ? profileState?.collectionLikeCounts?.get(category.id) || 0 : 0;
      let extra = canEditPersonalCollections
        ? `<span class="shelf-visibility ${category.isPublic !== false ? "is-public" : "is-private"}">${category.isPublic !== false ? "Pública" : "Privada"}</span>${category.isPublic !== false ? `<button class="small-btn" data-copy-collection="${escapeHTML(category.id)}">Compartilhar</button>` : ""}<button class="small-btn" data-shelf-edit-category="${escapeHTML(category.id)}">Editar</button><button class="small-btn danger" data-shelf-delete-category="${escapeHTML(category.id)}">Excluir</button>`
        : `<span class="shelf-visibility is-public">Pública</span><button class="small-btn ${liked ? "is-liked" : ""}" data-like-collection="${escapeHTML(category.id)}" data-like-owner="${escapeHTML(profile.id)}">${liked ? "♥" : "♡"} ${likes}</button><a class="small-btn" href="${escapeHTML(publicProfileHref(profile.username, category.id))}">Abrir coleção</a><button class="small-btn" data-copy-collection="${escapeHTML(category.id)}" data-copy-username="${escapeHTML(profile.username)}">Compartilhar</button>`;
      if (!own && canEditPersonalCollections) {
        extra += `<button class="small-btn ${liked ? "is-liked" : ""}" data-like-collection="${escapeHTML(category.id)}" data-like-owner="${escapeHTML(profile.id)}">${liked ? "♥" : "♡"} ${likes}</button>`;
      }
      extra += personalCollectionControls(category.id, categories, isOwnShelfProfile());
      return shelfCollectionMarkup(category.name, items, `${publicPrefix}category:${category.id}`, own ? state.readingProgress : profileState?.readingProgress, own ? state.favoriteIds : profileState?.favoriteIds, extra, null, category.isSeries === true);
    }).join("");
    if (own || categories.length) categoryMarkup = `<section class="section shelf-categories"><div class="section-head shelf-categories-head"><div><h2 class="section-title">Coleções pessoais</h2><div class="section-subtitle">Misture séries e edições na mesma coleção</div></div>${canEditPersonalCollections ? '<button class="small-btn" data-shelf-new-category>+ Nova coleção</button>' : ""}</div>${categoryMarkup || '<div class="empty">Crie uma coleção para começar a organizar seus salvos.</div>'}</section>`;
    const ownTop10Profile = own || String(profile?.id || "") === String(state.session?.user?.id || "");
    const profileTop10Lists = (own ? state.top10Lists : (profileState?.top10Lists || [])).filter(list => ownTop10Profile || list.is_public !== false);
    return `<div class="content shelf-page${own ? "" : " public-profile-page"}"><div class="profile-header">${avatarMarkup(profile)}<div><div class="eyebrow">${factionDot(profile)}@${escapeHTML(profile?.username || "")}</div>${profile?.title ? `<div class="profile-title" style="--title-bg:${safeTitleColor(profile.title_color)}">${escapeHTML(profile.title)}</div>` : own ? "" : '<div class="section-subtitle">Perfil público</div>'}${trophyRoom(own ? state.achievements : profileState?.achievements)} </div><div class="profile-actions">${actions}</div></div><div class="section-head"><div><h1 class="section-title">Minha estante</h1><div class="section-subtitle">Coleções fixas para organizar seus quadrinhos e séries</div></div>${own ? '<button class="btn btn-danger" data-action="open-local-box">Abrir caixa</button>' : ""}</div><div class="notice local-box-notice"><b>Minha caixa:</b> leia arquivos do seu computador sem enviá-los para o servidor. Tudo fica apenas neste navegador e some quando você sair.</div>${savedItems.visible !== false ? shelfCollectionMarkup("Salvos", savedItems.items || savedItems, `${publicPrefix}saved`, own ? state.readingProgress : profileState?.readingProgress, own ? state.favoriteIds : profileState?.favoriteIds) : ""}${savedSeries.visible !== false ? shelfCollectionMarkup("Séries salvas", savedSeries.items || savedSeries, `${publicPrefix}series-saved`, own ? state.readingProgress : profileState?.readingProgress, own ? state.favoriteIds : profileState?.favoriteIds, "", null, true) : ""}${readItems.visible !== false ? shelfCollectionMarkup("Lidos", readItems.items || readItems, `${publicPrefix}read`, own ? state.readingProgress : profileState?.readingProgress, own ? state.favoriteIds : profileState?.favoriteIds) : ""}${completedItems.visible !== false ? shelfCollectionMarkup("Concluídos", completedItems.items || completedItems, `${publicPrefix}completed`, own ? state.readingProgress : profileState?.readingProgress, own ? state.favoriteIds : profileState?.favoriteIds, "", null, true) : ""}${likedItems.visible !== false ? shelfCollectionMarkup("Curtidos", likedItems.items || likedItems, `${publicPrefix}liked`, own ? state.readingProgress : profileState?.readingProgress, own ? state.favoriteIds : profileState?.favoriteIds) : ""}${categoryMarkup}<div class="shelf-tab-panel shelf-top10-panel" data-shelf-tab-panel="top10">${top10Markup(profileTop10Lists, ownTop10Profile)}</div></div>`;
  }

  function renderShelfPage() {
    if (!state.session) return renderLoginPage();
    const snapshot = ensureShelfSnapshot();
    const savedItems = shelfItemsByIds([...snapshot.saved].filter(id => !isSeriesId(id)), false);
    const savedSeries = shelfItemsByIds([...snapshot.saved].filter(isSeriesId), true);
    const readItems = shelfItemsByIds([...snapshot.read]);
    const completedItems = completedSeriesItems(state.readingProgress);
    const canCustomize = Boolean(state.profile);
    const categories = state.shelfCategories.map(category => ({ ...category, itemIds: (category.itemIds || []).filter(id => snapshot.saved.has(id)) }));
    return renderShelfLikePage({ profile: state.profile, own: true, savedItems, savedSeries, readItems, completedItems, likedItems: { items: [], visible: false }, categories: canCustomize ? categories.map(category => ({ ...category, isSeries: false })) : [] });
    return `<div class="content"><div class="profile-header">${avatarMarkup(state.profile)}<div><div class="eyebrow">@${escapeHTML(state.profile?.username || "")}</div>${state.profile?.title ? `<div class="profile-title" style="--title-bg:${safeTitleColor(state.profile.title_color)}">${escapeHTML(state.profile.title)}</div>` : ""}${trophyRoom(state.achievements)}</div><div class="profile-actions"><button class="small-btn" data-action="profile">Editar perfil</button><button class="small-btn" data-action="logout">Sair</button></div></div><div class="section-head"><div><h1 class="section-title">Minha estante</h1><div class="section-subtitle">Coleções fixas para organizar seus quadrinhos e séries</div></div><button class="btn btn-danger" data-action="open-local-box">Abrir caixa</button></div><div class="notice local-box-notice"><b>Minha caixa:</b> leia arquivos do seu computador sem enviá-los para o servidor. Tudo fica apenas neste navegador e some quando você sair.</div>${shelfCollectionMarkup("Salvos", savedItems, "saved")}${state.profile?.shelf_series_public !== false ? shelfCollectionMarkup("Séries salvas", savedSeries, "series-saved", state.readingProgress, state.favoriteIds, "", null, true) : ""}${shelfCollectionMarkup("Lidos", readItems, "read")}${state.profile?.shelf_completed_public !== false ? shelfCollectionMarkup("Concluídos", completedItems, "completed", state.readingProgress, state.favoriteIds, "", null, true) : ""}${canCustomize ? `<section class="section shelf-categories"><div class="section-head"><div><h2 class="section-title">Coleções pessoais</h2><div class="section-subtitle">Misture séries e edições na mesma coleção</div></div><button class="small-btn" data-shelf-new-category>+ Nova coleção</button></div>${categories.map(category => shelfCollectionMarkup(category.name, shelfItemsByIds(category.itemIds), `category:${category.id}`, state.readingProgress, state.favoriteIds, `<span class="shelf-visibility ${category.isPublic !== false ? "is-public" : "is-private"}">${category.isPublic !== false ? "Pública" : "Privada"}</span>${category.isPublic !== false ? `<button class="small-btn" data-copy-collection="${escapeHTML(category.id)}">Compartilhar</button>` : ""}<button class="small-btn" data-shelf-edit-category="${escapeHTML(category.id)}">Editar</button><button class="small-btn danger" data-shelf-delete-category="${escapeHTML(category.id)}">Excluir</button>`)).join("") || '<div class="empty">Crie uma coleção para começar a organizar seus salvos.</div>'}</section>` : ""}</div>`;
  }

  function renderPublicCollectionPage(publicState, category) {
    const profile = publicState.profile;
    const allItems = publicCollectionItems(category, publicState);
    const filter = state.collectionFilter || { field: "all", query: "" };
    const filteredItems = filterCollectionItems(allItems, filter.field, filter.query);
    const sortOrder = publicState.profile?.shelf_sort_orders?.[`category:${category.id}`] || category.sortOrder || "added_desc";
    const items = sortShelfItems(filteredItems, sortOrder, null, publicState.readingProgress);
    const isLiked = publicState.collectionLikes?.has(category.id);
    const likes = publicState.collectionLikeCounts?.get(category.id) || 0;
    const isOwner = String(state.session?.user?.id || "") === String(profile.id || "");
    const storedColor = category.coverStyles?.__themeColor;
    const collectionColor = /^#[0-9a-f]{6}$/i.test(String(storedColor || "")) ? storedColor : "#31202b";
    const cover = category.coverUrl ? `style="background-image:url('${escapeHTML(proxiedImageUrl(category.coverUrl))}')"` : "";
    const colorControl = isOwner ? `<div class="public-collection-color-control"><span>Mudar cor</span><div class="public-collection-color-palette" role="group" aria-label="Cores da coleção">${PUBLIC_COLLECTION_COLOR_OPTIONS.map(([color, label]) => `<button type="button" class="public-collection-color-swatch ${color.toLowerCase() === String(collectionColor).toLowerCase() ? "is-selected" : ""}" style="--swatch-color:${color}" data-public-collection-color="${escapeHTML(category.id)}" data-public-collection-color-value="${color}" aria-label="${label}" title="${label}"></button>`).join("")}</div></div>` : "";
    return `<div class="content public-collection-page"><div class="public-collection-hero" style="--public-collection-color:${escapeHTML(collectionColor)}"><div class="public-collection-icon ${category.coverUrl ? "has-cover" : ""}" ${cover}>${category.coverUrl ? "" : "▣"}</div><div><div class="eyebrow">Coleção pública</div><h1 class="section-title">${escapeHTML(category.name)}</h1><div class="collection-creator-block">${avatarMarkup(profile, "collection-creator-avatar")}<div><a class="collection-creator" href="${escapeHTML(publicProfileHref(profile.username))}">@${escapeHTML(profile.username)}</a>${profile.title ? `<div class="collection-creator-title" style="--title-bg:${safeTitleColor(profile.title_color)}">${escapeHTML(profile.title)}</div>` : ""}</div></div><div class="section-subtitle">${allItems.length} item(ns)</div>${colorControl}</div></div><div class="section-head"><div><h2 class="section-title">${escapeHTML(category.name)}</h2><div class="section-subtitle">Uma coleção compartilhada da Banca Digital</div></div><div class="shelf-section-actions"><button class="small-btn ${isLiked ? "is-liked" : ""}" data-like-collection="${escapeHTML(category.id)}" data-like-owner="${escapeHTML(profile.id)}">${isLiked ? "♥ Curtida" : "♡ Curtir"} · ${likes}</button><button class="small-btn" data-copy-collection="${escapeHTML(category.id)}" data-copy-username="${escapeHTML(profile.username)}">Copiar link</button><a class="small-btn" href="${escapeHTML(publicProfileHref(profile.username))}">Ver perfil</a></div></div><form class="collection-filter" data-collection-filter-form><select name="field"><option value="all" ${filter.field === "all" ? "selected" : ""}>Filtrar por qualquer campo</option><option value="author" ${filter.field === "author" ? "selected" : ""}>Autor</option><option value="publisher" ${filter.field === "publisher" ? "selected" : ""}>Editora</option><option value="character" ${filter.field === "character" ? "selected" : ""}>Personagem</option><option value="tag" ${filter.field === "tag" ? "selected" : ""}>Gênero / tag</option><option value="seriesTitle" ${filter.field === "seriesTitle" ? "selected" : ""}>Série</option><option value="title" ${filter.field === "title" ? "selected" : ""}>Título</option></select><input name="query" value="${escapeHTML(filter.query)}" placeholder="Digite para filtrar a coleção"><button class="small-btn">Filtrar</button></form><div class="collection-results-meta">${items.length} de ${allItems.length} item(ns)</div><div class="results-grid">${items.map(item => card(item, publicState.readingProgress, publicState.favoriteIds)).join("") || '<div class="empty">Nenhum quadrinho corresponde ao filtro.</div>'}</div></div>`;
  }

  function renderPublicBlogCollectionPage(publicState, collection) {
    const profile = publicState.profile;
    const posts = (collection.blogIds || [])
      .map(id => (publicState.authoredBlogPosts || []).find(post => String(post.id) === String(id)) || (publicState.savedBlogPosts || []).find(post => String(post.id) === String(id)) || (publicState.collectionBlogPosts || []).find(post => String(post.id) === String(id)))
      .filter(Boolean);
    return `<div class="content public-collection-page public-blog-collection-page"><div class="public-collection-hero"><div class="public-collection-icon ${collection.coverUrl ? "has-cover" : ""}" ${collection.coverUrl ? `style="background-image:url('${escapeHTML(proxiedImageUrl(collection.coverUrl))}')"` : ""}>${collection.coverUrl ? "" : "✎"}</div><div><div class="eyebrow">Coleção pública de blogs</div><h1 class="section-title">${escapeHTML(collection.name)}</h1><div class="collection-creator-block">${avatarMarkup(profile, "collection-creator-avatar")}<div><a class="collection-creator" href="${escapeHTML(publicProfileHref(profile.username))}">@${escapeHTML(profile.username)}</a>${profile.title ? `<div class="collection-creator-title" style="--title-bg:${safeTitleColor(profile.title_color)}">${escapeHTML(profile.title)}</div>` : ""}</div></div><div class="section-subtitle">${posts.length} blog(s)</div></div></div><div class="section-head"><div><h2 class="section-title">${escapeHTML(collection.name)}</h2><div class="section-subtitle">Uma coleção pública de blogs da Banca Digital</div></div><div class="shelf-section-actions"><button class="small-btn" data-copy-collection="${escapeHTML(collection.id)}" data-copy-username="${escapeHTML(profile.username)}">Compartilhar</button><a class="small-btn" href="${escapeHTML(publicProfileHref(profile.username))}">Ver perfil</a></div></div><div class="blog-shelf-grid">${posts.map(post => blogCard(post)).join("") || '<div class="empty">Nenhum blog nesta coleção.</div>'}</div></div>`;
  }

  function filterCollectionItems(items, field, query) {
    const normalized = String(query || "").trim().toLowerCase();
    if (!normalized) return items;
    return items.filter(item => {
      const values = field === "tag" ? (item.tags || []) : field === "character" ? characterNames(item) : field === "all" ? [item.title, item.seriesTitle, item.author, item.publisher, ...characterNames(item), ...(item.tags || [])] : [item[field]];
      return values.some(value => String(value || "").toLowerCase().includes(normalized));
    });
  }

  async function toggleCollectionLike(ownerId, collectionId) {
    if (!state.session) return openAuthPage();
    const publicState = state.publicProfile;
    if (!publicState?.collectionLikes) return;
    const liked = publicState.collectionLikes.has(collectionId);
    const query = sb.from("shelf_collection_likes");
    const result = liked
      ? await query.delete().eq("owner_id", ownerId).eq("collection_id", collectionId).eq("user_id", state.session.user.id)
      : await query.insert({ owner_id: ownerId, collection_id: collectionId, user_id: state.session.user.id });
    if (result.error) return toast("Não foi possível atualizar a curtida.");
    if (liked) {
      publicState.collectionLikes.delete(collectionId);
      publicState.collectionLikeCounts.set(collectionId, Math.max(0, (publicState.collectionLikeCounts.get(collectionId) || 1) - 1));
    } else {
      publicState.collectionLikes.add(collectionId);
      publicState.collectionLikeCounts.set(collectionId, (publicState.collectionLikeCounts.get(collectionId) || 0) + 1);
    }
    render();
  }

  async function openCollectionCommentsPopup(collection, ownerProfile) {
    if (!sb || !collection?.id || !ownerProfile?.id) return toast("Os comentários ainda não estão disponíveis.");
    const overlay = document.createElement("div");
    overlay.className = "modal-backdrop comments-modal-backdrop";
    overlay.innerHTML = `<div class="modal comments-modal"><div class="section-head"><div><h2>Comentários da coleção</h2><div class="section-subtitle">${escapeHTML(collection.name || "Coleção")}</div></div><button class="small-btn" data-close>Fechar</button></div><div class="comments-list"><span class="section-subtitle">Carregando...</span></div>${state.session ? '<form class="comment-form"><textarea name="body" maxlength="1000" required placeholder="Escreva um comentário..."></textarea><button class="small-btn" type="submit">Comentar</button></form>' : '<p class="section-subtitle">Entre para comentar.</p>'}</div>`;
    $("#modal-root").appendChild(overlay);
    overlay.addEventListener("click", event => { if (event.target === overlay) overlay.remove(); });
    $("[data-close]", overlay).onclick = () => overlay.remove();
    const list = $(".comments-list", overlay);
    const refresh = async () => {
      let result = await sb.from("shelf_collection_comments").select("id, collection_id, owner_id, user_id, body, created_at, profiles(username, avatar_url, title, title_color, faction_id, plan)").eq("collection_id", collection.id).order("created_at", { ascending: true });
      if (result.error && /profiles|schema cache|relationship/i.test(result.error.message || "")) {
        result = await sb.from("shelf_collection_comments").select("id, collection_id, owner_id, user_id, body, created_at").eq("collection_id", collection.id).order("created_at", { ascending: true });
      }
      if (result.error) {
        list.innerHTML = `<span class="section-subtitle">${escapeHTML(result.error.message || "Não foi possível carregar os comentários.")}</span>`;
        return;
      }
      list.innerHTML = (result.data || []).map(comment => {
        const profile = { ...(comment.profiles || {}), username: cleanUsername(comment.profiles?.username || "usuário") };
        const canDelete = comment.user_id === state.session?.user?.id || comment.owner_id === state.session?.user?.id || ["moderator", "banca", "admin"].includes(state.profile?.plan);
        return `<article class="comment"><div class="comment-author-row">${avatarMarkup(profile, "comment-avatar")}<div class="comment-author-info"><a class="comment-author" href="${escapeHTML(publicProfileHref(profile.username))}" target="_blank" rel="noopener">@${escapeHTML(profile.username)}</a>${profile.title ? `<span class="comment-title">${escapeHTML(profile.title)}</span>` : ""}</div></div><p>${escapeHTML(comment.body)}</p><div class="comment-actions">${canDelete ? `<button class="comment-action comment-delete-action" data-collection-comment-delete="${escapeHTML(comment.id)}">Excluir</button>` : ""}<time class="comment-date" datetime="${escapeHTML(comment.created_at)}">${escapeHTML(formatCommentDate(comment.created_at))}</time></div></article>`;
      }).join("") || '<span class="section-subtitle">Nenhum comentário ainda.</span>';
      $$('[data-collection-comment-delete]', overlay).forEach(button => button.onclick = async () => {
        const result = await sb.from("shelf_collection_comments").delete().eq("id", button.dataset.collectionCommentDelete);
        if (result.error) return toast(result.error.message || "Não foi possível excluir o comentário.");
        await refresh();
      });
    };
    await refresh();
    $(".comment-form", overlay)?.addEventListener("submit", async event => {
      event.preventDefault();
      if (!state.session?.user?.id) return openAuthPage();
      const form = event.currentTarget;
      const body = String(new FormData(form).get("body") || "").trim();
      if (!body) return;
      const button = $("button", form);
      button.disabled = true;
      const result = await sb.from("shelf_collection_comments").insert({ collection_id: collection.id, owner_id: ownerProfile.id, user_id: state.session.user.id, body });
      if (result.error) {
        const silencedUntil = state.profile?.silenced_until && new Date(state.profile.silenced_until) > new Date();
        toast(silencedUntil
          ? `Sua conta está silenciada até ${formatCommentDate(state.profile.silenced_until)}.`
          : "Não foi possível publicar. Sua conta pode estar temporariamente limitada por anti-spam ou impedida de comentar.");
      }
      else { awardProfileXp("comment", `collection-comment:${collection.id}:${Date.now()}`); form.reset(); await refresh(); }
      button.disabled = false;
    });
  }

  function moderationActionNeedsReason(action) {
    return ["ban", "hide", "silence", "delete_comment", "delete_blog", "delete_message"].includes(action);
  }

  function askModerationReason(action) {
    const required = state.profile?.plan !== "admin";
    return new Promise(resolve => {
      const overlay = document.createElement("div");
      overlay.className = "modal-backdrop moderation-reason-backdrop";
      overlay.innerHTML = `<div class="modal moderation-reason-modal"><div class="section-head"><div><div class="eyebrow">Auditoria de moderação</div><h2>Motivo da ação</h2><div class="section-subtitle">${required ? "Informe o motivo para registrar esta ação." : "O motivo é opcional para administradores."}</div></div><button type="button" class="small-btn" data-reason-cancel>Cancelar</button></div><form data-reason-form><label class="field"><span>Motivo${required ? " *" : ""}</span><textarea name="reason" rows="4" maxlength="500" ${required ? "required" : ""} placeholder="Descreva o motivo da ação"></textarea></label><label class="field"><span>Observação interna</span><textarea name="internalNote" rows="3" maxlength="1000" placeholder="Informação visível apenas para a equipe (opcional)"></textarea></label><div class="modal-actions"><button type="button" class="small-btn" data-reason-cancel>Cancelar</button><button type="submit" class="btn btn-danger">Confirmar ação</button></div></form></div>`;
      $("#modal-root").appendChild(overlay);
      const finish = value => { overlay.remove(); resolve(value); };
      $$('[data-reason-cancel]', overlay).forEach(button => button.onclick = () => finish(null));
      $("[data-reason-form]", overlay).onsubmit = event => {
        event.preventDefault();
        const form = new FormData(event.currentTarget);
        const reason = String(form.get("reason") || "").trim();
        if (required && !reason) return $("[name=reason]", overlay).reportValidity();
        finish({ reason: reason || null, internalNote: String(form.get("internalNote") || "").trim() || null });
      };
      overlay.addEventListener("click", event => { if (event.target === overlay) finish(null); });
      $("[name=reason]", overlay)?.focus();
    });
  }

  async function runModerationAction(target, action, duration = null, title = null, titleColor = null, reason = null, internalNote = null) {
    if (!sb || !target?.username) return;
    if (!canModerateProfile(target)) {
      return toast("Moderadores não podem alterar integrantes da equipe.");
    }
    if (action === "title") title = profileTitle(title);
    const result = await sb.rpc("moderate_user", { p_username: target.username, p_action: action, p_duration: duration, p_title: title, p_title_color: titleColor, p_reason: reason, p_internal_note: internalNote });
    if (result.error) return toast(result.error.message || "Não foi possível aplicar a moderação.");
    toast("Ação de moderação aplicada.");
    await loadPublicProfile(target.username, state.publicProfile?.collectionId || null);
  }

  function canModerateProfile(target) {
    const actorPlan = state.profile?.plan;
    const targetPlan = target?.plan;
    if (!["moderator", "banca", "admin"].includes(actorPlan)) return false;
    if (["banca", "admin"].includes(targetPlan)) return actorPlan === "admin";
    if (targetPlan === "moderator") return ["banca", "admin"].includes(actorPlan);
    return true;
  }

  function applyModerationTitleColors(overlay) {
    const input = $("input[name=titleColor]", overlay);
    if (!input) return;
    const colors = [
      ["#000000", "Preto"], ["#ffffff", "Branco"], ["#e50914", "Vermelho"],
      ["#2f80ed", "Azul"], ["#27ae60", "Verde"], ["#ffd45c", "Amarelo"],
      ["#8e44ad", "Roxo"], ["#f2994a", "Laranja"]
    ];
    const select = document.createElement("select");
    select.name = input.name;
    select.className = input.className;
    const currentColor = safeTitleColor(input.value);
    select.innerHTML = colors.map(([value, label]) => `<option value="${value}" ${value === currentColor ? "selected" : ""}>${label}</option>`).join("");
    input.replaceWith(select);
  }

  function attachPlanControl(overlay, target) {
    if (!overlay || !target || !["moderator", "banca", "admin"].includes(state.profile?.plan)) return;
    const locked = !canModerateProfile(target);
    if (locked) return;
    const historySection = $(".moderation-history", overlay)?.closest(".moderation-section");
    if (!historySection) return;
    const planSection = document.createElement("section");
    planSection.className = "moderation-section";
    planSection.innerHTML = `<h3>Tipo de conta</h3><form id="moderation-plan-form"><div class="moderation-plan-row"><select name="plan" ${locked ? "disabled" : ""}><option value="free" ${target.plan === "free" ? "selected" : ""}>Comum</option><option value="premium" ${target.plan === "premium" ? "selected" : ""}>Lenda</option></select><button class="small-btn" type="submit" ${locked ? "disabled" : ""}>Salvar tipo</button></div></form>`;
    if (locked) {
      const currentOption = document.createElement("option");
      currentOption.value = target.plan;
      currentOption.textContent = target.plan === "admin" ? "Administrador" : target.plan === "banca" ? "Banca" : "Moderador";
      currentOption.selected = true;
      $("select[name=plan]", planSection)?.appendChild(currentOption);
    }
    if (state.profile?.plan === "admin") {
      const planSelect = $("select[name=plan]", planSection);
      const moderatorOption = document.createElement("option");
      moderatorOption.value = "moderator";
      moderatorOption.textContent = "Moderador";
      planSelect?.appendChild(moderatorOption);
      const bancaOption = document.createElement("option");
      bancaOption.value = "banca";
      bancaOption.textContent = "Banca";
      planSelect?.appendChild(bancaOption);
      if (target.plan === "moderator") planSelect.value = "moderator";
      if (target.plan === "banca") planSelect.value = "banca";
    } else if (state.profile?.plan === "banca") {
      const planSelect = $("select[name=plan]", planSection);
      const moderatorOption = document.createElement("option");
      moderatorOption.value = "moderator";
      moderatorOption.textContent = "Moderador";
      planSelect?.appendChild(moderatorOption);
      if (target.plan === "moderator") planSelect.value = "moderator";
    }
    const planSelect = $("select[name=plan]", planSection);
    if (target.plan && ![...planSelect.options].some(option => option.value === target.plan)) {
      const currentOption = document.createElement("option");
      currentOption.value = target.plan;
      currentOption.textContent = target.plan === "banca" ? "Banca" : target.plan;
      currentOption.selected = true;
      planSelect.appendChild(currentOption);
    }
    historySection.before(planSection);
    $("#moderation-plan-form", planSection).onsubmit = async event => {
      event.preventDefault();
      const plan = String(new FormData(event.currentTarget).get("plan") || "free");
      const result = await sb.rpc("set_user_plan", { p_username: target.username, p_plan: plan });
      if (result.error) return toast(result.error.message || "Não foi possível alterar o tipo de conta.");
      toast("Tipo de conta atualizado.");
      overlay.remove();
      await loadPublicProfile(target.username, state.publicProfile?.collectionId || null);
    };
  }

  function openModerationPanel(target) {
    if (!target || !["moderator", "banca", "admin"].includes(state.profile?.plan)) return;
    const overlay = document.createElement("div");
    overlay.className = "modal-backdrop";
    const history = state.publicProfile?.moderationHistory || [];
    overlay.innerHTML = `<div class="modal moderation-modal"><div class="section-head"><div><h2>Moderação de @${escapeHTML(target.username)}</h2><div class="section-subtitle">Disponível para moderadores e administradores</div></div><button class="small-btn" data-close>Fechar</button></div><div class="admin-actions moderation-actions"><button class="small-btn danger" data-moderation="ban">Banir usuário</button><button class="small-btn" data-moderation="hide">Ocultar perfil</button><button class="small-btn" data-moderation="unban">Remover banimento</button><button class="small-btn" data-moderation="unhide">Mostrar perfil</button><button class="small-btn" data-moderation="unsilence">Remover silêncio</button></div><div class="field"><label>Silenciar comentários</label><div class="admin-actions"><button class="small-btn" data-silence="24h">24 horas</button><button class="small-btn" data-silence="3d">3 dias</button><button class="small-btn" data-silence="1m">1 mês</button></div></div><form id="moderation-title-form"><div class="field"><label>Título do perfil</label><input name="title" value="${escapeHTML(target.title || "")}" maxlength="80"></div><div class="field"><label>Cor do título</label><input name="titleColor" type="color" value="${escapeHTML(safeTitleColor(target.title_color))}"></div><button class="small-btn" type="submit">Salvar título</button></form><h3>Histórico de moderação</h3><div class="moderation-history">${history.map(entry => `<div class="moderation-history-item"><b>${escapeHTML(entry.action)}</b><span>@${escapeHTML(entry.actor_username || "moderador")} · ${escapeHTML(formatCommentDate(entry.created_at))}</span></div>`).join("") || '<span class="section-subtitle">Nenhuma ação registrada.</span>'}</div></div>`;
    $("#modal-root").appendChild(overlay);
    $("[data-close]", overlay).onclick = () => overlay.remove();
    $$('[data-moderation]', overlay).forEach(button => button.onclick = async () => {
      const action = button.dataset.moderation;
      const audit = moderationActionNeedsReason(action) ? await askModerationReason(action) : { reason: null, internalNote: null };
      if (!audit) return;
      await runModerationAction(target, action, null, null, null, audit.reason, audit.internalNote);
      overlay.remove();
    });
    $$('[data-silence]', overlay).forEach(button => button.onclick = async () => {
      const audit = await askModerationReason("silence");
      if (!audit) return;
      await runModerationAction(target, "silence", button.dataset.silence, null, null, audit.reason, audit.internalNote);
      overlay.remove();
    });
    $("#moderation-title-form", overlay).onsubmit = async event => { event.preventDefault(); const form = new FormData(event.currentTarget); await runModerationAction(target, "title", null, String(form.get("title") || ""), String(form.get("titleColor") || "#ffd45c")); overlay.remove(); };
  }

  function openModerationPanel(target) {
    if (!target || !["moderator", "banca", "admin"].includes(state.profile?.plan)) return;
    const overlay = document.createElement("div");
    overlay.className = "modal-backdrop";
    const history = state.publicProfile?.moderationHistory || [];
    const visibilityAction = target.profile_hidden ? "unhide" : "hide";
    const visibilityLabel = target.profile_hidden ? "Mostrar perfil" : "Ocultar perfil";
    overlay.addEventListener("click", event => { if (event.target === overlay) overlay.remove(); });
    const banAction = target.is_banned ? "unban" : "ban";
    const banLabel = target.is_banned ? "Remover banimento" : "Banir usuário";
    const silenceLabel = target.silenced_until ? `Silenciado até ${formatCommentDate(target.silenced_until)}` : "Usuário pode comentar";
    const targetIsStaff = ["moderator", "admin"].includes(target.plan);
    const canModerateTarget = canModerateProfile(target);
    const restrictedNotice = targetIsStaff && !canModerateTarget
      ? '<div class="notice">Moderadores não podem alterar o acesso, o perfil, os comentários ou o tipo de conta de outros integrantes da equipe.</div>'
      : "";
    overlay.innerHTML = `<div class="modal moderation-modal"><div class="section-head moderation-header"><div><div class="eyebrow">Painel de moderação</div><h2>@${escapeHTML(target.username)}</h2><div class="section-subtitle">Ações registradas no histórico do perfil</div></div><button class="small-btn" data-close>Fechar</button></div><div class="moderation-status">${target.profile_hidden ? "Perfil oculto" : "Perfil público"} · ${target.is_banned ? "Banido" : "Conta ativa"} · ${escapeHTML(silenceLabel)}</div><div class="moderation-grid"><section class="moderation-section"><h3>Perfil e acesso</h3><div class="moderation-button-grid"><button class="small-btn" data-moderation="${visibilityAction}">${visibilityLabel}</button><button class="small-btn danger" data-moderation="${banAction}">${banLabel}</button></div></section><section class="moderation-section"><h3>Comentários</h3><div class="admin-actions"><button class="small-btn" data-silence="24h">Silenciar 24 horas</button><button class="small-btn" data-silence="3d">Silenciar 3 dias</button><button class="small-btn" data-silence="1m">Silenciar 1 mês</button><button class="small-btn" data-moderation="unsilence">Remover silêncio</button></div></section></div><section class="moderation-section"><h3>Título do perfil</h3><form id="moderation-title-form"><div class="moderation-title-fields"><div class="field"><label>Texto</label><input name="title" value="${escapeHTML(target.title || "")}" maxlength="80" placeholder="Título do usuário"></div><div class="field"><label>Cor</label><input name="titleColor" type="color" value="${escapeHTML(safeTitleColor(target.title_color))}"></div></div><button class="small-btn" type="submit">Salvar título</button></form></section><section class="moderation-section"><h3>Histórico</h3><div class="moderation-history">${history.map(entry => `<div class="moderation-history-item"><b>${escapeHTML(entry.action)}</b><span>@${escapeHTML(entry.actor_username || "moderador")} · ${escapeHTML(formatCommentDate(entry.created_at))}</span></div>`).join("") || '<span class="section-subtitle">Nenhuma ação registrada.</span>'}</div></section></div>`;
    if (!canModerateTarget) {
      const moderationGrid = $(".moderation-grid", overlay);
      moderationGrid?.insertAdjacentHTML("beforebegin", restrictedNotice);
      moderationGrid?.remove();
      $$('input[name=title], input[name=titleColor], #moderation-title-form button', overlay).forEach(field => { field.disabled = true; });
    }
    $("#modal-root").appendChild(overlay);
    $("[data-close]", overlay).onclick = () => overlay.remove();
    $$('[data-moderation]', overlay).forEach(button => button.onclick = async () => {
      const action = button.dataset.moderation;
      const audit = moderationActionNeedsReason(action) ? await askModerationReason(action) : { reason: null, internalNote: null };
      if (!audit) return;
      await runModerationAction(target, action, null, null, null, audit.reason, audit.internalNote);
      overlay.remove();
    });
    $$('[data-silence]', overlay).forEach(button => button.onclick = async () => {
      const audit = await askModerationReason("silence");
      if (!audit) return;
      await runModerationAction(target, "silence", button.dataset.silence, null, null, audit.reason, audit.internalNote);
      overlay.remove();
    });
    $("#moderation-title-form", overlay).onsubmit = async event => { event.preventDefault(); const form = new FormData(event.currentTarget); await runModerationAction(target, "title", null, String(form.get("title") || ""), String(form.get("titleColor") || "#ffd45c")); overlay.remove(); };
  }

  async function deletePublicCollection(ownerId, collectionId) {
    if (!["moderator", "banca", "admin"].includes(state.profile?.plan)) return;
    const result = await sb.from("shelf_collections").delete().eq("owner_id", ownerId).eq("id", collectionId);
    if (result.error) return toast("Não foi possível excluir a coleção.");
    toast("Coleção pública excluída.");
    await loadPublicProfile(state.publicProfile.profile.username, null);
  }

  function openProfileBlockConfirm(profile, blocked) {
    return new Promise(resolve => {
      const overlay = document.createElement("div");
      overlay.className = "modal-backdrop";
      overlay.innerHTML = `<div class="modal profile-block-confirm-modal"><div class="section-head"><div><div class="eyebrow">Privacidade</div><h2>${blocked ? "Desbloquear usuário?" : "Bloquear usuário?"}</h2><div class="section-subtitle">${blocked ? "Este usuário poderá voltar a ver seu perfil e interagir com você." : "Este usuário não poderá enviar mensagens, comentar no seu mural ou acessar seu perfil, histórico e coleções."}</div></div><button type="button" class="small-btn" data-close>Cancelar</button></div><div class="modal-actions"><button type="button" class="small-btn" data-close>Cancelar</button><button type="button" class="btn btn-danger" data-confirm-block>${blocked ? "Desbloquear" : "Bloquear"}</button></div></div>`;
      $("#modal-root").appendChild(overlay);
      const finish = value => { overlay.remove(); resolve(value); };
      $$('[data-close]', overlay).forEach(button => button.onclick = () => finish(false));
      $("[data-confirm-block]", overlay).onclick = () => finish(true);
    });
  }

  async function toggleProfileBlock(profile) {
    if (!state.session || !sb) return openAuthPage();
    if (!profile?.id || profile.id === state.session.user.id) return;
    const blocked = Boolean(state.publicProfile?.blockedByMe);
    if (!await openProfileBlockConfirm(profile, blocked)) return;
    const query = sb.from("profile_blocks");
    const result = blocked
      ? await query.delete().eq("blocker_id", state.session.user.id).eq("blocked_id", profile.id)
      : await query.insert({ blocker_id: state.session.user.id, blocked_id: profile.id });
    if (result.error) return toast(result.error.message || "Não foi possível atualizar o bloqueio.");
    await loadPublicProfile(profile.username);
  }

  async function toggleProfileFollow(profile) {
    if (!state.session) return openAuthPage();
    if (!profile?.id || profile.id === state.session.user.id) return;
    const publicState = state.publicProfile;
    const following = Boolean(publicState?.isFollowing);
    const query = sb.from("profile_follows");
    const result = following
      ? await query.delete().eq("follower_id", state.session.user.id).eq("following_id", profile.id)
      : await query.insert({ follower_id: state.session.user.id, following_id: profile.id });
    if (result.error) return toast("Não foi possível atualizar o acompanhamento.");
    publicState.isFollowing = !following;
    if (!following) await awardProfileXp("follow", `follow:${profile.id}`);
    publicState.followerCount = Math.max(0, (publicState.followerCount || 0) + (following ? -1 : 1));
    state.followingCount = Math.max(0, (state.followingCount || 0) + (following ? -1 : 1));
    render();
  }

  function renderPublicProfilePage() {
    const publicState = state.publicProfile;
    if (!publicState || publicState.loading || (publicState.collectionId && publicState.detailsLoading)) return '<div class="content"><div class="empty">Carregando perfil...</div></div>';
    if (publicState.error) return `<div class="content"><div class="empty">${escapeHTML(publicState.error)}</div></div>`;
    const profile = publicState.profile;
    if (publicState.blocked) return `<div class="content public-profile-page"><section class="section blocked-profile-notice"><div class="eyebrow">Privacidade</div><h1 class="section-title">Perfil indisponível</h1><p>${publicState.blockedByMe ? "Você bloqueou este usuário. Ele não pode enviar mensagens, comentar no seu mural ou acessar seu histórico, coleções e foto." : "Este perfil não está disponível para você."}</p><div class="profile-actions"><button class="small-btn" data-section="home">Voltar ao início</button>${publicState.blockedByMe ? `<button class="small-btn" data-unblock-profile>Desbloquear</button>` : ""}</div></section></div>`;
    const savedVisible = profile.shelf_saved_public !== false;
    const seriesVisible = profile.shelf_series_public !== false;
    const readVisible = profile.shelf_read_public !== false;
    const completedVisible = profile.shelf_completed_public !== false;
    const likedVisible = profile.shelf_liked_public !== false;
    const wallVisible = profile.profile_wall_public !== false;
    const savedPublicCollectionsVisible = profile.shelf_saved_public_collections !== false;
    const activityVisible = profile.profile_activity_public !== false;
    const savedItems = shelfItemsByIds([...publicState.favoriteIds].filter(id => !isSeriesId(id)), false);
    const savedSeries = shelfItemsByIds([...publicState.favoriteIds].filter(isSeriesId), true);
    const readItems = shelfItemsByIds([...publicState.readingProgress.entries()].filter(([, row]) => row.completed).map(([id]) => id));
    const likedItems = uniqueCatalogItems(state.db.library.filter(item => publicState.comicLikeIds?.has(item.id)));
    const completedItems = completedSeriesItems(publicState.readingProgress);
    const publicCategories = (publicState.collections || []).filter(category => category.isPublic !== false);
    const publicBlogCollections = (publicState.blogCollections || []).filter(collection => collection.isPublic !== false);
    const selectedCategory = publicCategories.find(category => category.id === publicState.collectionId);
    const selectedBlogCollection = publicBlogCollections.find(collection => collection.id === publicState.collectionId);
    if (publicState.collectionId && selectedCategory) return renderPublicCollectionPage(publicState, selectedCategory);
    if (publicState.collectionId && selectedBlogCollection) return renderPublicBlogCollectionPage(publicState, selectedBlogCollection);
    if (publicState.album && !canAccessStickerAlbum(profile)) {
      return '<div class="content"><div class="empty">O álbum não está disponível para usuários Banca.</div></div>';
    }
    if (publicState.album) {
      const isOwnAlbum = Boolean(state.session?.user?.id && String(state.session.user.id) === String(profile.id));
      return stickerAlbumMarkup(profile, publicState.stickerAwards || [], { isOwn: isOwnAlbum, progressMap: publicState.readingProgress });
    }
    if (publicState.collectionId && !selectedCategory && !selectedBlogCollection) return `<div class="content"><div class="empty">Esta coleção não existe ou é privada.</div><a class="small-btn" href="${escapeHTML(publicProfileHref(profile.username))}">Voltar ao perfil</a></div>`;
    const canFollow = Boolean(state.session?.user?.id && state.session.user.id !== profile.id);
    const canBlock = canFollow;
    const isOwnProfile = Boolean(state.session?.user?.id && String(state.session.user.id) === String(profile.id));
    const canModerate = !isOwnProfile && canModerateProfile(profile);
    const publicProfileActions = isOwnProfile
      ? '<button class="small-btn" data-profile-sticker-choose>Figurinha</button><button class="small-btn" data-action="profile">Editar perfil</button><button class="small-btn" data-action="logout">Sair</button>'
      : `${canFollow ? `<button class="small-btn follow-button ${publicState.isFollowing ? "is-following" : ""}" data-follow-profile>${publicState.isFollowing ? "Seguindo" : "Seguir"}</button>` : ""}${canBlock ? `<button class="small-btn block-button" data-block-profile>Bloquear</button>` : ""}<button class="small-btn" data-section="home">Voltar ao início</button>${canModerate ? `<button class="small-btn moderation-button" data-open-moderation>Moderação</button>` : ""}`;
    return renderShelfLikePage({ profile, own: false, savedItems: { items: savedItems, visible: savedVisible }, savedSeries: { items: savedSeries, visible: seriesVisible }, readItems: { items: readItems, visible: readVisible }, completedItems: { items: completedItems, visible: completedVisible }, likedItems: { items: likedItems, visible: likedVisible }, categories: isOwnProfile ? (publicState.collections || []) : publicCategories, profileState: publicState, profileActions: publicProfileActions });
    const publicShelfMarkup = renderShelfLikePage({ profile, own: false, savedItems: { items: savedItems, visible: savedVisible }, savedSeries: { items: savedSeries, visible: seriesVisible }, readItems: { items: readItems, visible: readVisible }, completedItems: { items: completedItems, visible: completedVisible }, likedItems: { items: likedItems, visible: likedVisible }, categories: publicCategories, profileState: publicState });
    const profileActions = `${canFollow ? `<button class="small-btn follow-button ${publicState.isFollowing ? "is-following" : ""}" data-follow-profile>${publicState.isFollowing ? "Seguindo" : "Seguir"}</button>` : ""}${canBlock ? `<button class="small-btn block-button" data-block-profile>Bloquear</button>` : ""}<button class="small-btn" data-section="home">Voltar ao início</button>${canModerate ? `<button class="small-btn moderation-button" data-open-moderation>Moderação</button>` : ""}`;
    if (false) {
    return `<div class="content public-profile-page"><div class="profile-header">${profileStickerMarkup(profile, publicState.stickerAwards || [])}${avatarMarkup(profile)}<div><div class="eyebrow">${factionDot(profile)}@${escapeHTML(profile.username)}</div>${profile.title ? `<div class="profile-title" style="--title-bg:${safeTitleColor(profile.title_color)}">${escapeHTML(profile.title)}</div>` : '<div class="section-subtitle">Perfil público</div>'}${trophyRoom(publicState.achievements)}${followSummary(profile.id, publicState.followerCount, publicState.followingCount)}</div><div class="profile-actions">${profileActions}</div></div>${wallVisible ? profileWallMarkup(publicState) : '<section class="section"><div class="empty">O mural deste perfil está oculto.</div></section>'}</div>`;
    }
    return `<div class="content public-profile-page">
      <div class="profile-header">
        ${profileStickerMarkup(profile, publicState.stickerAwards || [])}${avatarMarkup(profile)}
        <div>
          <div class="eyebrow">${factionDot(profile)}@${escapeHTML(profile.username)} ${officialAiBadge(profile)}</div>
          ${profile.title ? `<div class="profile-title" style="--title-bg:${safeTitleColor(profile.title_color)}">${escapeHTML(profile.title)}</div>` : '<div class="section-subtitle">Perfil público</div>'}
          ${trophyRoom(publicState.achievements)}
          ${followSummary(profile.id, publicState.followerCount, publicState.followingCount)}
        </div>
      </div>
      <div class="section-head"><div><h1 class="section-title">Estante de @${escapeHTML(profile.username)}</h1><div class="section-subtitle">${publicState.followerCount || 0} seguidores · ${publicState.followingCount || 0} seguindo · Coleções públicas do perfil</div></div><div class="profile-actions">${canFollow ? `<button class="small-btn follow-button ${publicState.isFollowing ? "is-following" : ""}" data-follow-profile>${publicState.isFollowing ? "Seguindo" : "Seguir"}</button>` : ""}${canBlock ? `<button class="small-btn block-button" data-block-profile>Bloquear</button>` : ""}<button class="small-btn" data-section="home">Voltar ao início</button>${canModerate ? `<button class="small-btn moderation-button" data-open-moderation>Moderação</button>` : ""}</div></div>
      ${savedVisible ? shelfCollectionMarkup("Salvos", savedItems, "public-saved", publicState.readingProgress, publicState.favoriteIds) : '<div class="notice">A coleção Salvos está oculta neste perfil.</div>'}
      ${seriesVisible ? shelfCollectionMarkup("Séries salvas", savedSeries, "public-series-saved", publicState.readingProgress, publicState.favoriteIds, "", null, true) : '<div class="notice">A coleção Séries salvas está oculta neste perfil.</div>'}
      ${readVisible ? shelfCollectionMarkup("Lidos", readItems, "public-read", publicState.readingProgress, publicState.favoriteIds) : '<div class="notice">A coleção Lidos está oculta neste perfil.</div>'}
      ${completedVisible ? shelfCollectionMarkup("Concluídos", completedItems, "public-completed", publicState.readingProgress, publicState.favoriteIds, "", null, true) : '<div class="notice">A coleção Concluídos está oculta neste perfil.</div>'}
      ${likedVisible ? shelfCollectionMarkup("Curtidos", likedItems, "public-liked", publicState.readingProgress, publicState.favoriteIds) : '<div class="notice">A coleção Curtidos está oculta neste perfil.</div>'}
      ${publicCategories.map(category => { const items = publicCollectionItems(category, publicState); const liked = publicState.collectionLikes?.has(category.id); const likes = publicState.collectionLikeCounts?.get(category.id) || 0; return shelfCollectionMarkup(category.name, items, `public-category:${category.id}`, publicState.readingProgress, publicState.favoriteIds, `<span class="shelf-visibility is-public">Pública</span><button class="small-btn ${liked ? "is-liked" : ""}" data-like-collection="${escapeHTML(category.id)}" data-like-owner="${escapeHTML(profile.id)}">${liked ? "♥" : "♡"} ${likes}</button><a class="small-btn" href="${escapeHTML(publicProfileHref(profile.username, category.id))}">Abrir coleção</a><button class="small-btn" data-copy-collection="${escapeHTML(category.id)}" data-copy-username="${escapeHTML(profile.username)}">Compartilhar</button>`); }).join("")}
    </div>`;
  }

  function renderCatalogLegacyBase(type = null) {
    const items = visibleCatalogItems(type ? state.db.library.filter(x => x.type === type) : state.db.library);
     const characterCarousel = type === "comic" ? `${characterWikiCarouselMarkup(items)}${teamWikiCarouselMarkup(items)}` : "";
    return `
      <div class="content">
        <div class="section-head">
          <div>
            <h1 class="section-title">${type === "manga" ? "Mangás" : type === "comic" ? "Quadrinhos" : "Catálogo"}</h1>
            <div class="section-subtitle">${items.length} edição(ões)</div>
          </div>
        </div>
        <div class="results-grid">${uniqueCatalogItems(items).map(item => card(item)).join("") || `<div class="empty">Nenhuma edição cadastrada.</div>`}</div>
        ${characterCarousel}
      </div>`;
  }

  function characterWikiCarouselMarkup(items) {
    const characters = new Map();
    items.forEach(item => characterNames(item).forEach(name => {
      const character = String(name || "").trim();
      const key = character.toLocaleLowerCase("pt-BR");
      if (character && !isTeamCharacter(character) && !isRedirectedCharacter(character) && !characters.has(key)) characters.set(key, character);
    }));
    const entries = [...characters.values()].sort((a, b) => a.localeCompare(b, "pt-BR"));
    if (!entries.length) return "";
    const cardMarkup = character => {
      const setting = state.characterSettings.get(publisherKey(character)) || {};
      const image = setting.cover_url || wikiCharacterImageCache.get(character) || "assets/batmanicon.jpg";
      return `<button type="button" class="wiki-character-card" data-wiki-character="${escapeHTML(character)}" aria-label="Ver personagem ${escapeHTML(character)}"><span class="wiki-character-image"><img src="${escapeHTML(image)}" alt="Imagem de ${escapeHTML(character)}" loading="lazy"></span><strong>${escapeHTML(character)}</strong></button>`;
    };
    const cards = entries.map(cardMarkup).join("");
    const repeated = `${cards}${cards}`;
    return `<section class="section wiki-character-carousel-section"><div class="section-head"><div><h2 class="section-title">Personagens</h2><div class="section-subtitle">Explore os personagens presentes nos quadrinhos.</div></div></div><div class="wiki-character-carousel"><div class="wiki-character-track">${repeated}</div></div></section>`;
  }

  function teamWikiCarouselMarkup(items) {
    const teams = new Map();
    state.characterSettings.forEach(setting => {
      if (setting?.character_type !== "team") return;
      const team = String(setting.character_name || "").trim();
      if (team && !isRedirectedCharacter(team)) teams.set(publisherKey(team), team);
    });
    items.forEach(item => characterNames(item).forEach(name => {
      const team = String(name || "").trim();
      if (team && isTeamCharacter(team) && !isRedirectedCharacter(team) && !teams.has(publisherKey(team))) teams.set(publisherKey(team), team);
    }));
    const entries = [...teams.values()].sort((a, b) => a.localeCompare(b, "pt-BR"));
    if (!entries.length) return "";
    const cards = entries.map(team => {
      const setting = state.characterSettings.get(publisherKey(team)) || {};
      const image = setting.cover_url || wikiCharacterImageCache.get(team) || "assets/batmanicon.jpg";
      return `<button type="button" class="wiki-character-card" data-wiki-character="${escapeHTML(team)}" aria-label="Ver equipe ${escapeHTML(team)}"><span class="wiki-character-image"><img src="${escapeHTML(imageProxyFetchUrl(image))}" alt="Imagem de ${escapeHTML(team)}" loading="lazy"></span><strong>${escapeHTML(team)}</strong></button>`;
    }).join("");
    return `<section class="section wiki-team-carousel-section"><div class="section-head"><div><h2 class="section-title">Equipes</h2><div class="section-subtitle">Explore as equipes presentes nos quadrinhos.</div></div></div><div class="wiki-character-carousel"><div class="wiki-character-track wiki-team-track">${cards}</div></div></section>`;
  }

  const TOP10_MAX_ITEMS = 100;
  const TOP10_CHARACTER_CATEGORIES = [
    ["team", "Equipes"],
    ["villain", "Vilões"],
    ["support", "Secundários"],
    ["hero", "Heróis"],
    ["antihero", "Anti-heróis"]
  ];
  const TOP10_DEFAULT_CHARACTER_CATEGORIES = TOP10_CHARACTER_CATEGORIES.map(([key]) => key);

  async function loadTop10Lists(ownerId) {
    if (!sb || !ownerId) return [];
    const listsResult = await sb.from("profile_top10_lists").select("id, owner_id, name, list_type, character_categories, is_final, sort_order, is_public, created_at, updated_at").eq("owner_id", ownerId).order("sort_order", { ascending: true }).order("created_at", { ascending: true });
    if (listsResult.error || !listsResult.data?.length) return [];
    const ids = listsResult.data.map(list => list.id);
    const itemsResult = await sb.from("profile_top10_items").select("id, list_id, character_key, character_name, image_url, rank").in("list_id", ids).order("rank", { ascending: true });
    const itemsByList = new Map(ids.map(id => [id, []]));
    (itemsResult.data || []).forEach(item => itemsByList.get(item.list_id)?.push(item));
    const itemIds = (itemsResult.data || []).map(item => item.id);
    const votesResult = itemIds.length ? await sb.from("profile_top10_item_votes").select("item_id, user_id, vote").in("item_id", itemIds) : { data: [] };
    const commentsResult = await sb.from("profile_top10_list_comments").select("list_id").in("list_id", ids);
    const commentCounts = (commentsResult.data || []).reduce((counts, comment) => counts.set(String(comment.list_id), (counts.get(String(comment.list_id)) || 0) + 1), new Map());
    const votesByItem = new Map(itemIds.map(id => [id, { likes: 0, dislikes: 0, userVote: 0 }]));
    (votesResult.data || []).forEach(vote => {
      const summary = votesByItem.get(vote.item_id);
      if (!summary) return;
      if (vote.vote === 1) summary.likes += 1;
      if (vote.vote === -1) summary.dislikes += 1;
      if (String(vote.user_id) === String(state.session?.user?.id || "")) summary.userVote = vote.vote;
    });
    return listsResult.data.map(list => ({
      ...list,
      comment_count: commentCounts.get(String(list.id)) || 0,
      items: (itemsByList.get(list.id) || []).map(item => {
        const votes = votesByItem.get(item.id) || { likes: 0, dislikes: 0, userVote: 0 };
        item = { ...item, ...votes };
        if (list.list_type !== "story") return item;
        const story = state.db.library.find(entry => String(entry.id) === String(item.character_key));
        return story ? { ...item, character_name: item.character_name === story.title ? top10StoryLabel(story) : item.character_name, image_url: item.image_url || coverFor(story) || null } : item;
      })
    }));
  }

  function top10CharacterEntries() {
    const characters = new Map();
    state.db.library.forEach(item => characterNames(item).forEach(rawName => {
      const name = String(rawName || "").trim();
      const key = name.toLocaleLowerCase("pt-BR");
      if (name && !isRedirectedCharacter(name) && !characters.has(key)) characters.set(key, name);
    }));
    return [...characters.entries()].sort((a, b) => a[1].localeCompare(b[1], "pt-BR"));
  }

  function top10CharacterCategory(name) {
    const setting = characterSettingForName(name);
    if (setting?.character_type === "team" || isTeamCharacter(name)) return "team";
    return TOP10_CHARACTER_CATEGORIES.some(([key]) => key === setting?.character_alignment) ? setting.character_alignment : "support";
  }

  function top10CharacterCategoriesForList(list) {
    const selected = Array.isArray(list?.character_categories) ? list.character_categories : TOP10_DEFAULT_CHARACTER_CATEGORIES;
    return new Set(selected.length ? selected : TOP10_DEFAULT_CHARACTER_CATEGORIES);
  }

  function top10StoryEntries() {
    return [...new Map(state.db.library.filter(item => item?.id && item?.title).map(item => [String(item.id), item])).values()]
      .map(item => [String(item.id), top10StoryLabel(item), item])
      .filter(([, name]) => name)
      .sort((a, b) => a[1].localeCompare(b[1], "pt-BR"));
  }

  function top10StoryLabel(item) {
    return [item.title || itemDisplayTitle(item), item.issue ? `#${item.issue}` : "", item.year ? `(${item.year})` : ""].filter(Boolean).join(" · ");
  }

  function top10EntriesForList(list) {
    if (list?.list_type === "story") return top10StoryEntries();
    const categories = top10CharacterCategoriesForList(list);
    return top10CharacterEntries().filter(([, name]) => categories.has(top10CharacterCategory(name))).map(([key, name]) => [key, name, null]);
  }

  function top10StorySeriesKey(item, key) {
    return item?.seriesId ? `series:${item.seriesId}` : `item:${key}`;
  }

  function updateTop10VoteButtons(item, controls) {
    const likeButton = $("[data-top10-vote='1']", controls);
    const dislikeButton = $("[data-top10-vote='-1']", controls);
    if (!likeButton || !dislikeButton) return;
    likeButton.textContent = `👍 ${item.likes || 0}`;
    dislikeButton.textContent = `👎 ${item.dislikes || 0}`;
    likeButton.classList.toggle("is-active", item.userVote === 1);
    dislikeButton.classList.toggle("is-active", item.userVote === -1);
  }

  function top10ListReason(list) {
    return (list?.items || []).reduce((total, item) => total + (Number(item.likes) || 0) - (Number(item.dislikes) || 0), 0);
  }

  function updateTop10Reason(list, card) {
    if (!card) return;
    const reason = $("[data-top10-reason]", card);
    if (reason) reason.textContent = `★ Razão: ${top10ListReason(list)}`;
  }

  function top10ListShareUrl(list) {
    const username = state.section === "public-profile" ? state.publicProfile?.profile?.username : state.profile?.username;
    const url = new URL(window.location.href);
    url.search = "";
    url.hash = "";
    url.searchParams.set("perfil", cleanUsername(username || ""));
    url.searchParams.set("lista_top10", String(list.id));
    return url.toString();
  }

  async function shareTop10List(list) {
    const url = top10ListShareUrl(list);
    const shareData = { title: list.name, text: `Veja a lista ${list.name} na Banca Digital`, url };
    if (navigator.share) await navigator.share(shareData).catch(() => {});
    else {
      await navigator.clipboard?.writeText(url);
      toast("Link da lista copiado.");
    }
  }

  async function openTop10ListComments(list) {
    const overlay = document.createElement("div");
    overlay.className = "modal-backdrop";
    overlay.innerHTML = `<div class="modal top10-comments-modal"><div class="section-head"><div><h2>Comentários</h2><div class="section-subtitle">${escapeHTML(list.name)}</div></div><button class="small-btn" data-close>Fechar</button></div><div class="top10-comments-list"><span class="section-subtitle">Carregando...</span></div>${state.session ? '<form class="comment-form" data-top10-list-comment-form><textarea name="body" maxlength="1000" required placeholder="Escreva um comentário..."></textarea><button class="small-btn" type="submit">Comentar</button></form>' : '<p class="section-subtitle">Entre para comentar.</p>'}</div>`;
    $("#modal-root").appendChild(overlay);
    const close = () => overlay.remove();
    $("[data-close]", overlay).onclick = close;
    overlay.addEventListener("click", event => { if (event.target === overlay) close(); });
    const commentsList = $(".top10-comments-list", overlay);
    const renderComments = comments => {
      commentsList.innerHTML = comments.map(comment => {
        const profile = { ...(comment.profiles || {}), username: cleanUsername(comment.profiles?.username || "usuário") };
        const canDelete = state.session?.user?.id === comment.user_id || ["moderator", "banca", "admin"].includes(state.profile?.plan);
        return `<article class="comment top10-list-comment${comment.parent_id ? " is-reply" : ""}" data-top10-list-comment="${escapeHTML(comment.id)}">${avatarMarkup(profile, "comment-avatar")}<div class="top10-list-comment-body"><div class="comment-author-info"><a class="comment-author" href="${escapeHTML(publicProfileHref(profile.username))}">@${escapeHTML(profile.username)}</a></div><div class="top10-list-comment-text">${chatBodyMarkup(comment.body)}</div><div class="top10-list-comment-footer"><time class="comment-date">${escapeHTML(formatCommentDate(comment.created_at))}</time><button type="button" class="comment-action" data-top10-list-comment-reply="${escapeHTML(comment.id)}">Responder</button>${canDelete ? `<button type="button" class="comment-action comment-delete-action" data-top10-list-comment-delete="${escapeHTML(comment.id)}">Excluir</button>` : ""}</div></div></article>`;
      }).join("") || '<span class="section-subtitle">Nenhum comentário ainda.</span>';
    };
    const refresh = async () => {
      const result = await sb.from("profile_top10_list_comments").select("id, parent_id, user_id, body, created_at").eq("list_id", list.id).order("created_at", { ascending: true });
      if (result.error) { commentsList.innerHTML = '<span class="section-subtitle">Não foi possível carregar os comentários.</span>'; return; }
      const userIds = [...new Set((result.data || []).map(comment => comment.user_id).filter(Boolean))];
      const profiles = userIds.length ? await sb.from("profiles").select("id, username, avatar_url, title, title_color, plan").in("id", userIds) : { data: [] };
      const profilesById = new Map((profiles.data || []).map(profile => [profile.id, profile]));
      const comments = (result.data || []).map(comment => ({ ...comment, profiles: profilesById.get(comment.user_id) || {} }));
      renderComments(comments);
      hydrateChatTop10Previews(commentsList);
      list.comment_count = comments.length;
      $(`[data-top10-comments="${list.id}"]`)?.replaceChildren(document.createTextNode(`Comentários · ${comments.length}`));
    };
    commentsList.addEventListener("click", async event => {
      const deleteButton = event.target.closest?.("[data-top10-list-comment-delete]");
      if (deleteButton) {
        if (!await openSiteConfirm("Excluir este comentário e suas respostas?", { title: "Excluir comentário", confirmLabel: "Excluir comentário" })) return;
        const result = await sb.from("profile_top10_list_comments").delete().eq("id", deleteButton.dataset.top10ListCommentDelete).eq("list_id", list.id);
        if (result.error) return toast("Não foi possível excluir o comentário.");
        deleteButton.closest("[data-top10-list-comment]")?.remove();
        await refresh();
        return;
      }
      const replyButton = event.target.closest?.("[data-top10-list-comment-reply]");
      if (replyButton && state.session) {
        const comment = replyButton.closest("[data-top10-list-comment]");
        if (!$("[data-top10-list-reply-form]", comment)) comment.insertAdjacentHTML("beforeend", '<form class="comment-form top10-list-reply-form" data-top10-list-reply-form><textarea name="body" maxlength="1000" required placeholder="Escreva uma resposta..."></textarea><button class="small-btn" type="submit">Responder</button></form>');
      } else if (replyButton) openAuthPage();
    });
    await refresh();
    $("[data-top10-list-comment-form]", overlay)?.addEventListener("submit", async event => {
      event.preventDefault();
      if (!state.session?.user?.id) return openAuthPage();
      const form = event.currentTarget;
      const body = String(new FormData(form).get("body") || "").trim();
      if (!body) return;
      const button = $("button[type=submit]", form);
      button.disabled = true;
      const replyTo = form.closest("[data-top10-list-comment]")?.dataset.top10ListComment || null;
      const result = await sb.from("profile_top10_list_comments").insert({ list_id: list.id, user_id: state.session.user.id, parent_id: replyTo, body });
      if (result.error) toast("Não foi possível publicar o comentário.");
      else { form.reset(); await refresh(); }
      button.disabled = false;
    });
  }

  async function voteTop10Item(item, vote, controls, listOverride = null) {
    if (!state.session?.user?.id || !sb) return openAuthPage();
    const previous = { likes: item.likes || 0, dislikes: item.dislikes || 0, userVote: item.userVote || 0 };
    const nextVote = previous.userVote === vote ? 0 : vote;
    if (previous.userVote === 1) item.likes = Math.max(0, previous.likes - 1);
    if (previous.userVote === -1) item.dislikes = Math.max(0, previous.dislikes - 1);
    if (nextVote === 1) item.likes = previous.userVote === -1 ? previous.likes + 1 : previous.likes + (previous.userVote === 1 ? 0 : 1);
    if (nextVote === -1) item.dislikes = previous.userVote === 1 ? previous.dislikes + 1 : previous.dislikes + (previous.userVote === -1 ? 0 : 1);
    item.userVote = nextVote;
    updateTop10VoteButtons(item, controls);
    const card = controls.closest("[data-top10-list-card]");
    const list = listOverride || editableTop10Lists().find(entry => String(entry.id) === String(card?.dataset.top10ListCard));
    if (list) updateTop10Reason(list, card);
    const result = nextVote
      ? await sb.from("profile_top10_item_votes").upsert({ item_id: item.id, user_id: state.session.user.id, vote: nextVote }, { onConflict: "item_id,user_id" })
      : await sb.from("profile_top10_item_votes").delete().eq("item_id", item.id).eq("user_id", state.session.user.id);
    if (result.error) {
      Object.assign(item, previous);
      updateTop10VoteButtons(item, controls);
      if (list) updateTop10Reason(list, card);
      toast("Não foi possível registrar seu voto.");
    }
  }

  function bindTop10VoteControls(panel, allowVoting = false) {
    if (!panel) return;
    const lists = editableTop10Lists();
    $$('[data-top10-list-card]', panel).forEach(card => {
      const list = lists.find(entry => String(entry.id) === String(card.dataset.top10ListCard));
      if (!list) return;
      const sharedList = String(state.publicProfile?.top10ListId || "") === String(list.id);
      card.classList.toggle("is-shared-target", sharedList);
      if (sharedList && !$(".top10-shared-label", card)) {
        const title = $("h3", card);
        title?.insertAdjacentHTML("afterend", '<span class="top10-shared-label">Lista compartilhada</span>');
      }
      if (sharedList && card.dataset.sharedScrolled !== "true") {
        card.dataset.sharedScrolled = "true";
        requestAnimationFrame(() => card.scrollIntoView({ behavior: "smooth", block: "center" }));
      }
      const items = [...(list.items || [])].sort((a, b) => a.rank - b.rank);
      $$(".top10-item", card).forEach((row, index) => {
        if ($(".top10-vote-actions", row)) return;
        const item = items[index];
        if (!item?.id) return;
        const controls = document.createElement("span");
        controls.className = "top10-vote-actions";
        controls.dataset.top10VoteTarget = list.list_type === "story" ? "edition" : "character";
        const voteTarget = list.list_type === "story" ? "edição" : "personagem";
        controls.innerHTML = allowVoting
          ? `<button type="button" class="small-btn" data-top10-vote="1" aria-label="Curtir ${voteTarget}">👍 0</button><button type="button" class="small-btn" data-top10-vote="-1" aria-label="Não curtir ${voteTarget}">👎 0</button>`
          : '<span class="top10-vote-count" data-top10-vote="1">👍 0</span><span class="top10-vote-count" data-top10-vote="-1">👎 0</span>';
        const editActions = $(".top10-item-actions", row);
        if (editActions) editActions.prepend(controls);
        else $("strong", row)?.after(controls);
        updateTop10VoteButtons(item, controls);
        $$('button[data-top10-vote]', controls).forEach(button => button.addEventListener("click", event => {
          event.stopPropagation();
          voteTop10Item(item, Number(button.dataset.top10Vote), controls);
        }));
      });
    });
  }

  function bindTop10ListDragCards(panel, editable = false) {
    if (!panel || !editable) return;
    const container = $('[data-top10-panel]', panel) || panel;
    $$('[data-top10-list-card]', container).forEach(card => {
      if (card.dataset.top10ListDragBound === "true") return;
      card.draggable = true;
      card.dataset.top10ListDragBound = "true";
      card.addEventListener("dragstart", event => {
        if (event.target.closest("button, input, textarea, a")) return event.preventDefault();
        card.classList.add("is-list-dragging");
        event.dataTransfer.effectAllowed = "move";
        event.dataTransfer.setData("text/plain", card.dataset.top10ListCard);
      });
      card.addEventListener("dragover", event => {
        event.preventDefault();
        const dragging = container.querySelector(".top10-list-card.is-list-dragging");
        if (!dragging || dragging === card) return;
        const before = event.clientY < card.getBoundingClientRect().top + card.offsetHeight / 2;
        container.insertBefore(dragging, before ? card : card.nextSibling);
      });
      card.addEventListener("dragend", async () => {
        card.classList.remove("is-list-dragging");
        const orderedIds = $$('[data-top10-list-card]', container).map(item => String(item.dataset.top10ListCard));
        const lists = editableTop10Lists();
        const previousOrder = lists.map(list => String(list.id));
        const orderedLists = orderedIds.map(id => lists.find(list => String(list.id) === id)).filter(Boolean);
        if (orderedLists.length !== lists.length || orderedIds.every((id, index) => id === previousOrder[index])) return;
        orderedLists.forEach((list, index) => { list.sort_order = index; });
        const result = await Promise.all(orderedLists.map(list => sb.from("profile_top10_lists").update({ sort_order: list.sort_order }).eq("id", list.id).eq("owner_id", state.session.user.id)));
        if (result.some(response => response.error)) {
          lists.forEach(list => { list.sort_order = previousOrder.indexOf(String(list.id)); });
          render();
          toast("Não foi possível salvar a ordem das listas.");
        }
      });
    });
  }

  function syncTop10Labels() {
    $$('[data-shelf-media="top10"], [data-public-shelf-media="top10"]').forEach(button => { button.textContent = "Listas"; });
    $$('[data-top10-panel] > .section-head .section-title').forEach(title => { title.textContent = "Listas"; });
    $$('[data-top10-panel] > .section-head .section-subtitle').forEach(subtitle => { subtitle.textContent = "Crie listas personalizadas de personagens, histórias, favoritos ou qualquer tema."; });
    $$('[data-top10-new-list]').forEach(button => { button.textContent = "+ Nova lista"; });
    const lists = editableTop10Lists();
    const canEdit = state.section === "shelf" || (state.section === "public-profile" && String(state.publicProfile?.profile?.id || "") === String(state.session?.user?.id || ""));
    $$('[data-top10-panel] > .empty').forEach(empty => { empty.textContent = canEdit ? "Crie sua primeira lista para começar." : "Este perfil ainda não criou uma lista pública."; });
    $$('[data-top10-list-card]').forEach(card => {
      const list = lists.find(entry => String(entry.id) === String(card.dataset.top10ListCard));
      if (!list) return;
      const story = list.list_type === "story";
      const status = $(".section-head .shelf-visibility", card);
      if (status) {
        status.textContent = list.is_final ? "Definitiva" : "Mutável";
        status.classList.toggle("is-mutable", !list.is_final);
        status.classList.toggle("is-final", list.is_final);
      }
      if (canEdit && list.is_final) {
        $$('[data-top10-remove], [data-top10-move], [data-top10-edit-item]', card).forEach(control => control.remove());
        $(".top10-add-form", card)?.remove();
      }
      if (canEdit && !list.is_final && (list.items || []).length < TOP10_MAX_ITEMS && !$("[data-top10-search-list]", card)) {
        const searchLabel = story ? "história" : "personagem";
        card.insertAdjacentHTML("beforeend", `<div class="top10-add-form"><input type="search" placeholder="Digite o nome da ${searchLabel}..." aria-label="Buscar ${searchLabel} para ${escapeHTML(list.name)}" data-top10-search-list="${escapeHTML(list.id)}" autocomplete="off"><div class="top10-suggestions" data-top10-suggestions="${escapeHTML(list.id)}"></div></div>`);
      }
      const count = $(".section-head .section-subtitle", card);
      if (count) count.textContent = `${(list.items || []).length}/${TOP10_MAX_ITEMS} ${story ? "histórias" : "personagens"}`;
      let reason = $("[data-top10-reason]", card);
      if (!reason) {
        reason = document.createElement("span");
        reason.className = "top10-reason";
        reason.dataset.top10Reason = list.id;
        count?.after(reason);
      }
      updateTop10Reason(list, card);
      const cardHead = $(".section-head", card);
      if (cardHead && !$("[data-top10-comments]", card)) {
        const actions = document.createElement("div");
        actions.className = "top10-list-actions";
        actions.innerHTML = `<button type="button" class="small-btn" data-top10-comments="${escapeHTML(list.id)}">Comentários · ${list.comment_count || 0}</button><button type="button" class="small-btn" data-top10-share="${escapeHTML(list.id)}">Compartilhar</button>`;
        cardHead.append(actions);
      }
      const listActions = $(".top10-list-actions", card);
      if (status && listActions) listActions.prepend(status);
      const input = $("[data-top10-search-list]", card);
      if (input) {
        input.placeholder = `Digite o nome da ${story ? "história" : "personagem"}...`;
        input.setAttribute("aria-label", `Buscar ${story ? "história" : "personagem"} para ${list.name}`);
      }
      if (story) {
        const rankedItems = [...(list.items || [])].sort((a, b) => a.rank - b.rank);
        $$(".top10-item", card).forEach((row, index) => {
          const rankedItem = rankedItems[index];
          const storyEntry = state.db.library.find(entry => String(entry.id) === String(rankedItem?.character_key));
          const title = $("strong", row);
          if (!title || !storyEntry) return;
          title.classList.add("top10-story-title");
          title.textContent = rankedItem.character_name === top10StoryLabel(storyEntry)
            ? (storyEntry.title || itemDisplayTitle(storyEntry))
            : (rankedItem.character_name || storyEntry.title || itemDisplayTitle(storyEntry));
          const metadata = [storyEntry.issue ? `#${storyEntry.issue}` : "", storyEntry.year ? `(${storyEntry.year})` : ""].filter(Boolean).join(" · ");
          let metadataElement = $(".top10-story-meta", row);
          if (!metadataElement) {
            metadataElement = document.createElement("span");
            metadataElement.className = "top10-story-meta";
            title.after(metadataElement);
          }
          metadataElement.textContent = metadata;
          metadataElement.hidden = !metadata;
          const image = $("img", row);
          const storyCover = rankedItem.image_url || coverFor(storyEntry) || "assets/batmanicon.jpg";
          if (image && image.getAttribute("src") !== storyCover) image.src = storyCover;
        });
      }
    });
  }

  function top10Markup(lists = [], own = false) {
    const cards = lists.map(list => {
      const items = [...(list.items || [])].sort((a, b) => a.rank - b.rank);
      const itemMarkup = items.map((item, index) => {
        const setting = characterSettingForName(item.character_name || "");
        const image = item.image_url || setting?.cover_url || wikiCharacterImageCache.get(item.character_name) || "assets/batmanicon.jpg";
        return `<li class="top10-item"><span class="top10-rank">${index + 1}</span><img src="${escapeHTML(image)}" data-top10-character-image="${escapeHTML(item.character_name)}" alt="Imagem de ${escapeHTML(item.character_name)}" loading="lazy"><strong>${escapeHTML(item.character_name)}</strong>${own ? `<span class="top10-item-actions"><button class="small-btn" data-top10-move="up" data-top10-list="${escapeHTML(list.id)}" data-top10-item="${escapeHTML(item.id)}" ${index === 0 ? "disabled" : ""}>↑</button><button class="small-btn" data-top10-move="down" data-top10-list="${escapeHTML(list.id)}" data-top10-item="${escapeHTML(item.id)}" ${index === items.length - 1 ? "disabled" : ""}>↓</button><button class="small-btn danger" data-top10-remove="${escapeHTML(item.id)}" data-top10-list="${escapeHTML(list.id)}">Remover</button></span>` : ""}</li>`;
      }).join("");
      return `<article class="top10-list-card" data-top10-list-card="${escapeHTML(list.id)}"><div class="section-head"><div><h3>${escapeHTML(list.name)}</h3><div class="section-subtitle">${items.length}/${TOP10_MAX_ITEMS} itens</div></div>${own ? `<button class="small-btn danger" data-top10-delete-list="${escapeHTML(list.id)}">Excluir lista</button>` : `<span class="shelf-visibility is-public">${list.is_final ? "Definitiva" : "Mutável"}</span>`}</div><ol class="top10-items">${itemMarkup || '<li class="empty">Escolha itens para montar esta lista.</li>'}</ol>${own && !list.is_final && items.length < TOP10_MAX_ITEMS ? `<div class="top10-add-form"><input type="search" placeholder="Digite o nome do item..." aria-label="Buscar item para ${escapeHTML(list.name)}" data-top10-search-list="${escapeHTML(list.id)}" autocomplete="off"><div class="top10-suggestions" data-top10-suggestions="${escapeHTML(list.id)}"></div></div>` : ""}</article>`;
    }).join("");
    return `<section class="section top10-section" data-top10-panel><div class="section-head"><div><h2 class="section-title">Listas</h2><div class="section-subtitle">Crie listas personalizadas de personagens, histórias, favoritos ou qualquer tema.</div></div>${own ? '<button class="small-btn" data-top10-new-list>+ Nova lista</button>' : ''}</div>${cards || `<div class="empty">${own ? "Crie sua primeira lista para começar." : "Este perfil ainda não criou uma lista pública."}</div>`}</section>`;
  }

  function currentTop10Context() {
    const own = state.section === "shelf";
    return { own, lists: own ? state.top10Lists : (state.publicProfile?.top10Lists || []) };
  }

  function editableTop10Lists() {
    return state.section === "public-profile" ? (state.publicProfile?.top10Lists || []) : state.top10Lists;
  }

  function replaceEditableTop10Lists(lists) {
    if (state.section === "public-profile" && state.publicProfile) state.publicProfile.top10Lists = lists;
    else state.top10Lists = lists;
  }

  async function saveTop10Items(list, items) {
    const result = await sb.from("profile_top10_items").delete().eq("list_id", list.id);
    if (result.error) return result;
    return items.length ? await sb.from("profile_top10_items").insert(items.map((item, index) => ({ list_id: list.id, character_key: item.character_key, character_name: item.character_name, image_url: item.image_url || null, rank: index + 1 }))) : { error: null };
  }

  async function addTop10Character(list, key, name) {
      if (!list || list.is_final || !key || !name || (list.items || []).length >= TOP10_MAX_ITEMS) return;
    if ((list.items || []).some(item => item.character_key === key)) return toast("Esse personagem já está neste ranking.");
    const story = list.list_type === "story" ? top10StoryEntries().find(([entryKey]) => String(entryKey) === String(key))?.[2] : null;
    const items = [...(list.items || []), { character_key: key, character_name: name, image_url: story ? (coverFor(story) || null) : null }];
    await updateTop10Items(list, items, "Não foi possível atualizar o ranking.");
  }

  async function updateTop10Items(list, items, errorMessage) {
    const previousItems = list.items || [];
    state.top10Revision += 1;
    list.items = items.map((item, index) => ({ ...item, rank: index + 1, id: item.id || `top10-local-${Date.now()}-${index}` }));
    updateTop10Dom(list, previousItems, list.items);
    state.top10PendingOperations += 1;
    const result = await saveTop10Items(list, list.items);
    state.top10PendingOperations = Math.max(0, state.top10PendingOperations - 1);
    if (!result.error) return;
    list.items = previousItems;
    render();
    toast(result.error.message || errorMessage);
  }

  function updateTop10Dom(list, previousItems, nextItems) {
    const card = $(`[data-top10-list-card="${list.id}"]`);
    const listElement = $(".top10-items", card);
    if (!card || !listElement) return;
    const temporary = document.createElement("div");
    temporary.innerHTML = top10Markup([list], true);
    const nextRows = [...temporary.querySelectorAll(".top10-item")];
    const rowFor = item => nextRows.find(row => [...row.querySelectorAll("[data-top10-item]")].some(button => String(button.dataset.top10Item) === String(item.id)));
    const currentRows = new Map([...listElement.querySelectorAll(".top10-item")].map(row => {
      const button = row.querySelector("[data-top10-item], [data-top10-remove]");
      return [button?.dataset.top10Item || button?.dataset.top10Remove, row];
    }));
    nextItems.forEach(item => {
      let row = currentRows.get(String(item.id));
      if (!row) {
        row = rowFor(item);
        if (row) {
          listElement.appendChild(row);
          row.querySelectorAll("[data-top10-move], [data-top10-remove]").forEach(button => button.addEventListener("click", async event => {
            event.stopPropagation();
            const currentList = editableTop10Lists().find(entry => String(entry.id) === String(button.dataset.top10List));
            if (!currentList) return;
            const currentItems = [...(currentList.items || [])].sort((a, b) => a.rank - b.rank);
            const index = currentItems.findIndex(entry => String(entry.id) === String(button.dataset.top10Item || button.dataset.top10Remove));
            if (button.dataset.top10Remove) currentItems.splice(index, 1);
            else {
              const target = button.dataset.top10Move === "up" ? index - 1 : index + 1;
              if (index < 0 || target < 0 || target >= currentItems.length) return;
              [currentItems[index], currentItems[target]] = [currentItems[target], currentItems[index]];
            }
            await updateTop10Items(currentList, currentItems, "Não foi possível atualizar o ranking.");
          }));
        }
      }
      if (row) listElement.appendChild(row);
    });
    [...listElement.querySelectorAll(".top10-item")].forEach(row => {
      const button = row.querySelector("[data-top10-item], [data-top10-remove]");
      const id = button?.dataset.top10Item || button?.dataset.top10Remove;
      if (!nextItems.some(item => String(item.id) === String(id))) row.remove();
    });
    const empty = $(".empty", listElement);
    if (nextItems.length) empty?.remove();
    const count = $(".section-head .section-subtitle", card);
      if (count) count.textContent = `${nextItems.length}/${TOP10_MAX_ITEMS} itens`;
    const addForm = $(".top10-add-form", card);
    if (addForm) addForm.hidden = nextItems.length >= TOP10_MAX_ITEMS;
    bindTop10DragRows(listElement);
    ensureTop10EditButtons(card);
    styleTop10RemoveButtons(card);
    syncTop10Labels();
  }

  function bindTop10DragRows(container) {
    if (!container) return;
    container.querySelectorAll(".top10-item").forEach(row => {
      const control = row.querySelector("[data-top10-item]");
      if (!control || row.dataset.top10DragBound === "true") return;
      row.draggable = true;
      row.dataset.top10DragList = control.dataset.top10List;
      row.dataset.top10DragItem = control.dataset.top10Item;
      row.dataset.top10DragBound = "true";
      row.addEventListener("dragstart", event => {
        row.classList.add("is-dragging");
        event.dataTransfer.effectAllowed = "move";
        event.dataTransfer.setData("text/plain", row.dataset.top10DragItem);
      });
      row.addEventListener("dragover", event => {
        event.preventDefault();
        const dragging = container.querySelector(".top10-item.is-dragging");
        if (!dragging || dragging === row) return;
        const before = event.clientY < row.getBoundingClientRect().top + row.offsetHeight / 2;
        container.insertBefore(dragging, before ? row : row.nextSibling);
      });
      row.addEventListener("dragend", async () => {
        row.classList.remove("is-dragging");
        const list = editableTop10Lists().find(entry => String(entry.id) === String(row.dataset.top10DragList));
        if (!list) return;
        const orderedIds = [...container.querySelectorAll(".top10-item")].map(item => String(item.dataset.top10DragItem));
        const currentItems = [...(list.items || [])].sort((a, b) => a.rank - b.rank);
        const items = orderedIds.map(id => currentItems.find(item => String(item.id) === id)).filter(Boolean);
        if (items.length !== currentItems.length || items.every((item, index) => String(item.id) === String(currentItems[index].id))) return;
        await updateTop10Items(list, items, "Não foi possível reordenar o ranking.");
      });
    });
  }

  function ensureTop10EditButtons(scope = document) {
    scope.querySelectorAll?.('[data-top10-list-card] .top10-item').forEach(row => {
      const removeButton = $("[data-top10-remove]", row);
      if (!removeButton || $("[data-top10-edit-item]", row)) return;
      const editButton = document.createElement("button");
      editButton.type = "button";
      editButton.className = "small-btn";
      editButton.dataset.top10EditItem = removeButton.dataset.top10Remove;
      editButton.dataset.top10EditList = removeButton.dataset.top10List;
      editButton.textContent = "Editar";
      removeButton.before(editButton);
    });
  }

  function styleTop10RemoveButtons(scope = document) {
    scope.querySelectorAll?.('[data-top10-remove]').forEach(button => {
      button.textContent = "×";
      button.title = "Remover personagem";
      button.setAttribute("aria-label", "Remover personagem");
    });
  }

  function alignmentWikiCarouselMarkup(items, alignment, title, subtitle) {
    const entities = new Map();
    items.forEach(item => characterNames(item).forEach(name => {
      const entity = String(name || "").trim();
      const setting = state.characterSettings.get(publisherKey(entity));
      if (entity && setting?.character_alignment === alignment && !entities.has(publisherKey(entity))) entities.set(publisherKey(entity), entity);
    }));
    const entries = [...entities.values()].sort((a, b) => a.localeCompare(b, "pt-BR"));
    if (!entries.length) return "";
    const cards = entries.map(entity => {
      const setting = state.characterSettings.get(publisherKey(entity)) || {};
      const image = setting.cover_url || wikiCharacterImageCache.get(entity) || "assets/batmanicon.jpg";
      return `<button type="button" class="wiki-character-card" data-wiki-character="${escapeHTML(entity)}" aria-label="Ver ${escapeHTML(entity)}"><span class="wiki-character-image"><img src="${escapeHTML(imageProxyFetchUrl(image))}" alt="Imagem de ${escapeHTML(entity)}" loading="lazy"></span><strong>${escapeHTML(entity)}</strong></button>`;
    }).join("");
    return `<section class="section wiki-alignment-carousel-section"><div class="section-head"><div><h2 class="section-title">${escapeHTML(title)}</h2><div class="section-subtitle">${escapeHTML(subtitle)}</div></div></div><div class="wiki-character-carousel"><div class="wiki-character-track wiki-alignment-track">${cards}</div></div></section>`;
  }

  function alignmentWikiCarouselsMarkup(items) {
    return [
      ["hero", "Heróis", "Explore os heróis presentes nos quadrinhos."],
      ["villain", "Vilões", "Explore os vilões presentes nos quadrinhos."],
      ["antihero", "Anti-heróis", "Explore os anti-heróis presentes nos quadrinhos."],
      ["support", "Secundários e apoio", "Explore os personagens secundários e de apoio."]
    ].map(([alignment, title, subtitle]) => alignmentWikiCarouselMarkup(items, alignment, title, subtitle)).join("");
  }

  function imprintCharacterMarkup(items) {
    const characters = new Map();
    items.forEach(item => {
      const storyKey = String(item.seriesId || item.id || "");
      characterNames(item).forEach(name => {
        const character = String(name || "").trim();
        const key = character.toLocaleLowerCase("pt-BR");
        if (!character || isTeamCharacter(character) || isRedirectedCharacter(character)) return;
        if (!characters.has(key)) characters.set(key, { name: character, stories: new Set() });
        if (storyKey) characters.get(key).stories.add(storyKey);
      });
    });
    const entries = [...characters.values()].sort((a, b) => b.stories.size - a.stories.size || a.name.localeCompare(b.name, "pt-BR"));
    if (!entries.length) return "";
    const cards = entries.map(({ name, stories }) => {
      const setting = state.characterSettings.get(publisherKey(name)) || {};
      const image = setting.cover_url || wikiCharacterImageCache.get(name) || "assets/batmanicon.jpg";
      return `<button type="button" class="wiki-character-card publisher-character-card" data-wiki-character="${escapeHTML(name)}" aria-label="Ver personagem ${escapeHTML(name)}"><span class="wiki-character-image"><img src="${escapeHTML(imageProxyFetchUrl(image))}" alt="Imagem de ${escapeHTML(name)}" loading="lazy"></span><strong>${escapeHTML(name)}</strong><small>${stories.size} ${stories.size === 1 ? "história" : "histórias"}</small></button>`;
    }).join("");
    return `<section class="section imprint-characters-section"><div class="section-head"><div><h2 class="section-title">Personagens do selo</h2><div class="section-subtitle">Personagens que aparecem nas histórias deste selo.</div></div></div><div class="publisher-character-carousel" aria-label="Personagens deste selo"><div class="publisher-character-track">${cards}</div></div></section>`;
  }

  function characterSettingForName(name) {
    const key = publisherKey(name);
    return state.characterSettings.get(key) || [...state.characterSettings.values()].find(setting => publisherKey(setting?.character_name) === key);
  }

  function isTeamCharacter(name) {
    return characterSettingForName(name)?.character_type === "team";
  }

  function isRedirectedCharacter(name) {
    return Boolean(characterSettingForName(name)?.redirect_character_key);
  }

